window.RB_SHARDS=window.RB_SHARDS||{};window.RB_SHARDS[10]=[{"i":26083,"n":"כאביסא, אברהם מאלגיר","f":"שלמה","bt":"תרי","dt":"תרף - בערך","b":"רב באל אסנאם(=אורליאנויל)-אלגיר. ברשימת המסייעים בהדפסת \"בית שלמה\" ירושלים תרנה."},{"i":26084,"n":"כאהון","k":"ראה: נהון","b":"רב בטיטואן-ת\"ר"},{"i":26085,"n":"כאסכי, עזרא מחלב","dt":"תרכט - יז חשון","b":"רב בחלב-תריב אחיו של ר שלום."},{"i":26086,"n":"כאסכי, שלום מחלב","f":"חלפון","k":"בעל שלום לעם","dt":"תרלב - ה אלול","b":"דיין מחכמי חלב בזמן ר אברהם ענתבי ור חיים מרדכי לבטון בעל \"נכח השלחן\", עם ר חיים מרדכי לבטון ור שלמה נחמד. חתנו ר הלל דוד סתהון בעל \"ארוכה ומרפא\"."},{"i":26087,"n":"כארזשעלר, זאב מוארשא","b":"תלמיד ישיבת \"בית שמואל\" בוארשא. פרסם מאמרים ב\"בית שמואל\" - וארשא תרצו."},{"i":26088,"n":"כאשכיל, משה","f":"יוסף","b":"מחכמי עכו, במחצית השניה של המאה הי\"א."},{"i":26089,"n":"כביארה, חזקיה","b":"מחכמי צפת שעבר לחברון, בשנת שעה פנה לעזרת קהלות אלגיר בבקשת עזרה לחברון. מכתב ממנו לאחרים קנשינו באלגיר פורסם על ש. אסף ב\"קובץ על יד\" ג. ומבקש את עזרתם שהוצעה לו לפני שנים רבות עוד בהיותו בצפת."},{"i":26090,"n":"כגן, אברהם מתתיה הכהן מארה\"ב","f":"שמואל אריה","bt":"תרנב-ז","bp":"שנדובה","b":"נכד(-אבי אמו) ר יואל אליעזר פונק משניאדובא. תלמיד ישיבת לומזה, נוברדוק, מאלטש אצל ר דוד דינובסקי. בריינסק, ביהמ\"ד בברלין אצל ר חיים הלר, ונסמך ממנו ומאת ר י\"ל גורדון מלומזה. בעל תואר באוניברסיטה של ברלין. היגר לארה\"ב-תרפח וכיהן כרב בקורונה-לונג איילנד. חבר אגודת הרבנים באמריקה."},{"i":26091,"n":"כגן, בועז מארה\"ב","f":"משה אליהו מרגולה","b":"רב בארה\"ב."},{"i":26092,"n":"כגן, יהודה אריה ליב הכהן מארה\"","f":"שלמה אביגדור","k":"בעל הליכות יהודה","bt":"תרסד","bp":"יאנוב-פלך גרודנא","dt":"תשג - יח טבת","b":"נכד ר מאיר יוסף קטקין מיאנובה בעל \"פנים מאירות\". תלמיד ישיבות מיר, ראדין, סלובודקא, קלעם. נסמך מאת: ר חיים עוזר גרודזינסקי, ר צבי הירש קאמאי ממיר, ר אליעזר יהודה פינקל ממיר, ר חיים הליר, רמ\"א עמיאל מתל אביב. חתן ר יצחק קוסובסקי מיוהנסבורג בעל \"שבת ומועד\", וגיסו של ר חיים עוזר גרודזינסקי. רב בלאזדיי, רב באנטוורפן-תרצא, ליאון, שיקגו-תשג. פרסם מאמרים ב\"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה, \"המתיבתא\" - נ\"י תשג, \"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר, \"תלפיות\" - נ\"י תשד. אחיו (נקראו גרשטין: ר יעקב (אריה?) מלאזדיי הי\"ד, ר חיים ברוך הי\"ד מסמיאטיש, ר אלעזר הי\"ד מירושלים."},{"i":26093,"n":"כגן, יהודה ליב מצנסטחוב","b":"רב בית כנסת בצנסטחוב-תרצה."},{"i":26094,"n":"כגן, משה אליהו מראגולה ונ\"י","b":"הגיע מראגולה-ליטא לניו יורק וכיהן כרב בניו יורק. בנו ר בועז רב בארה\"ב."},{"i":26095,"n":"כגן, שלמה אביגדור הכהן","b":"חתן ר יוסף קטקין מיאנוב בעל \"פנים מאירות\". רב בירושלים-תרס. בניו - ר יהודה ליב כגן מארה\"ב, ר יעקב מלאזדיי הי\"ד, ר חיים ברוך מסמיאטיץ הי\"ד, ר אלעזר מירושלים הי\"ד."},{"i":26096,"n":"כגן, שמואל אריה משניאדובה","dt":"תש..","b":"חתן ר יואל אליעזר פונק משניאדובה-פלך לומזה. מחכמי שניאדובה. נספה בשואה. בנו - ר אברהם מתתיה מארה\"ב."},{"i":26097,"n":"כדורי, יצחק דיבה=זאב מירושלים","f":"כדורי","r":"ראש ישיבת נחלת יצחק","bt":"תרנד - בערך","bp":"בגדד","dt":"תשסו - כט טבת","dp":"ירושלים","b":"תלמיד הבן איש חי בבגדד, עלה לירושלים-תרפג. חתן ר יחקאל נקאש. מגדולי המקובלים בירושלים.","bk":[["דברי יצחק - שו\"ת",""],["פתחי עולם - קמעות סגולות ותפלות",""]]},{"i":26098,"n":"כדורי, ששון מבגדד","bt":"תרן","dt":"תשלא - כט אייר","dp":"בגדד","b":"מחכמי בגדד, תלמיד ר עבדאללה סומך. חכם באשי-תרפז, ודיין עם ר אברהם אצלן ור סלמן חוגי."},{"i":26099,"n":"כהן בצלאל בן ישראל משה","bt":"1820","dt":"ה'תרלח 1878","bk":[["ראשית בכורים",""]]},{"i":26100,"n":"כהן יעקב בן אברהם מג’רבה","bt":"1852","dt":"ה'תרסט 1909","bk":[["בכור יעקב",""],["גן יעקב",""],["מעיל יעקב",""]]},{"i":26101,"n":"כהן מאיר בן שמואל","bt":"1902","dt":"ה'תשלח 1978","bk":[["חלקת מאיר",""]]},{"i":26102,"n":"כהן סאסי","bt":"1912","dt":"ה'תשסד 2004","bk":[["פרוכת המסך",""]]},{"i":26103,"n":"כהן פורט-מנדולין, מנחם","dt":"שסב - י כסלו","b":"מרביץ תורה בויניציאה"},{"i":26104,"n":"כהן צדוק בן יעקב מלובלין","bt":"1823","dt":"ה'תרס 1900","bk":[["אוצר המלך",""],["אור זרוע לצדיק",""],["דברי סופרים",""],["דובר צדק",""],["הזכרונות",""],["ישראל קדושים",""],["לבושי צדקה",""],["מחשבות חרוץ",""],["מחשבת צדיק",""],["משיב צדק",""],["פוקד עקרים",""],["פרי צדיק",""],["צדקת הצדיק",""],["קומץ המנחה",""],["רסיסי לילה",""],["שיחת מלאכי השרת",""],["תפארת צב\"י",""],["תפארת צב\"י חלק א",""],["תפארת צב\"י חלק ב",""],["תקנת השבין",""]]},{"i":26105,"n":"כהן צדוק מפריס","bt":"1839","dt":"ה'תרסה 1905","bk":[["דברי צדוק הכהן",""],["העבדות",""]]},{"i":26106,"n":"כהן צדק גאון פומפודיתא","f":"יוסף","b":"גאון ישיבת פומפודיתא-ד'תרעז (917) על מקום ר יהודה בן שמואל גאון - זקנו של ר שרירא גאון. נבחר ע\"י הנשיא דוד בן זכאי, אך חכמי הישיבה בחרו בר מבשר כהנא לגאון, והיתה מחלוקת בישיבה כחמש שנים, עד שהוסכם שישמשו שניהם - כל אחד בישיבה אחרת. לאחר פטירת ר מבשר הוכר ר כהן צדק כגאון. היה בזמן ר סעדיה גאון בסורא (והיה מחלוקת ביניהם)."},{"i":26107,"n":"כהן צדק יוסף בן אהרן","bt":"1827","dt":"ה'תרסג 1903","bk":[["אור חדש",""],["אלף אלפין",""],["מוסר השכל",""],["נוה תהלה",""],["קדש הלולים",""],["שבת אחים",""],["שם ושארית",""],["תוספת קדושה",""],["תורה והמצוה",""]]},{"i":26108,"n":"כהן צדק מסורא","f":"איבומאי","b":"גאון סורא- 848, במשך כעשר שנים, על מקום ר משרשיא (משה) כהנא. תשובות ממנו בקובץ תשובות הגאונים - רובם בעברית (ולא בארמית) ורבות מהן בענין ברכות ונוסח התפלה. חיבר סדר ליל פסח. בין הכרעותיו -לומר אהבה רבה בשחרית ואהבת עולם בערבית."},{"i":26109,"n":"כהן צדק, אביגדור מוינה","k":"מגדולי הראשונים","b":"רב בוינה-שנת ל'"},{"i":26110,"n":"כהן צדק, אהרן מלבוב","f":"משלם מלמברג","dt":"תקצח","b":"תלמיד הקצות והחוות דעת. מחכמי למברג ויברוב. חתן דודו ר יהודה ליב מבוליחוב. דברי תורה ממנו בתוך המשניות שהוציא אביו עם פירוש \"עיקר תוי\"ט\"."},{"i":26111,"n":"כהן צדק, אליהו מברעזוב","f":"יצחק איזיק","dt":"תקצה","dp":"דינוב","b":"רב בברזוב."},{"i":26112,"n":"כהן צדק, בצלאל מלמברג","f":"משלם","bt":"תקם","dt":"תרח","b":"רב בלמברג על מקום אביו. חתן ר שמואל פילכנפלד מפוזנא."},{"i":26113,"n":"כהן צדק, דוד מלונדון","f":"יוסף מלמברג","k":"בעל תולדות הברון רוט","b":"רב בלונדון. עורך לצד אביו של \"אור תורה\" - לבוב, פרסם מאמרים בכתבי עת, הו\"ל \"המבשר\", \"הנשר\". חיבר \"תולדות הברון רוטשילד\", תולדות הרב ד\"ר אשער\"."},{"i":26114,"n":"כהן צדק, יהודה ליב","f":"בצלאל","k":"בעל בית יהודה אחרון","bt":"תקפח","dt":"תרמט","b":"רב בסאל. חיבר \"בית יהודה אחרון\" ושאגת ארי\" - בכתב יד."},{"i":26115,"n":"כהן צדק, יהודה ליב מבוליחוב","f":"יואל","bt":"תקכא","dt":"תקסב","dp":"מונקטש","b":"חתן ר מאיר חיות מטיסמניץ. רב בבוליחוב (בגיל 16), סטרי-תקמה. מדברי תורתו בספר אחיו \"פתחי נדה\"."},{"i":26116,"n":"כהן צדק, יואל מאטיניא","f":"יצחק איזיק","bt":"תפ","dt":"תקל","b":"חתן דודו ר דב בר מצורטקוב. רב באטיניא, סטניסלב (נספה בדרך לרבנותו שם)."},{"i":26117,"n":"כהן צדק, יוסף מלבוב","f":"אהרן","k":"בעל ישועות מלכי","bt":"תקפז","bp":"למברג","dt":"תרסד","dp":"לונדון","b":"בעל דפוס בלמברג, השתתף בכתבי עת רבים וכתב הקדמות לספרים. הו\"ל \"מגד ירחים\" למברג תרטז, \"אוצר חכמה\" - למברג תרך, \"היהודי הנצחי\" למברג תרכה, \"אור תורה\" פפד\"מ ולמברג תרכד. עבר לקראקא-תרכו, היה דרשן בפפדמ, פריז והולנד. רב בלונדון. חיבר \"ישועות מלכי\" למברג תריד, ועוד."},{"i":26118,"n":"כהן צדק, משלם מזורובנה וקוריץ","f":"יואל מאנטוני וסטניסל","k":"בעל עיקר תוי\"ט","bt":"תקיח","dt":"תקע - טו תשרי","dp":"לבוב","b":"חתן ר איציק מבוליחוב בן יחיאל מיכל באב\"ד מבילקמין. רב בזורובנא, קוריץ-תקמח על מקום אחיו בעל \"ברית כהנת עולם\", בוליחוב-תקלו, למברג תקנו. חתן ר יצחק באב\"ד מבוליחוב. חיבר \"פתחי נדה\" למברג תקנז, ועוד. הסכים על \"נחל אשכול\", חדושי מהר\"ם שי\"ף, \"נוית ברמה\"-למברג תקסא, \"שנות אליהו\" ועוד. רב בזוריינא, קוריץ על מקום אחיו ר יצחק איזיק בעל \"ברית כהנת עולם\",, בוליחוב,ראב\"ד בלבוב-תקנו. הו\"ל את כתבי אחיו עם הקדמות והוספות ממנו."},{"i":26119,"n":"כהן שבי, עזרא מירושלים","b":"מחכמי ירושלים-רע."},{"i":26120,"n":"כהן, אברהם ביג משלוניקי","b":"רופא צבאי בשלוניקי-תרס."},{"i":26121,"n":"כהן, אברהם דב בער הכהן ממצרים","f":"ישראל מרדכי","b":"רב במצרים, ירושלים-תרלז."},{"i":26122,"n":"כהן, אברהם יצחק מפיאסצנה","f":"שלום","k":"העילוי מפלעשצעניץ","bt":"תריב","bp":"פלעשצניץ-פלך מינסק","dt":"תרפג - אדר","b":"תלמיד ישיבת וולוזין, ר ירוחם פרלמן \"הגדול ממינסק\" המזכירו בספריו בשם \"חכם אחד\". חתן הגביר ר אברהם זאב רפפורט מפעלשצניץ. רב בפיסאצנע-פלך מינסק-תרמז, קרליץ(=קארעליטש)-פלך מינסק."},{"i":26123,"n":"כהן, אברהם מצייקישוק","dt":"תרנד","b":"רב בצייקישוק."},{"i":26124,"n":"כהן, אדולף מפרשבורג","b":"מג\"מ ומחברי אגודה \"עץ חיים\" - פרשבורג תרעא - ללימוד תורה של חבורה מחכמי פרשבורג."},{"i":26125,"n":"כהן, אהרן מירושלים","k":"בעל בית אהרן","b":"עלה לארץ תרפה, ר\"מ בישיבת חברון בירושלים. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה - ירושלים תשא."},{"i":26126,"n":"כהן, אהרן מנדל הכהן מקהיר","f":"נתן","k":"בעל אבל מצרים","bt":"תרכו","bp":"טבריה","dt":"תרפח","dp":"חיפה","b":"רב קהילת האשכנזים בקהיר-תרנז, ומחדש הסמיכה?, בשנת תרסא החל לפרסם קובץ \"כנסת הגדולה\", בתרפז הגיע לחיפה. כינס אסיפת רבנים בקראקא-תרסג לצורך חידוש הסמיכה. חיבר ספר \"אבל מצרים\" קהיר תרסט, \"כלילת חתנים\" קהיר תרע ועוד"},{"i":26127,"n":"כהן, אלחנן הכהן (סלנטר)","f":"יהודה ליב","k":"עורך תשובות לשואל","bt":"תרכט-לד","bp":"קופישוק","dt":"תרצו - כה תשרי","dp":"דוינסק","b":"תלמיד ר מאיר אטלס. חתן ר מרדכי אליאשברג. רב באסווטיאן(=פושויטין)-ליד יאנושק, ארמשט, סומי, דוינסק-תרפו על מקם ר מאיר שמחה בעל \"אור שמח\". הו\"ל \"תשובות לשואל\" לר אהרן שאול מאירוב מדוינסק עם חדושים והערות ממנו. הניח חבורים בכת\"י. בנו ר בנימין יהונתן. לפי יהדות ליטא נספה בשואה-תשא."},{"i":26128,"n":"כהן, אליהו","dt":"תרפד - כ טבת","dp":"ג'רבא","b":"מחכמי ג'רבא וטריפולי"},{"i":26129,"n":"כהן, אליעזר מארה\"ב","b":"פרסם מאמרים ב\"המתיבתא\" - נ\"י תשג."},{"i":26130,"n":"כהן, אפרים מירושלים","f":"אריה ליב","b":"מנהל ביהמ\"ד למורים \"עזרה\" ונשיא לשכת \"בני ברית\" בירושלים."},{"i":26131,"n":"כהן, בן ציון","k":"בעל שפת אמת","bt":"תשד","bp":"ג'רבא","dt":"תשנו","dp":"ירושלים","b":"חיבר \"שפת אמת\"","bk":[["שפתי כהן",""]]},{"i":26132,"n":"כהן, בנימין יונתן מדוינסק","f":"אלחנן מדוינסק","bt":"תרנב","bp":"פאשביץ","dt":"תשא-ג","b":"תלמיד ר שבתי קרמר מחרקוב, ישיבת פוניבז, מיר בהזמנת המשגיח ר ירוחם והיה מתלמידיו הקרובים. רב בשאבילן(=שאבלין)-קרולנד, דוינסק על מקום אביו (והיה רבה האחרון של העיר). נספה בשואה."},{"i":26133,"n":"כהן, בצלאל מארה\"ב","b":"פרסם מאמרים ב\"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה, \"כרם ציון\" - ירושלים תרצה-תשיג, תשכג - קובץ \"מדרש בני ציון\"."},{"i":26134,"n":"כהן, ברוך","bt":"תרכא","dt":"תרצג - ו תמוז","b":"רב בבריאנסק(ארה\"ב),עלה לא\"י-תרפ\"ג"},{"i":26135,"n":"כהן, ברוך יצחק מאנגליה","f":"חיים זוסמן מאנגליה","bt":"תרם","b":"נכד-אבי אמו ר יעקב ריינוביץ מלונדון. תלמיד ביהמ\"ד לרבנים בלונדון, ר\"א חייקין. רב בשפילד-תרסז"},{"i":26136,"n":"כהן, גרשון ממינסק","f":"אהרן","bt":"תקעט","dt":"תרן - כג טבת","dp":"מינסק","b":"עסקן מחכמי מינסק-תרמד בזמן הגדול ממינסק."},{"i":26137,"n":"כהן, דאני מגרבה","f":"אפרים","b":"פרסם מאמרים ב\"קרן דוד\" - גרבה תרעו."},{"i":26138,"n":"כהן, דוד","b":"חמיו של בעל \"משמרות כהונה\""},{"i":26139,"n":"כהן, דוד הנזיר מירושלים","b":"תלמיד הרב קוק. מחכמי ירושלים. נזיר."},{"i":26140,"n":"כהן, דוד מוילנא וירושלים","f":"אהרן","k":"בעל עיר דוד","b":"מחכמי וילנא, עלה לירושלים. חיבר 'זכרון כבוד לעיר דוד'."},{"i":26141,"n":"כהן, דוד מוינה","b":"רב ופרופ', ציר בחצר המלך פרנץ יוזף. חתנו - ר הלל הלוי וייס מארה\"ב."},{"i":26142,"n":"כהן, דוד מליטא","f":"ישראל יעקב","bt":"1901","bp":"יאנובה","dt":"1941","b":"מורה בת\"ת. צייר חובב, נסע לברלין ופריס ובשבו לליטא חזר ללמד והמשיך לצייר מחיי סביבתו הדתית. נספה בשואה."},{"i":26143,"n":"כהן, וילהלם מפרשבורג","b":"מנהל ביה\"ס של הקהלה החרדית בפרשבורג - לפני השואה."},{"i":26144,"n":"כהן, זאב אריה מוילנא","k":"בעל מסבות הפעל","b":"מדקדק, מאושר מטעם הממשלה להשכלת העם. חיבר גם \"מסבות השם\" וילנא תרנב - יחד עם דוד אליעזר ברנויץ.."},{"i":26145,"n":"כהן, זאב צבי מברלין","b":"פרסם מאמרים ב\"המגיד\" - סטמר תרפח."},{"i":26146,"n":"כהן, זלמן מנירנברג","k":"מהרז\"ך. בעל סדר גטין","b":"מגדולי הפוסקים בחכמי אשכנז,מרביץ תורה בנירנברג-קפ\"א"},{"i":26147,"n":"כהן, חי מג'רבה","k":"בעל כה לחי","dt":"תרעד","b":"מגדולי חכמי ורבני ג'רבא,אב\"ד ורב ראשי בנפצא,חיבר \"כה לחי\""},{"i":26148,"n":"כהן, חיים אורי מוילנא","f":"בצלאל מוילנא","k":"בעל דברי חיים","bt":"תריז","bp":"וילנא","b":"אחיינו של ר שלמה הכהן אב\"ד וילנא. תלמיד ישיבת איישישוק. נסמך מאת ר אליהו אליעזר גרודזנסקי, ור ראובן מדדנברג. דיין בוילנא-תרלו. חיבר גם \"מנחם ציון\" - הספד על ר יצחק אלחנן, \"בונה ירושלים\" - הספד על ר עזריאל הילסדהימר ור\"ש מוהליבר, \"אבן שלמה\" - הספד על דודו ר שלמה הכהן מוילנא."},{"i":26149,"n":"כהן, חיים זוסמן זאב ממנצסטר","dt":"תרסט - בערך","b":"חתן ר יעקב ריינוביץ מולקוביסק ולונדון. מו\"צ בקריסילין, רב במנצסטר-תרע, דיין בלונדון. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה, \"בית ועד לחכמים\" - לונדון תרסב. בנו - ר צבי-רב בלונדון."},{"i":26150,"n":"כהן, חיים יהודה מקרוטשוב","bt":"תריח","b":"רב בקרוטשוב-תר\"נ"},{"i":26151,"n":"כהן, חיים מגרבה","f":"וזיפה","b":"פרסם מאמרים ב\"מקבציאל\" - גרבה תרצה."},{"i":26152,"n":"כהן, חיים מתונס","k":"בעל שערי חיים","b":"מחכמי גאבס(טוניסיה),חיבר \"שערי חיים\"(בתוך ספרו של סבו ואביו \"כרם חמדה\")"},{"i":26153,"n":"כהן, חנניה ס\"ט","b":"פרסם מאמרים ב\"הנצנים\" - תל אביב תשא - קובץ תלמידי ישיבת הישוב החדש בת\"א."},{"i":26154,"n":"כהן, טוביה","b":"פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז."},{"i":26155,"n":"כהן, יהודה ליב","k":"בעל \"אידישע פאלקס לי","bt":"1881","bp":"וילנא","dt":"1937","b":"היגר לארה\"ב-1904. חוקר פולקלור של יהודי ליטא פולין ורומניה. קיבץ שירי עם יהודיים על ניגוניהם. חיבר גם \"יידישע פאלקס מעשיות\" נ\"י-וילנא 1931, ועוד."},{"i":26156,"n":"כהן, יהושע","f":"יהודה","k":"בעל בנין העם","bt":"תרנג","bp":"לאריסה-יון","b":"מורה בכי\"ח בבגדאד, התכונן לצאת לצנעא אך לא הספיק, מאזאנאן-מרוקו, עבר לפאריס, חזר לארץ-תרפו, בשליחות בבולגריה-תרפח, ציק הקק\"ל במרוקו וספרד. פרסם מאמרים שונים."},{"i":26157,"n":"כהן, יהושע מירושלים","b":"פרסם מאמרים ב\"תל תלפיות\" - ירושלים תשא."},{"i":26158,"n":"כהן, יואל בר","k":"בעל כבוד מלכים","bt":"1816","bp":"וולוזין","dt":"1871","dp":"וילנא","b":"חיבר גם \"חיי אסף\" - משלי אזופוס עם מבוא. פירוש לילקוט \"היכל רענן\" ועוד."},{"i":26159,"n":"כהן, יונה מראויטש","f":"בנימין","bt":"תרכא","b":"רב ברוויץ(=ראויטש)-תרמד."},{"i":26160,"n":"כהן, יוסף חי מתונס","f":"רפאל שלום","bt":"תרלט","bp":"ספאקס-תונס","dt":"תרצז - יא ניסן","dp":"ירושלים","b":"עלה לירושלים, מלמד בביהמ\"ד לרבנים של חברת \"העזרה\", מלמד תרבות צרפת, אספן בולים. בשליחות במרוקו, בגדאד, מצרים."},{"i":26161,"n":"כהן, יוסף מג'ירמוק","f":"סימן טוב ערב","bt":"תרלא","bp":"ג'ירמוק-תורכיה","b":"תלמיד חכמי חלב, ואצל ר יצחק בן אברהם אזולאי, מו\"ץ על מקום רבו (בחלב או בג'ירמוק)-תרמו, עלה לירושלים- וכיהן כרב עדת עולי ג'ירמוק, סויריק, ודיארביקיר בירושלים. דיין-תרפג אצל ר דוד פאפו, יחד עם ר שמואל פארדו."},{"i":26162,"n":"כהן, יוסף מגרבה","f":"יהודה","b":"פרסם מאמרים ב\"מקבציאל\" - גרבה תרצה."},{"i":26163,"n":"כהן, יוסף מטבריה וטריפולי","f":"נחום","bt":"תרך","dt":"תרץ - בערך","dp":"בנגזי-לוב","b":"מחכמי טבריה, עבר לבנגזי-לוב. נזכר אצל ר יוסף חיים ילוז."},{"i":26164,"n":"כהן, יוסף משלוניקי","b":"ממיסדי ה\"מזרחי\" בשלוניקי-תרעט."},{"i":26165,"n":"כהן, יעקב אליהו משלוניקי","b":"מנהל בביה\"ס ת\"ת בשלוניקי-לפני השואה."},{"i":26166,"n":"כהן, יעקב מזגערזש","k":"בעל ספר שירים","bt":"תרם","bp":"זעגרזש","b":"משורר. פרסם שירים ב\"המליץ\", ועוד."},{"i":26167,"n":"כהן, יעקב מפלורינה-יוון","b":"ראש הקהלה בפלורינה-יוון בזמן השואה."},{"i":26168,"n":"כהן, יצחק מטוקום","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":26169,"n":"כהן, יצחק מיון וירושלים","f":"יהודה","bt":"תרלד","bp":"לאריסה-יון","b":"עלה לירושלים, סייע ליהודי יון שגורשו לתורכיה, הקים שכונות בירושלים יחד עם חברו ישראל חכמשוילי."},{"i":26170,"n":"כהן, יצחק משה מדרום אפריקה","bt":"תרלו","b":"תלמיד ביהמ\"ד לרבנים בלונדון, בעל תואר ד\"ר. רב בבולאוואיא(=בולאביו)-דרום אפריקה-תרס. סייעו בידו: ר משה רבינוביץ-תלמיד ישיבת וולוזין, ר זיידל רבינוביץ."},{"i":26171,"n":"כהן, ישראל איסר מלייפציג","bt":"1858","bp":"נובהרדוק","dt":"1924","b":"עבר ללייפציג. מורה ב\"מכון היהודי\" של פרופ' דליטש. חוקר תלמודי בעל השפעה על תיאלוגים פרוטסטנטים שלמדו בלייפציג. תרגם לאידיש ספרי ירמיהו ותהלים. נזכר אצל פרופ' דלמן בהקדמתו לדקדוק העברי-ארמי, ואצל פרופ' לצרוס ב\"מוסר היהדות\", וע\"י פרופ' ר קיטל ב\"מבוא הרומי\" למהדורת התנ\"ך שלו, ע\"י פרופ' שנדרמן בהקדמתו ל\"התיאולוגיה היהודית\" לפ. ובר."},{"i":26172,"n":"כהן, ישראל מקאביליאק וירושלים","dp":"ירושלים","b":"רב בקאביליאק-תרמ. עלה לירושלים."},{"i":26173,"n":"כהן, לוי יצחק","b":"פרסם מאמרים ב\"קבוצי בחורים\" - מארגרטן תרצג."},{"i":26174,"n":"כהן, ליב מפרשבורג","f":"מנדל מפרשבורג","b":"בנו של מזכיר קהלת פרשבורג בזמן הכת\"ס. חיבר \"כתב יושר דברי אמת\" כנגד ר עקיבא יוסף שלזינגר שיצא כנגד הכת\"ס בענין המטיף - ר פייש פישמן - שדרש בגרמנית ובגלל המגדל שעל ביהכ\"נ. כנגדו יצאה חוברת \"תשובה מאהבה\" מר יהושע ברוך ריינץ מבאלקני, ומרבנים נוספים."},{"i":26175,"n":"כהן, ליבר מניו יורק","b":"פרסם מאמרים ב\"הפוסק\" - תל אביב תש-תשיד."},{"i":26176,"n":"כהן, ליפמן דובער מזוראויץ","f":"שמעון משה","bt":"תרה","b":"רב בזזוראוויץ-פלך מוהילוב-תרנה."},{"i":26177,"n":"כהן, מאיר גצל","b":"ניצל מהשואה והגיע לשנחאי-סין. פרסם מאמרים ב\"המתיבתא\" - נ\"י תשג, \"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי."},{"i":26178,"n":"כהן, מאיר מירושלים וארה\"ב","f":"ישראל","bt":"תרעב","bp":"ירושלים","b":"תלמיד ישיבת מאה שערים בירושלים, ישיבת חברון, נסמך מאת: ר איסר זלמן מלצר, ר יעקב משה חרלפ, ר יוסף גרשון הורביץ, ר יצחק יעקב וכטפויגל, רמ\"א עמיאל. חתן ר מנחם מרדכי פרנקל-תאומים מפילדלפיה. רב בפילדלפיה. חבר אגודת הרבנים באמריקה."},{"i":26179,"n":"כהן, מנדל מפרשבורג","b":"מזכיר קהלת פרשבורג-תרכג. בנו ר ליב בעל \"כתב יושר דברי אמת\"."},{"i":26180,"n":"כהן, מרדכי","bt":"תרטז","dt":"תרפג","b":"רב פעלים,מחכמי טריפולי,דיין בבנגאזי-תר\"פ"},{"i":26181,"n":"כהן, מרדכי דוד","b":"פרסם מאמרים ב\"כרם ציון\" - ירושלים תרצה-תשיג - קובץ \"מדרש בני ציון\"."},{"i":26182,"n":"כהן, מרדכי מרודאמין","dt":"תשג","b":"רב ברודאמין"},{"i":26183,"n":"כהן, משה זאב מפלוטל","f":"שאול","bt":"תרמז","b":"רב בפלאטל(=פלוטל)-פלך קובנא-תרעא."},{"i":26184,"n":"כהן, משה מבני ברק","b":"פרסם מאמרים ב\"תפארת ציון\" - בני ברק תשב - קובץ תלמידי ישיבת \"תפארת ציון\"."},{"i":26185,"n":"כהן, משה מוריס משלוניקי","k":"בעל איל אוניקו קאמינ","b":"סופר ועתונאי ציוני. חיבר בלאדינו \"איל אוניקו קאמינו(=הדרך היחידה) - סופיה תרפב."},{"i":26186,"n":"כהן, משה מליטא וארץ ישראל","f":"אברהם יצחק","bt":"1879","bp":"פלשצניץ-פלך מינסק","dt":"1952","dp":"ירושלים","b":"בנו של רבה של קארליץ. מזכיר \"המזרחי\" אצל הרב ריינס. מורה לעברית בישיבת לידא, מזכיר ועד הפליטים במינסק בזמן מלחה\"ע ה-I. עורך \"אונזער פריינד\" בוילנא, \"אידישע שטימע\" בקובנא-1923, \"הד ליטא\", ועוד. עלה לארץ-תרצה."},{"i":26187,"n":"כהן, משה נחמיה מדוואהרט","dt":"תריג - טז סיון","b":"תלמיד ר שמחה בונם מפשיסחא, ר יצחק מוארקי. רב בדווארט-תר."},{"i":26188,"n":"כהן, מתתיה מנחם מיון","k":"בעל ממך - בכת\"י","bt":"תריד","bp":"יאנינה-יון","dt":"תרפט - יג כסלו","dp":"אזמיר","b":"מחכמי אזמיר. חיבר ספר מ'מ'ך' בכת\"י - בידי בנו אלברט כהן מירושלים."},{"i":26189,"n":"כהן, נסים מגרבה","b":"פרסם מאמרים ב\"מקבציאל\" - גרבה תרצה."},{"i":26190,"n":"כהן, נפתלי","bt":"תרלב","dt":"תרצט - כג תמוז","b":"מרביץ תורה,רב בברגפרפך,מרבורג,ר\"מ בפולדא,עלה לא\"י"},{"i":26191,"n":"כהן, עמנואל","bt":"1864","bp":"טוקום-קורלנד","dt":"1941","dp":"ירושלים","b":"רופא ועסקן ציוני. התישב בוילנא-1892 והיה בועד ובבי ציון. השתתף בקבלת הפנים להרצל בוילנא. יו\"ר חברת \"מפיצי השכלה\". פעל להצלת יהודים בזמן פרעות הפולנים-1919 (הציל גם את ל. יפה). עלה לארץ-1923 והיה רופא בהדסה."},{"i":26192,"n":"כהן, עקיבא יוסף מירושלים","b":"פרסם מאמרים ב\"עטרת צבי\" - ירושלים תשא."},{"i":26193,"n":"כהן, פנחס מאנסבך","dp":"תשא","b":"רב באנסבך-תרנז-תרעז, מראשי ומיסדי אגודת ישראל בגרמניה, נשיא אגודת ישראל העולמית. עלה לארץ. עליו ב\"תקופות ואישים\" מאת שבתי שינפלד."},{"i":26194,"n":"כהן, פנחס מפרשבורג","b":"מראשי אגודת ישראל בפרשבורג-תרף. ממתנגדי הציונות. עלה לארץ."},{"i":26195,"n":"כהן, צבי הירש ממונטריאול","f":"חיים בן יהודה","bt":"תרכב-ה","bp":"בודוביץ-ליד וילקוביסק","dt":"תשי","b":"נכד ר יהודה בודיזעצער. תלמיד ישיבות וילנא, וולוזין. רב ועסקן בליטא, היגר לקנדה-תרן וכיהן כרב במונטריאול. נסמך מאת: ר יעקב דוד מסלוצק-הרידב\"ז. פעל בנושא החינוך היהודי בעירו. בזמן מלחה\"ע ה-I פעל לסידור יתומים יהודים מאוקראינה במשפחות יהודיות בקנדה, והשתתף בעזרה למהגרים. ראש ועד הרבנים במונטריאול-תשב, חבר אגודת הרבנים באמריקה וממיסדיה, ותנועת המזרחי פעל לעזרת יהודי אירופה וסייע לקלוט יתומים מאוקראינה בקנדה. פרסם מאמרים ב\"מרכז התורה\" - מונטריאול תשב."},{"i":26196,"n":"כהן, צבי הירש מפיורדא","f":"משה","k":"בעל אמרי צבי","bt":"תרלח","dt":"תרפא","dp":"ארץ ישראל","b":"רב פיורדא, חתנו של ר יעקב כהנא רבה של מאלטש, עלה לארץ ישראל. חיבר \"אמרי צבי\" וילנא תרנח."},{"i":26197,"n":"כהן, צבי מלונדון","f":"חיים זוסמן מלונדון","bt":"תרכט","b":"נכד-אבי אמו ר יעקב מוולוקוביסק ולונדון. תלמיד ביהמ\"ד לרבנים בלונדון. חתן ר יהודה לובצקי מפאריס. רב במערטיר טירוויל-וילס אנגליה-תרנ, נוטינגהם, לונדון. חיבר ספר דרשות - בכת\"י?"},{"i":26198,"n":"כהן, קולמן מפרשבורג","b":"שירת כקצין בצבא האוסטרי בזמן מלחה\"ע ה-I, ממארגני ההגנה היהודית בפרשבורג - בזמן הפרעות בסיום מלחה\"ע ה-I."},{"i":26199,"n":"כהן, ראובן","dt":"תשג"},{"i":26200,"n":"כהן, ראובן ליאון מארה\"ב","f":"אליעזר","bt":"1887","bp":"קובנא","b":"היגר בילדותו לארה\"ב ולמד ביולוגיה. היה ממפתחי \"מבחן כהן\" - בדיקת דם לגילוי מחלת העגבת."},{"i":26201,"n":"כהן, רחמים מג'רבה","k":"בעל יתדות החצר","bp":"ג'רבא","dt":"תשיח","b":"מחכמי ג'רבא. ספרו נדפס בתוך \"נטע רבעי\" תשלג. פרסם מאמרים ב\"קרן דוד\" - גרבה תרעו."},{"i":26202,"n":"כהן, רפאל מגרבה","f":"כלאלו","b":"פרסם מאמרים ב\"מקבציאל\" - גרבה תרצה."},{"i":26203,"n":"כהן, רפאל מריגא","dt":"תשג","b":"רב בריגא. פרסם מאמרים בתלמיד ישיבת חב\"ד באוטואצק. פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":26204,"n":"כהן, שלמה מבני ברק","b":"עורך \"השער\" - בני ברק תשח."},{"i":26205,"n":"כהן, שלמה מפאריס","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":26206,"n":"כהן, שלמה משלוניקי","b":"רופא צבאי בשלוניקי-תרס."},{"i":26207,"n":"כהן, שלמה ראובן מאודסה","k":"בעל תפילות הרמב\"ם","bt":"1889","bp":"אוראן-ליטא","b":"תלמיד ישיבות וילנא, קאלם, לידא ואודסה. רופא והסטוריון. מורה לעברית באודסה (אצל אוסישקין, זבוטינסקי, הרב טשרנוביץ, ועוד). רופא בקרים ובקווקז. פרסם מאמרים על נושאים תורניים וציוניים. היגר לארה\"ב-1922. חיבר גם \"תרומת היהודים למדע\", \"גורמי מחלות לפי ספרות התלמוד\"."},{"i":26208,"n":"כהן, שמואל דובער","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":26209,"n":"כהן, שמעון מצורביץ","b":"חתן ר אריה ליב האפט מקאנאטפ. מו\"ץ בצוראוויץ."},{"i":26210,"n":"כהן-בורשטין, מאיר משאטאווע ונ\"","f":"שמואל-מעדני שמואל","bt":"תרסב","bp":"שאטאווע","b":"תלמיד ר שלמה פולצוק, נסמך ממנו ומאת: ר ישראל גוטמן מקמניץ-פודולסק, רמ\"ז מרגליות, ר בנימין ארונוביץ, ר דב רעוועל. רב בשאטאווא על מקום אביו-תרעז, היגר לארה\"ב וכיהן כרב באסבורי פרק-ניו ג'רסי-תרף. פרסם מאמרים ב\"הפרדס\". חבר אגודת הרבנים באמריקה, תנועת המזרחי."},{"i":26211,"n":"כהן-ביסטריץ מאיר","bt":"1820","dt":"ה'תרנב 1892","bk":[["ביעור טיט היון",""]]},{"i":26212,"n":"כהן-קון, אברהם (אלברט) מצרפת","f":"שמשון","bt":"תקעד-ה","bp":"פרשבורג","dt":"תרלו - ד ניסן","dp":"ירושלים","b":"למד בביה\"ס של המשכילים בפרשבורג, תלמיד ר אליעזר הורביץ בוינה, למד באוניברסטיה בוינה, מחנך בבית רוטשילד בפאריס, גבאי צדקה של בית רוטשילד עלה לירושלים-תריד בשליחות משפחת רוטשילד, והיה נציגם בירושלים. שליחו של הברון רוטשילד בשלוניקי, לבדוק הקמת בתי ספר מודרנים בעיר, פעל גם למען יהודי מרוקו. אודותיו ב\"זעליג הויזדארף\"."},{"i":26213,"n":"כהנא יצחק זאב","bt":"1904","dt":"ה'תשכג 1963","bk":[["לתקנת עגונות",""],["ספר העגונות",""],["שמיטת כספים",""]]},{"i":26214,"n":"כהנא לוי יצחק","bt":"1889","dt":"ה'תשי 1950","bk":[["משאת בית הלוי",""]]},{"i":26215,"n":"כהנא נחמן בן חיים אריה","dt":"ה'תרסד 1904","bk":[["ארחות חיים",""]]},{"i":26216,"n":"כהנא שמואל זנויל","bt":"1906","dt":"ה'תשנח 1998","bk":[["רבנו משה בן מימון",""]]},{"i":26217,"n":"כהנא שמעון אריה בן שאול","bt":"1805","dt":"ה'תרלז 1877","bk":[["הגהות מהר\"שאך",""],["ספרי מהרשאך",""]]},{"i":26218,"n":"כהנא, אברהם אריה ליב מברדיטשו","f":"שלום שכנא מהורודנקא","k":"בעל אור הנערב","bt":"תק","dt":"תקמה-ח","dp":"פולנאה","b":"רב בברודי, ברדיטשוב, פולנאה-תקן. חתן ר מרדכי קע\"ט. חיבר \"אור הנערב\" אוסטרהא תקפד, \"דברי חמד\". בנו - ר שלמה בעל \"דברי שלמה\". אחיו: ר משה מנחם מנדל מזלוויץ, ר אהרן מזלוויץ."},{"i":26219,"n":"כהנא, אברהם דב מארה\"ב","f":"יעקב מאיר-מאור יעקב","bp":"לאשע-פלך מינסק","dt":"תשיח","b":"תלמיד ישיבות מיר, סלובודקא, סלוצק, שקלוב אצל ר מאיר שורץ. נסמך מאת: ר ברוך בר ליבוביץ, ר משה שמואל שפירא מבוברויסק, ר\"מ מסלונים, ר חיים עוזר גרודזנסקי, ר משה מרדכי אפשטין. רב ביכנ\"ס במינסק-תרעח, וילנא, ראש החנוך הדתי בוילנא בנשיאות רחיים עוזר, ויסד מוסדות וישיבות ובהם בתי אולפנא \"יבנה\", ממיסדי אגודת ישראל במינסק ובוילנא, היגר לארה\"ב-תרפד וכיהן כרב בניו יורק, פארק-ראקווי-תרפח. מזכיר אגודת הרבנים באמריקה. גיסו - ר דובער אפלמן מברונזויל."},{"i":26220,"n":"כהנא, אברהם הפייטן","b":"פייטן, חיבר פיוט \"שמעני וקח את מאמרי\", \"האל אשר המציא לכל נמצא\" עם פירוש ממנו."},{"i":26221,"n":"כהנא, אברהם יחיאל מיכל","f":"אלכסנדר זושא משדליץ","b":"בנו של בעל \"תורת כהן - יקר מפז\"."},{"i":26222,"n":"כהנא, אברהם מאוסטרהא ודובנא","f":"שלום שכנא כץ מקרקא","dt":"תצא-תצה","dp":"דובנא","b":"רב בברודי, אוסטרהא-תעח על מקום ר בצלאל כץ (בהסכמת ר נפתלי כץ-אביו של ר בצלאל - שהיה הסכם שלא ימנו באוסטרהא רב בחייו - ומחל וחתם על כתב הרבנות), דובנא (ברח מאוסטרהא-תפז או תפח בגלל הדוכס מושל העיר שנתן עיניו בבתו) על מקום ר יהושע בן אליעזר וגיסו ר שאול על מקומו אחריו. הסכים על \"דרש משה\" לר משה דרשן מקראקא-תעט, \"יפה מראה\"-תפד, ועוד. חתנו ר שאול בעל \"בנין אריאל\" על מקומו אחריו בדובנא. הסכים על \"קנין אברהם\" זולקוא תפג, \"יפה מראה\" אמשטרדם תפז, ועוד.נספד ב\"זכר החיים\" לר חיים רפפורט מלבוב. (כשהגיע בבריחתו לדובנא נשאל לאן הוא נוסע וענה שכתוב בתורה אצל הגר שנשאלה אי מזה באת ואנה תלכי וענתה מפני שרי אנכי בורחת - ומכאן שהבורח אינו יודע לאן פניו מועדות - ואז נתבקש מהם לכהן כרב בדובנא). בניו: ר יצחק משה מדובנא, ר ישראל מוישנביץ, חתנו - ר שאול מדובנא בעל \"בנין אריאל\". (יש אומרים שהיה בנו של ר שמואל ונכדו של ר שלום שכנא)."},{"i":26223,"n":"כהנא, אברהם מברודי ופולנאה","f":"שמואל","dt":"תקא","dp":"דובנא","b":"רב בברודי, אוסטרהא-תעח על מקום ר נפתלי כץ שעלה לארץ (ונאלץ לברוח בגלל שר העיר), דובנא על מקום ר זלמן אפרים (היה ביניהם פרק זמן שלא כיהן אב\"ד) ובנו ר יצחק משה על מקומו אחריו. חתנו - ר שאול מדובנא. נספד בספר החיים לר חיים רפפורט."},{"i":26224,"n":"כהנא, אברהם מברודי ופולנאה","f":"יצחק משה כהנא","bt":"תק","dt":"טו אדר","b":"חתן ר שאול מאמשטרדם בעל \"בנין אריאל\". רב בברסטיץ, לעת זקנה עבר לברודי. בנו - ר יעקב בעל \"גאון יעקב\"."},{"i":26225,"n":"כהנא, אברהם מואסליקוב וירושלים","f":"יעקב בן אברהם","dt":"תרכט - כג חשון","dp":"ירושלים","b":"רב בואסילקוב, ובכמה קהלות, עלה לירושלים. בנו - ר יעקב זאב דינזון-כהנא מפאסוואל בעל \"שארית יעקב\". מצאצאי ר אברהם מקרוז-אחי הגר\"א."},{"i":26226,"n":"כהנא, אברהם מוישניויץ ודובנא","f":"ישראל מליזנסק או זאב","b":"רב בווינוביץ(=וישנוביץ)-ווהלין, דומ\"צ בדובנא. הסכים על \"נחל אשכול\" דובנא תקסט. בנו - ר שמחה מקטירבורג. לפי שם הגדולים השלישי - שם אביו ר זאב אב\"ד וישנביץ."},{"i":26227,"n":"כהנא, אברהם עבר מקוזלוב","b":"רב בקוזלוב, מיקוליניץ."},{"i":26228,"n":"כהנא, אהרן אברהם","k":"בעל פרחי אהרן","bt":"תרכד","dt":"תרצו - כה שבט","b":"רב במיכלשוק(=מיכאילשוק), וואסאנש,סוויציאני,ר\"מ בראדין,הומען,עלה לא\"י תרפ\"א,ר\"מ בתל אביב"},{"i":26229,"n":"כהנא, אהרן מזלוויץ","f":"שלום שכנא מהורודנקא","dt":"תקלד - יב כסלו","b":"רב בזאלזיץ(=זלוויץ). אחיו: ר משה מנחם מנדל מזלוויץ, ר אברהם אריה מברדיטשוב בעל \"אור הנערב\"."},{"i":26230,"n":"כהנא, אהרן ממאסיף וסערט","f":"נחמן-ארחות חיים","k":"בעל וערך הכהן","dt":"תשד","b":"חתן ר חיים אלתר דאכנר ממאסיף וסערט. רב בסיטשל, ביסטרא, פטריווא. נספה בשואה."},{"i":26231,"n":"כהנא, אהרן מקזילוביץ","b":"רב בקזילוביץ"},{"i":26232,"n":"כהנא, אהרן מקרקוביץ","b":"אב\"ד קרקוביץ-תרע."},{"i":26233,"n":"כהנא, אלחנן","b":"שמש של ק\"ק אשכנזים בירושלים, חתם על כתב רבנות ר דוד אופנהיים בשנת תסז."},{"i":26234,"n":"כהנא, אליהו"},{"i":26235,"n":"כהנא, אליהו מוילנא","f":"יעקב מוילנא","dt":"תקפב - טו כסלו","dp":"וילנא","b":"נכד-אבי אמו ר ישכר בער-אחי הגר\"א."},{"i":26236,"n":"כהנא, אליעזר מקרלין","k":"בעל שיח ספונים","b":"רב בקרלין-תק. חיבר פירוש לחמש מגילות בשם \"שיח ספונים\" ונדפס - \"שירת דודים\" על שיר השירים, \"עמק הבכא\" על איכה, ועוד, חיבר גם \"טעמי תורה\" - זולקווא תקב."},{"i":26237,"n":"כהנא, אלכסנדר זושא משדליץ","f":"אברהם","k":"בעל תורת כהן - יקר מ","bt":"תקנה","dt":"תקצז - ו אד\"א","b":"תלמיד החוזה מלובלין, ר שמחה בונם מפשיסחא - וכתב את ספר רבו \"קול שמחה\", בנו ר אברהם משה מפשיסחא, ר יצחק מווארקי. רב בשדליץ-תקפו, פלאצק-תקצו. חיבר \"תורת כהן - יקר מפז\". בנו ר אברהם יחיאל מיכל כהנא."},{"i":26238,"n":"כהנא, אלתר אליעזר מזידיטשוב ים","f":"יוסף מאיר מספינקא ים","bt":"תרצז","dt":"תשסט","b":"חתן ר יעקב יוסף זיסוויין. תלמיד ישיבת ויזניץ. אדמור בירושלים. בקי בתחומים רבים ובהם מוסיקה, היסטוריה. מקורב לחסידות סטמר ו\"נטורי קרתא\"."},{"i":26239,"n":"כהנא, אריה ליב","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":26240,"n":"כהנא, אריה ליב מזרכניץ","f":"שמואל מדובנא או שלום","b":"רב בזדאבניץ(=זרכניץ). אחיו: ר אברהם מאוסטרהא וברוד ודובנא, ר מרדכי משידלוב, ר ישראל מליזנסק, ר שמואל מדובנא. (לפי שם הגדולים השלישי - אביו היה ר שלום שכנא מקראקא)."},{"i":26241,"n":"כהנא, אריה ליב מקלויזנבורג","f":"יצחק איזיק","k":"אפאהידער רב","bt":"תרכה","bp":"מונקטש","dt":"תשג - יא חשון","dp":"קלויזנבורג","b":"לאחר שנתייתם גדל אצל אביו חורגו ר יוסף ליב כהנא בסיגט תלמיד ר מנחם מנדל פאנט בדעש, ובעל \"ייטב לב\" בסיגט. חתן ר יחזקאל פאנט בעל \"כנסת יחזקאל\". רב בכפר אפאהידא-ליד קלויזנבורג, עבר לקלויזנבורג."},{"i":26242,"n":"כהנא, אריה פיבוש מקומרנא","f":"אהרן","dt":"תקסו - טז כסלו","dp":"ברודי","b":"רב בקומרנא, ברודי."},{"i":26243,"n":"כהנא, בן ציון מירושלים","dt":"תרעו","b":"רב בפלגוריא,עלה לירושלים"},{"i":26244,"n":"כהנא, בנימין זאב מלמברג","f":"שמואל זנויל","bt":"תרלז","bp":"דוקלא","dt":"תרפד","b":"חתן ר יצחק איזיק פופרש מברודי. עסקן בברודי, למברג . היה בידידות עם מהרם שפירא."},{"i":26245,"n":"כהנא, ברוך דוד מוישניצה","f":"לוי יצחק","k":"בעל חיבת הארץ","bt":"תרי","bp":"וישניצה","dt":"תרפד","b":"חתן ר שרגא פייטל. עלה לירושלים-תרלג, צפת - שם הקים קלויז צאנז. בשליחות בגליציה מטעם כולל צפת. חיבר \"חיבת הארץ\" ירושלים תרנז, ועוד."},{"i":26246,"n":"כהנא, ברוך מסטוטשין","b":"נכד הישמח משה. רבה הראשון של סטוטשין."},{"i":26247,"n":"כהנא, ברוך מקרלסבורג","f":"נחמן מספינקא ב\"ב","k":"אדמור מספינקא ארה\"ב","b":"אדמור מספינקא בארה\"ב."},{"i":26248,"n":"כהנא, דוד","k":"בעל תולדות המקובלים","bt":"1838","bp":"אודסה","dt":"1915","dp":"אודסה","b":"חוקר וסופר. פרסם בקובץ \"כנסת ישראל\"-תרמו, את ספר זכרונותיו של זקנו ר דוד בן מאיר הכהן מאודסה."},{"i":26249,"n":"כהנא, דוד הכהן מברוד","f":"משה - קרן אור","k":"בעל נפש דוד","dt":"תקנט - ל שבט","b":"רב בליטין, דומ\"צ בברוד. בנו - ר לוי כהנא מקאזין."},{"i":26250,"n":"כהנא, דוד מלמברג","f":"שלמה","k":"בעל יומן גיטו למברג","bt":"תרסג","bp":"הרימלוב","b":"דוקטור מאוניברסיטת וינה. רב בלמברג. חתן ר מרדכי אנגלרד. ניצל מהשואה על ידי ההגמון פשיטיצקי - ובמקום מחבואו תרגם את התורה לאוקראינית. עבר לוארשא אחרי השחרור ועסק בשיקום והצלה. עלה לארץ-תשי וכיהן כרב צבאי. רב בבואנוס איירס-תשכח. חיבר \"יומן גיטו למברג\" ירושלים תשלח."},{"i":26251,"n":"כהנא, דוד נפתלי הרץ מגוליגור","bt":"תרל","dt":"תש","b":"חתן ר אליעזר מישל מגוליגור. רב בטורקה-תרעב על מקום חותנו, רב בפמורן-תרץ."},{"i":26252,"n":"כהנא, הלל מסטניסלב","k":"בעל גלילות הארץ","bt":"תקפא","bp":"סטניסלב","dt":"תרסא - יז ניסן","b":"תלמיד ר משולם ישכר הורביץ מסטניסלב. עבר לבוטושאן והקים בה את בית הספר העברי הראשון. פרסם בכתב עת שונים. חיבר \"גלילות הארץ\" בוקרשט תרם."},{"i":26253,"n":"כהנא, זאב וולף מטשארנא","f":"שלמה אריה מעגעראש","k":"בעל אור לישרים","bt":"תרט","bp":"עגערעש","dt":"תש - יב אייר","dp":"טשאנרא","b":"תלמיד הכת\"ס, ומהר\"ם שיק, ור ישראל יצחק לנדסברג מגרוסורדין. חתן ר נתן נטע קולמן מטשארנא, ובזיוו\"ש חתן ר מרדכי רייכנפלד מיאנושהאזא. רב בשימאני-תרמא, טשארנא-תרמג על מקום חותנו, וחתנו ר אריה הברפלד על מקומו אחריו. חיבר \"שפתי כהן\" בסוף \"תל תלפיות\", ו\"אור לישרים\" בסוף \"מלחמת יהושע\" לחותנו זקנו. ?? לא באוצר ??"},{"i":26254,"n":"כהנא, חיים אריה מסיגט","f":"יחיאל צבי","k":"בעל דברי גאונים-תרל","bt":"1830","dt":"תרעז - כט שבט","dp":"סיגט","b":"נינו של \"קונטרס הספיקות\". תלמדי ה\"ייטב לב\" בסיגט. חתן ר צבי מדילאטין-גליציה, וגיסו של ר שלמה דרימר בעל \"בית שלמה\". דיין בסיגט אצל רבו ה\"ייטב לב\", והיה מסייע רבות לרבו (כולל השגת היתר מאה רבנים לבנו), אך אחר פטירת רבו היה במחלוקת עם בנו ר חנניה יו\"ט שהתנגד למינו ר נחמן בנו של ר חיים אריה לרבנות ספינקא, ובזמן הפילוג בקהלה עבר לצד הספרדים המתפלגים. היה בעל ספריה גדולה עם ספרים נדירים ובהם הרבה מהחכמים הספרדים, והשתמש בה לספרו \"דברי גאונים\" - שזכה להצלחה ונדפס שלש פעמים בחייו (הערות על ספרו ב\"עמק הלכה\" - דעש תרצב - מאת ר יצחק טיטלבוים מברדיוב). \"מפתח החיים\" - אונגואר-פרשבורג-מונקטש - תרפב.","bk":[["דברי גאונים",""]]},{"i":26255,"n":"כהנא, חיים בצלאל מקלויזנבורג","f":"אריה ליבוש מקלויזנבו","dt":"תשד","b":"נכד ר יצחק איזיק-חתן ר יחזקאל פנט מקרלסבורג. רב ביהמ\"ד \"עבודת כהונה\" בקלויזנבורג-תשג על מקום אביו. חתן ר עזריאל שוורץ מסטמר. נספה בשואה."},{"i":26256,"n":"כהנא, חיים ממארמארוש","f":"יהודה מנחם מסיגט","k":"בעל אבן שתיה-תרץ","dt":"תרפה - יד שבט","b":"חסיד קוסוב. דיין בכפר סלישט-מאמרמארוש. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד, ועוד. חיבר \"אבן שתיה\" על צדיקי בית קוסוב והשלים וערך ר חיים ישכר גרוס מפטריווה."},{"i":26257,"n":"כהנא, יהודה ליב מלויצק","f":"משה מלויצק","b":"רב בלויצק-תס על מקום אביו."},{"i":26258,"n":"כהנא, יהודה ליב מקידאן","f":"יחזקאל","b":"תלמיד ר שלמה לנדא מוילקומיר. רב בקידאן על מקום ר משה מרדכי קצנלנבוגן ור ראובן זקש על מקומו אחריו. גיסו - ר דב בער רבינוביץ מראסיין. חתם על שטר הרשאה-תקנח, עם הדיין מנחם נחום בן יחיאל מיכל מקידאן."},{"i":26259,"n":"כהנא, יהונתן בנימין מקלויזנבור","f":"שלמה יהודה","dt":"תרנ.. - בערך","dp":"ירושלים","b":"תלמיד הכת\"ס. מחכמי קלויזנבורג והיה לו בית מדרש פרטי, וכיהן כרב לא רשמי. בסוף ימיו עלה לירושלים. נזכר בספרי שו\"ת חכמי דורו."},{"i":26260,"n":"כהנא, יהושע","b":"פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":26261,"n":"כהנא, יהושע מלויצק","f":"ישראל כהנא","dt":"תקלה - ו סיון","b":"רב בלויצק"},{"i":26262,"n":"כהנא, יהושע מליזנסק","b":"רב בליזנסק-תק\"י"},{"i":26263,"n":"כהנא, יהושע מקראקא","f":"שלום שכנא כץ מקראקא","dt":"תצה","b":"ראב\"ד בקראקא על מקום אביו."},{"i":26264,"n":"כהנא, יוסף אלימלך מאונגוואר","f":"יצחק איזיק מהערנאד","k":"בעל פני יוסף","r":"רב דאונגוואר","bt":"תרכו","bp":"ראסלביץ(=ראסנביץ)","dt":"תשד - י סיון","dp":"אושוויץ","b":"תלמיד השב\"ס, זקנו-ר יצחק ביליצר מנאדי-אידא, ר חיים צבי מנהיימר מאונגואר, ור שלמה גנצפריד מאונגוואר. מקורב לאדמור\"י צאנז, מונקטש ובלז ועוד. חתן ר משה יונגרייז מקאשוי, ובזיוו\"ש חתן ר יאיר קאלוש ממזעאלאברץ. רב וראש ישיבה בהערנאד-שזאדאני(=הערנאדזשאדני)-תרנב על מקום אביו, בוניהאד(=בניהאד)-תרעז, צעהלים-תרפג, אונגוואר-תרצא. נשיא הלשכה האורטודוכסית בבודפשט. חתם על כרוז יחד עם הבישוף ד\"ר סטויה - לשמור על הצניעות בקרב המתרחצים בנהר אוג. נספה בשואה. חיבר גם \"פני יוסף\". פרסם מאמרים ב\"שערי אורה\" - מיהאלביץ תרץ-תרצד.","bk":[["חידושי מהרי\"א הכהן",""]]},{"i":26265,"n":"כהנא, יוסף מאיר מספינקא ירושל","f":"צבי בן נחמן","k":"אדמור מספינקא ירושלי","bt":"תרע","dt":"תשלח - ח שבט","b":"נינו של האדמור ר יוסף מאיר וייס מספינקא. נכד-אבי אמו ר יוסף מאיר מספינקא. חתן ר יצחק טיטלבוים מהוסקוב (שושלת אויהל), (או של החקל יצחק מספינקא). רב בסערדנא-תרצו, אדמור באונגוואר, עלה לארץ-תשא וכיהן כאדמור מספינקא בירושלים, והקים ישיבת \"אמרי יוסף\". בנו ר ברוך חתן ר יעקב לייזר מפעשוורסק-אנטורפן."},{"i":26266,"n":"כהנא, יוסף מדווטשר","k":"בעל חקירת בראשית","b":"רב בפוגאראש,דווטשר-תר\"י"},{"i":26267,"n":"כהנא, יוסף מרדכי","f":"פיבוש","b":"רב מדרגמרשטט-תר\"מ"},{"i":26268,"n":"כהנא, יוסף מרדכי מטעטש","f":"יחיאל צבי כהנא","k":"בעל דברי צדיקים","dt":"תרנו - יב סיון","b":"תלמיד בעל \"ייטב לב\", ור שמואל שמלקא מסעליש. רב ודומ\"צ בטעטש."},{"i":26269,"n":"כהנא, יחזקאל שרגא מצפת-ברוקלין","f":"נחמן מצפת","b":"תלמיד הדעת סופר, והעילוי ממיצ'ט בניו יורק. חתן ר ברוך שלום טריינין מדוינסק. רב בברוקלין. חיבר ספרים בעברית אידיש ואנגלית. וביניהם \"תורה ישרה\". בנו ר מאיר דוד שהקים את הליגה להגנה יהודית ור נחמן בעל \"מי מנוחות\". (שם אביו בגליציה - ברוך דוד מוישניצה)"},{"i":26270,"n":"כהנא, יחיאל מיכל מסיגט","b":"נכד בעל קונטרס הספקות. חתן ר לוי יצחק הורביץ מבלחוב. מחכמי סיגט. בנו - ר שמואל זנויל כהנא-פרנקל מבודפשט."},{"i":26271,"n":"כהנא, יחיאל מיכל מפודהייץ","b":"רב בפודהייץ-תרב."},{"i":26272,"n":"כהנא, יחיאל מסאלקה","f":"יהודה כהנא","dt":"תרו - יג אייר","b":"רב בסאלקה"},{"i":26273,"n":"כהנא, יחיאל צבי","f":"יוסף מרדכי כהנא","b":"רב בסיגעט-תר\"כ"},{"i":26274,"n":"כהנא, יעקב אליהו וילצקי מפלאוו","dt":"תרמח","b":"תלמיד הפרי מגדים, ור צבי הירש הלר. אב\"ד פלאוונא, טומשוב."},{"i":26275,"n":"כהנא, יעקב גדליה","f":"יחיאל צבי","k":"בעל רמזי תורה-תרלו","b":"נינו של בעל \"קונטרס הספיקות\". מחכמי סיגט."},{"i":26276,"n":"כהנא, יעקב מאיר מלאשע וניו יור","f":"אברהם דב הכהן","k":"בעל מאור יעקב","bt":"תרכ","bp":"מיר","dt":"תרצד - כח תשרי","b":"תלמיד ישיבות מיר אצל ר חיים ליב טיקטינסקי, וולוזין. רב בלאשע-פלך מינסק-תרמה, מינסק, פלונגיאן, מו\"צ בוילנא, ניו יורק-תרפד. נסמך מאת: ר ירוחם יהודה פרלמן - \"הגדול ממינסק\", ר הלל משקלוב וחסלביץ, ר יוסף רוזין מטלז וסלונים, ר שלמה הכהן מוילנא. בנו - ר אברהם דב מארה\"ב, חתנו - ר דב אפלמן מניו יורק."},{"i":26277,"n":"כהנא, יעקב מבוליחוב","b":"רב בבוליחוב-תריח."},{"i":26278,"n":"כהנא, יעקב מבריסק","b":"רב בקלויז בבריסק בזמן רבנות ר שלמה זלמן בן ירמיה יעקב, אב\"ד מוהילוב. נזכר בהקדמת אחיינו - ר יעקב כהנא מטיעשן - בספרו \"אהל יעקב\"."},{"i":26279,"n":"כהנא, יעקב מוילנא","f":"אברהם מברסטביץ","k":"בעל גאון יעקב","r":"מח\"ס מרא דמתניתא, תנא ירושלמי כת\"י","bt":"תקכד","dt":"תקפו - יט אד\"ב","dp":"וילנא","b":"נכד (אבי אמו) ר שאול מאמשטרדם. מצאצאי ר שלום שכנא מלובלין. חתן ר ישכר בער-אחי הגר\"א וישב אצלו. מגדולי חכמי וילנא, נאמן קהילת וילנא ומנהל עניני הצדקה. חיבר פירוש למסכת עירובין בשם \"גאון יעקב\" - המו\"ל ר רפאל נתן רבינוביץ - לבוב תרכג. בנו ר אליהו.","bk":[["גאון יעקב עירובין",""]]},{"i":26280,"n":"כהנא, יעקב מחצי-עמר","b":"אב\"ד חצי-עמר - תרנו. חתן ר מרדכי אשכנזי מפיסטין."},{"i":26281,"n":"כהנא, יעקב מצ'רנוביץ","dt":"ט כסלו","b":"דיין בטשרנוביץ(=צ'רנוביץ)."},{"i":26282,"n":"כהנא, יעקב מקולומיאה","b":"רב בקולומיאה-תרלח."},{"i":26283,"n":"כהנא, יעקב מראווא","b":"רב בראווא."},{"i":26284,"n":"כהנא, יעקב משניפישוק","b":"מרביץ תורה בשניפישק-תר\"כ"},{"i":26285,"n":"כהנא, יצחק איזיק","dt":"תשד","b":"רב בפאררא"},{"i":26286,"n":"כהנא, יצחק איזיק הכהן מרסנוביץ","f":"מאיר כהנא אלטשולר","dt":"תרנב - כא טבת","b":"רב בראסלביץ(=רסנוביץ), הערנאד-זשאדאני. חתן ר יצחק איזיק הלוי ביליצר מנאדי-אידא. אביו היה רבה של טשעטשאביץ. פרסם מאמרים ב\"אסיפת חכמים\" - אטוניא-בויאן תרע-תרעד."},{"i":26287,"n":"כהנא, יצחק מבריסק ופרמישלא","b":"דיין בפרמישלא, חתם-תמא על תקנה בועד ארבע ארצות בירוסלב עם ר יעקב בהר\"ש מקראקא, ר קלונימוס בן משה הקדוש מפוזנא, ועוד."},{"i":26288,"n":"כהנא, יצחק מדרוהוביטש","k":"בעל פני יצחק","b":"רב בדרוהוביטש. חיבר \"פני יצחק\" בכתב יד."},{"i":26289,"n":"כהנא, יצחק מירושלים","f":"יהודה ליב","k":"בעל תולדות יצחק","dt":"תרס - א אדר","dp":"ירושלים","b":"רב בסובאלק ובערים נוספות, עלה לירושלים-תריג, והיה מחכמי \"בית אל\". בשנת תרטז חתם בירושלים ב\"מעשה אבות\". חיבר \"תולדות יצחק\" ירושלים תרלד. בפטירתו אמר ר זלמן בהר\"ן להגאון מדוברובנא להספידו ולפרסם שהיה מל\"ו צדיקים שבדור."},{"i":26290,"n":"כהנא, יצחק מקראקא","b":"רב בקרקא"},{"i":26291,"n":"כהנא, יצחק מרדכי ממינסק וירושל","k":"בעל זכר לחיים","b":"מחכמי מינסק, עלה לירושלים בזמן השואה."},{"i":26292,"n":"כהנא, יצחק משה מדובנא","f":"אברהם מדובנא","dt":"תקה-ו","dp":"דובנא","b":"אב\"ד דובנא-תצה על מקום אביו ור שאול=חתנו של החכם צבי על מקומו אחריו. חתם על תקנות רבות בפנקס קהלת דובנא. גיסו - ר שאול."},{"i":26293,"n":"כהנא, ישראל יונתן בנימין","f":"שלמה יהודה הכהן","bp":"קראסנא","dt":"תרסט - כו אב","dp":"ירושלים","b":"תלמיד הכת\"ס, ור יצחק שמחה ברגר ממאדיאר לאפוש. חתן ר שמחה ליב. רב בקלויזנבורג-תרלא. עלה לירושלים-תרנו."},{"i":26294,"n":"כהנא, ישראל מבריסק","f":"יונה","b":"פרנס בבריסק, חתם-תקיב עם כמה מחבריו על מכתב לר יונתן איבשיץ בענין הקמיעות."},{"i":26295,"n":"כהנא, ישראל מוישנביץ","f":"אברהם מאוסטרהא ודובנ","b":"רב בוישנוויץ(=וישנביץ)."},{"i":26296,"n":"כהנא, ישראל מליזנסק","f":"שמואל או שלום שכנא מ","dt":"תקטו - ו חשון","b":"רב בליזנסק. בנו - ר אברהם מוישנוביץ."},{"i":26297,"n":"כהנא, ישראל מנאווריא וזולקוא","f":"מרדכי","k":"בעל בית ישראל","bt":"תקסא","bp":"ברודי","dt":"תרמא - יד שבט","dp":"זולקוא","b":"רב בנבריה(=נאווריא), זולקוא-תרא. חיבר \"בית ישראל\" זולקוא תריח."},{"i":26298,"n":"כהנא, ישראל מרוזינאי","dt":"תקנה - ג שבט","b":"רב ברוזינאי"},{"i":26299,"n":"כהנא, לוי הכהן","f":"דוד - נפש דוד","dt":"תקצז - יט חשון","b":"רב בקאזין. בנו - ר מאיר מטשטשעויץ."},{"i":26300,"n":"כהנא, לוי יצחק מארה\"ב","k":"בעל משאת בית הלוי","b":"רב בארה\"ב-תרצו."},{"i":26301,"n":"כהנא, מאיר מטשעטשביץ","f":"לוי כהן","bt":"תקנ","dt":"תרטז - כח ניסן","b":"רב בטשעטשעוויץ-תקע\"ז"},{"i":26302,"n":"כהנא, מנחם מהומענע","dt":"תשד","b":"רב בהומענע"},{"i":26303,"n":"כהנא, מנחם מנדל מזאלוזיץ","f":"שלום שכנא כהנא מהורד","b":"רב בזאלוזיץ-תק\"נ"},{"i":26304,"n":"כהנא, מנחם מנדל מזברז","bt":"תקפב","dt":"תרל","b":"רב בטויסט, זברז-תר."},{"i":26305,"n":"כהנא, מנחם מנדל מספינקא לונדון","f":"נחמן מספינקא ב\"ב","k":"אדמור מספינקא לונדון","b":"חתן ר דוד צבי שניבלג מויזניץ. אדמור מספינקא-תשמח בלונדון."},{"i":26306,"n":"כהנא, מנחם נחום","k":"בעל צמח מנחם","b":"רב בצערקוב-תק\"ע, מחותן עם ר מאיר גינצבורג מוילנא וגליל וויזון. חתנו - ר צבי הירש א\"ש. ?? לא באוצר ??"},{"i":26307,"n":"כהנא, מרדכי דוד מספינקא י-ם","f":"יוסף מאיר מספינקא ים","k":"בעל ברכת אבי","bt":"תרצא","b":"בן האדמור מספינקא. חתן ר משה מנחם הרשטיק. חבר מערכת \"אוצר הפוסקים\" בירושלים."},{"i":26308,"n":"כהנא, מרדכי מוילנא","b":"מחכמי וילנא, חתם-תמא בועד ירוסלב על תקנת קהלת זולקוא, עם ר קלונימוס בן משה הקדוש מפוזנא, ועוד."},{"i":26309,"n":"כהנא, מרדכי ממאהליב","f":"נתן נטע מאוסטרהא","b":"רב באמיסטיבווה, אפטא, מוהלוב-תמד. תשובה ממנו בשו\"ת מהר\"ם זיסקינד רוטנבורג."},{"i":26310,"n":"כהנא, מרדכי מנייהייזל","f":"נחמן - ארחות חיים","k":"אדמור מנייהייזל","dt":"תשד - כו סיון","b":"נכד האדמור מספינקא ר יוסף וייס. חתן ר אהרן וייס מבנדיקוביץ. רב בכפר קעכניא-מארמרוש, רב בפאביאנהאזא-הונגריה. אדמור בנייהייזל. נספה בשואה. הו\"ל \"ליקוטי תורה\" לזקנו בעל \"אמרי יוסף\" - סיגט תרנב."},{"i":26311,"n":"כהנא, מרדכי משידלוב","f":"שמואל או שלום שכנא","b":"רב בשידלוב-ת\"ק"},{"i":26312,"n":"כהנא, משה אליקים בריעה מספינקא","f":"נחמן מספינקא ב\"ב","k":"אדמור מספינקא ב\"ב","b":"אדמור מספינקא ב\"ב על מקום אביו."},{"i":26313,"n":"כהנא, משה הכהן מבלז","f":"יהודה ליב הכהן","k":"בעל קרן אור","b":"רב בבעלז-תקכ. חיבר גם \"מראה כהן\". בנו - ר דוד בעל \"נפש דוד\"."},{"i":26314,"n":"כהנא, משה זעירא מפרמישלא","f":"יוסף","b":"חתם בועד ירולסב-תנו בענין מדפיסי זולקוא, עם ר מנחם בן יוחנן ברוך מיונה, ועוד."},{"i":26315,"n":"כהנא, משה מאוסטרהא","f":"אהרן","dt":"תסד - ח טבת","dp":"אוסטרהא","b":"מחכמי אוסטרהא."},{"i":26316,"n":"כהנא, משה מאמסטיבאוו ווילנא","bp":"אמסטיבאוו","b":"תלמיד ר עקיבא איגר, מחכמי וארשא, וילנא. שאלה ממנו לר חיים מוולוזין."},{"i":26317,"n":"כהנא, משה מבוצאץ","b":"רב בבוצאץ."},{"i":26318,"n":"כהנא, משה ממאחניווקע","f":"ישראל","bt":"תרל","b":"רב במחנובקה(=מאחניווקע)-פלך קיוב-תרנו."},{"i":26319,"n":"כהנא, משה מנחם מנדל מזלוויץ","f":"שלום שכנא מהורודנקא","b":"אב\"ד זלוויץ. אחיו: ר אהרן מזלוויץ, ר אברהם אריה ליב מברדיטשוב בעל \"אור הנערב\"."},{"i":26320,"n":"כהנא, משה שמחה מסטניסלב","k":"בעל זכרון שמואל","b":"רב בסטניסלב-תרכט. חיבר \"זכרון שמואל\" בכתב יד."},{"i":26321,"n":"כהנא, משלם זוסיא מקמניץ-פאד","b":"רב בקמניץ-פאד. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד, \"הבונה\" - לבוב תרסד."},{"i":26322,"n":"כהנא, נחום מיכל מפלונגיאן","b":"רב בפולאנגן(=פלונגיאן)-תרלח על מקום ר יהושע הלר, שוקיאן."},{"i":26323,"n":"כהנא, נחמן מירושלים","f":"ברוך דוד","bt":"תרכט","b":"עלה לארץ עם אביו בילדותו. חתן ר משה יהודה יעבץ-מילר. עסק בקבלה עם ר יהושע פלאג'י."},{"i":26324,"n":"כהנא, נחמן מסיגט","f":"יהודה-קונטרס הספיקות","b":"דומ\"צ בסיגעט-תר. בנו - ר יוסף אריה מסיגט-חתן ר יחזקאל פנט מקרלסבורג."},{"i":26325,"n":"כהנא, נחמן מספינקא","f":"חיים אריה-דברי גאוני","k":"בעל ארחות חיים","r":"אבד\"ק ספינקא","bt":"תרכה","bp":"סיגט","dt":"תרסד - כח תמוז","b":"חתן ר יוסף מאיר וייס האדמור מספינקא. רב בספינקא-תרמד והיה מחלוקת על כך מצד בעל \"קדושת יו\"ט\" מסיגט והיתה מחלוקת בין חסידי סיגט לספינקא בגלל זה. בנו ר צבי על מקומו אחריו בספינקא. חיבר \"ארחות חיים\" שזכה להערכה רבה ומהרש\"ם מברעזאן, והאדר\"ת ממיר הוסיפו לספר הערות ותוספות. נפטר בחיי אביו.","bk":[["ארחות חיים – שו\"ע או\"ח",""],["דעת כהן",""]]},{"i":26326,"n":"כהנא, נחמן מספינקא","f":"צבי הירש מספינקא","k":"אדמור מספינקא בני בר","bt":"תרסה","bp":"ספינקא","dt":"תשלז - יז תשרי","dp":"ירושלים","b":"חתן דודו ר יעקב ישראל וישורון רובין האדמור מסוליציא. רב חסידי בקרלסבורג. ניצל מהשואה ואחריה דיין בקלויזנבורג ועסק בהתרת עגונות. עלה לארץ-תשי, וכיהן כרב המושב בני ראם, עבר לבני ברק וכיהן כאדמור מספינקא."},{"i":26327,"n":"כהנא, נתן זאנוויל מסיגט","f":"יוסף יוחנן","k":"בעל מלחמת התבל-תרעז","b":"נינו של בעל \"קונטרס הספיקות\". גביר מראשי הקהלה הספרדית בסיגט. חיבר \"מלחמת התבל באור היהדות\" ובו תמיכה בהתגיסות היהודים לצבא ההונגרי במלחמת העולם, ומתאר את מעללי הקוזקים כנגד קהלות ישראל בגליציה."},{"i":26328,"n":"כהנא, נתן נטע מאוסטרהא","f":"משה מרדכי","dt":"תיז או תמג","b":"נכד ר נתן נטע הכהן מברעזן וראש הישיבה בלבוב. ראש חכמי דורו, רב בירוסלב-שצב, אוסטרהא והגליל על מקום ר שמשון באך-אחרי שצו. ניצל מפרעות תח ותט. הסכים על ספר \"הש\"ך\", ועוד. (יתכן שהוא ר נתן בן משה שמזכיר שטינשנידר ב\"ספרות ישראל\" - שנהרג בידי התורכים בעיר אונגריש ברוד במורביה-תמג). בנו ר מרדכי ממאהליב, וחתנו ר משה חריף מפולנאה בן שלמה חריף מלבוב - ונכדו - ר משה חריף מלבוב. (אצל בובר מביא שיש אומרים שבנו גם ר וולף וחתנו - ר יוסף בן משה חריף מלבוב) מצאצאיו ר אהרן מטרבאלי בעל \"שם אהרן\", ו\"מקלו של אהרן\"."},{"i":26329,"n":"כהנא, פיבוש מווישיווה","f":"ישעיה","b":"מצאצאי בעל \"קונטרס הספיקות\". נכד ר חיים אריה כהנא בעל \"דברי גאונים\". רב בכפר אונטר-ווישיווה-תרפח על מקום ר יוסף מאיר ורצברגר. נספה בשואה."},{"i":26330,"n":"כהנא, צבי הירש מבלבירישוק","f":"אברהם","k":"בעל לקוטי רצב\"א","b":"רב בבלבירישוק, לאזדיי."},{"i":26331,"n":"כהנא, צבי הירש מדרבן","b":"רב בדרבן."},{"i":26332,"n":"כהנא, צבי הירש מטארפא","f":"נחמן כהנא","b":"רב בטארפא"},{"i":26333,"n":"כהנא, צבי הירש מספינקא","f":"נחמן-ארחות חיים","bt":"תרמד","dt":"תשד","b":"חתן ר ברוך רובין מבריזדאוויץ האדמור מקולומיאה. רב בספינקא-תרנט על מקום אביו. נספה בשואה. בניו: ר נחמן, ר יוסף עלו לארץ."},{"i":26334,"n":"כהנא, צבי הירש מקלוואריה","f":"פנחס חיים","b":"דיין בקלוואריה, חתם-תקצז עם הראב\"ד ר אריה ליב ברוידא, ועם ר אלתר בן יעקב ור משה בן יהודה."},{"i":26335,"n":"כהנא, צבי מסטרימטרה","f":"ישעיה מפטריווה","bt":"תרסד","bp":"כפר פטריווה-מארמארוש","dt":"תשה - כח טבת","dp":"אושוויץ","b":"מצאצאי בעל \"קונטרס הספיקות\" ר לוי יצחק מברדיטושב ועוד. תלמיד בעל \"קרן לדוד\" ור מנחם מנדל הגר בישיבת אויבר-ווישיווה. חתן הנגיד ר צבי יהודה באש מסטרימטרה. רב בסטרימטרה על מקום ר משה קיזלניק שער לריזאווליה, והקים שם ישיבת \"בית יעקב\". נספה בשואה. רוב כתביו אבדו וחלקם אצל חתנו ר חיים מאיר לוסטיג מניו יורק. פרסם מאמרים ב\"דגל התורה\" - אויבר-וישווה תרפח."},{"i":26336,"n":"כהנא, צבי מסיגט","f":"נחמן","k":"בעל אוצר יהודה-תרצא","b":"נכד בעל \"קונטרס הספיקות\". מחכמי סיגט וביבליוגרף. היה ספרן אצל ר משה יהודה דוידוביץ. חיבר \"אוצר יהודה\" רשימת הספרים של ר משה יהודה דוידוביץ מסיגט - כ-1870 ספרים. ?? לא באוצר - מופיע המחבר כבעל הספרים ולא הספרן ??"},{"i":26337,"n":"כהנא, צבי מספינקא לוס אנגלס","f":"מרדכי בן נחמן","k":"אדמור מספינקא לוס אנ","bt":"תרפג","b":"נינו של ר יוסף מאיר וייס מספינקא. חתן ר קלונימוס קלמן ליבמן מפולין. אדמור מבנדיקוביץ בלוס אנגלס, עבר לניו יורק."},{"i":26338,"n":"כהנא, קלמן","f":"בנימין זאב","bt":"תרע","bp":"ברודי","dt":"ה'תשמא 1981","b":"בעל תואר דוקטור מאוניברסיטת ברלין ווירצבורג. חתן ר ברוך קונשטט. ר\"מ בישיבת פולדא, עלה לארץ-תרצח ושימש כרב בקיבוץ חפץ חיים.","bk":[["חקר ועיון",""],["טהרת בת ישראל",""],["סדר תנאים ואמוראים",""],["שנת השבע",""]]},{"i":26339,"n":"כהנא, שלום שכנא כץ מקראקא","f":"אהרן מנחם כץ מקראקא","dt":"תמה - ז-יז סיון","dp":"קראקא","b":"מצאצאי ר יוסף כץ בעל \"שארית יוסף\". אביו נקרא \"ר מנדל ר זלמן חזנש\". חתן ר יהושע בן יוסף מקראקא בעל \"פני יהושע\" (ובאוצר הרבנים - חתן המגיני שלמה). מגדולי חכמי דורו, גביר, מרביץ תורה, מנהיג בקראקא. בניו ר שמואל כהנא מדובנא, ר יהושע הכהן מקראקא, ר אברהם כהנא מברוד ואוסטרהא, ר אריה ליב מזרכניץ, ר מרדכי משידלוב, ר ישראל מליזנסק. חתניו - ר מנחם רפפורט, ר נתן פייטל, ר אברהם עברל זלצבורג. אחיו: ר תנחום מקראקא, ר משה מקראקא."},{"i":26340,"n":"כהנא, שלום שכנא מהורדנקא","f":"אריה ליב כהנא","b":"רב בהורדנקא-תק. בניו: ר משה מנחם מנדל מזלוויץ, ר אהרן מזלוויץ, ר אברהם אריה ליב מברדיטשוב בעל \"אור הנערב\"."},{"i":26341,"n":"כהנא, שלמה דוד מירושלים","f":"בן ציון כהנא","bt":"תרכט","dt":"תשיד - כז כסלו","b":"חתן ר שמואל זנויל קלפפיש. חבר בועד הרבנים בוארשא-תרנה, עלה לירושלים-תש, רב בעיר העתיקה. פרסם מאמרים ב\"בית אברהם\" - וארשא תרצד, \"בית הכנסת\" - תל אביב תשו, \"מוריה\" - ירושלים תשג, \"הפוסק\" - תל אביב תש-תשיד."},{"i":26342,"n":"כהנא, שלמה דוד מפומורן","b":"רב בפומורן."},{"i":26343,"n":"כהנא, שלמה זלמן מאוסטרהא","f":"אברהם אריה-אור הנערב","k":"בעל דברי שלמה","dt":"תריב - יז אלול","dp":"אוסטרהא","b":"נכד ר שלום שכנא הכהן מקראקא. חתן ר אריה ליבוש אשכנזי-חתנו של הגביר ר אברהם אבלי מאוסטרהא. מחכמי אוסטרהא ומלמד תורה ומחבר הח\"ק-תקסה. נהג בחסידות ובפרישות (בפסח לא אכל מצה מלבד מצת החובה - מחשש חמץ). הו\"ל ספר אביו \"אור הנערב\". היה מחלוקת כנגדו מצד אנשים שלא רצה לכבדם מהיותו איש אמת."},{"i":26344,"n":"כהנא, שלמה מזולקוא","b":"מחכמי זולקוא, חתם-תעו בזולקוא שלא יהיו קרובי הרב בתוך מנהיגי הקהל."},{"i":26345,"n":"כהנא, שלמה מלובלין ובודון","b":"רב בבודון-שנות ה-ת'."},{"i":26346,"n":"כהנא, שלמה מסיגט","b":"שו\"ב בסיגט."},{"i":26347,"n":"כהנא, שמואל דוד מוארשא","b":"פרסם מאמרים ב\"בית שמואל\" - וארשא תרצו."},{"i":26348,"n":"כהנא, שמואל זנויל ממונקטש","f":"יהודה יעקב","k":"בעל זכרון שמואל","dt":"תרעה - כז ניסן","b":"דומ\"צ במונקאטש-תרסז וראש ישיבה. פרסם מאמרים ב\"בית שמואל\" - וארשא תרצו."},{"i":26349,"n":"כהנא, שמואל זנויל מסיגט","bp":"מאקאווא","b":"תלמיד ר מרדכי בנט. מגדולי סיגעט-תר\"כ. חתן בעל \"קונטרס הספיקות\". בנו - ר יהודה כץ-חתנו של ר יחזקאל פנט מקרלסבורג, חתנו - ר יהודה מודרן."},{"i":26350,"n":"כהנא, שמואל מדובנא","f":"שלום שכנא כץ מקרקא","dp":"תעט-פט - כה סיון","b":"מצאצאי ר יוסף כץ בעל שארית יוסף, ונכד ר אהרן מנחם-חתנו של הפני יהושע. ממנהיגי ועד ארבע ארצות-תנג, רב בניישטט, דובנא-תסט, עבר לברודי. הסכים על \"פני אריה זוטא\"-וילמשדורף תף. אבי משפחת כהנא בדובנא בנו - ר ישראל מליזנסק. (יש אומרים שבנו גם ר אברהם כהנא מאוסטרהא, אחרים אומרים שהיה אחיו). חתנו ר מנליש מקראקא ודובנא."},{"i":26351,"n":"כהנא, שמחה מזאשקוב","f":"שמואל","k":"בעל שלמי שמחה","bt":"תרלח","b":"נכד ר חיים רפפורט, ונכד ר אברהם כהנא-חתנו של ר שאול מאמשטרדם. רב בזשקוב-פלך קיוב-תרנט. נסמך מאת: ר\"מ לאקשובקא, ר חזקיה מדיני, רא\"י אבלסון מאודסה. חיבר שו\"ת בשם \"שלמי שמחה\" - בכת\"י."},{"i":26352,"n":"כהנא, שמחה מקאטירבארג","f":"אברהם מוישניויץ","b":"רב בקטיבורג(=קאטירבארד)-ווהלין-תקץ. בנו - ר שמואל מלכוביץ. ונכדו ר שמחה בורשטין מפראנפיל."},{"i":26353,"n":"כהנא, שמעון אלעזר מירושלים","b":"מראשי הכולל בירושלים-תרן."},{"i":26354,"n":"כהנא, שרגא פייב ממארגרטן","f":"יוסף אלימלך מאונגואר","k":"בעל דברי חן","bt":"תרנב","dt":"תרעט- יז ניסן","b":"תלמיד ר יהודה גרינוולד בסטמר. בגיל 13 פרסם חדושי תורה ב\"נטעי בחורים\" ובכתבי עת שונים. חתן ר שמואל זלמן וינברגר ממארגרטן וכיהן כרב אצלו במארגרטן, רסלביץ(=ראסנאויץ), זשאדאני. נסמך מאת: ר אברהם יצחק גליק בעל \"באר יצחק\", ר מרדכי פריד ממארטינסברג בעל \"ברוך מרדכי\". נזכר בחדושי מהרי\"א לאביו - ירושלים תשכט. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד. חיבר גם \"דברי שרגא\", ועוד."},{"i":26355,"n":"כהנא-בלומנפלד, יוסף מטוקום","f":"זאב וולף","b":"רבה הראשון של טוקום-תקסא, בהסכמת ר אבלי פוסוואלר."},{"i":26356,"n":"כהנא-פרנקל, שמואל זנויל מבודפש","f":"יחיאל מיכל מסיגט","bt":"תרן","dt":"תשל - יח אב","b":"תלמיד הדעת סופר. חתן ר אברהם מ\"ש-פרנקל מבודפשט נשיא הלשכה האורטודוכסית בהונגריה, רב על מקום חותנו-תרצז ניצל מהשואה, ואחריה המשיך כרב בבודפשט. עבר לניו יורק."},{"i":26357,"n":"כהנא-שפירא, אברהם אשר שמואל","f":"ישראל איסר מווידיסלב","k":"ראש\"י מזלין","bt":"תקמט","dt":"תריב - טו תמוז","b":"רב בזלין, שיניבה, עלה לירושלים-תרו, וקיבל מכתב המלצה מר צבי הירש מרימנוב."},{"i":26358,"n":"כהנא-שפירא, אברהם דב מקובנא","f":"שלמה זלמן סנדר ממאלץ","k":"בעל דבר אברהם","r":"רבה האחרון של קובנא","bt":"תרל-א","bp":"קוברין","dt":"תשג - כב אדר","dp":"סלובודקה","b":"נינו של ר חיים מוולוזין. תלמיד ישיבת ווולזין, גויס לצבא הרוסי ונשלח למינסק, ר ירוחם הגדול ממינסק שהכיר בגדולתו פעל לשחררו, ואח\"כ - חתן ר ירוחם ליב פרלמן - \"הגדול ממינסק\". רב בסמולוביץ-פלך מינסק-תרנו על מקום גיסו ר אליעזר רבינוביץ שעבר למינסק על מקום חותנם \"הגדול ממינסק\", אב\"ד קובנא-תרעג כ-30 שנה - והיה רבה האחרון, ונשיא אגודת הרבנים בליטא, בשליחות בארה\"ב-תרפד, עם ר משה מרדכי אפשטין מסלובודקה, והרב אברהם יצחק הכהן קוק. חיבר גם \"טהרת המשפחה\", \"דבר אברהם\", ועוד. נספה בשואה - בגיטו סלובודקה, בנו ר ירחם יהודה תיאר את פועלו בגיטו - בהקדמה לספרו. פרסם מאמרים ב\"יגדיל תורה\" - סלוצק-בוברויסק תרסט, \"הפלס\" - ברלין תרסא-תרסה. מאמר ממנו ב\"תלפיות\" - נ\"י תשד.","bk":[["דבר אברהם","מערכות"],["דבר אברהם - שו\"ת",""],["נאום על טהרת המשפחה",""]]},{"i":26359,"n":"כהנא-שפירא, אברהם יצחק","f":"רפאל יעקב מטורנא","b":"מחכמי ירושלים. חתן ר חיים רוטנברג (נכד אחיו של חדושי הרי\"מ), ונכדת הגר\"א, ובזיוו\"ש חתן ר משה שטיין."},{"i":26360,"n":"כהנא-שפירא, אברהם מירושלים","bp":"ירושלים","b":"תלמיד ישיבת חברון בירושלים. ראש ישיבת \"מרכז הרב\" בירושלים. פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח."},{"i":26361,"n":"כהנא-שפירא, אהרן שמואל","f":"עזריאל למל","b":"רב בשברשין-תפ\"ב"},{"i":26362,"n":"כהנא-שפירא, אליעזר נתן מירושלי","b":"חתם-תרכב עם ראשי הכוללות בירושלים על כתב שליחות ר נתן נטע נאטקין."},{"i":26363,"n":"כהנא-שפירא, אלעזר מירושלים","f":"אברהם אשר שמואל","bt":"תקצו","bp":"קראקא","dt":"תרעח","b":"עלה לירושלים-תרז עם אביו. ראש כולל גליציה והתעודות שהוציא עבור הקונסוליה האוסטרית הוכרו כרשמיות. חתם בתרכ\"ה אחרי ר מנדל צימטבוים ממישלניץ (שהיה נציגו של ר עזריאל הילדסהיימר). כיהן בועד השחיטה של המהרי\"ל דיסקין כנציג החסידים. בנו ר פנחס עסקן ומראשי כולל גליציה - גורש בתרעז לאנטוליה כנתין זר."},{"i":26364,"n":"כהנא-שפירא, דוד מקראקא","f":"מרדכי צבי מקראקא","bt":"תרסא","bp":"בזיסק","dt":"תשלא","b":"תלמיד ה\"אבני נזר\". חתן ר חיים יהושע גוטשטכר מוארשא ועבר לשם, והיה רב בגטו, ניצל מהשואה. רב בפיורדא כ-25 שנה. עלה לארץ-תשלא."},{"i":26365,"n":"כהנא-שפירא, חיים מקוזניצא","f":"שלמה זלמן סנדר ממאלץ","k":"בעל כרם חיים","bt":"תרלד","b":"נינו של ר חיים מוולוזין. חתן ר שמואל משה גוריצקי מקאפציווא. ר\"מ בקיבוץ בחורים במינסק, רב בקוזניצא-פלך גרודנא-תרסז. חיבר \"כרם חיים\" - בכת\"י."},{"i":26366,"n":"כהנא-שפירא, יהודה מקובנא","f":"שלמה זלמן סנדר ממאלץ","k":"בעל וזאת ליהודה","bt":"תרלח","dt":"תרף - כ אדר","b":"מצאצאי ר חיים מוולוזין. רב בקובנא-תרף. חתן ר מאיר אטלס משאוויל, גיסיו - ר אלחנן וסרמן, ר חיים עוזר גרודזנסקי. חיבר \"וזאת ליהודה\" ונדפס בסוף \"דבר אברהם\" לאחיו. נפטר ללא ילדים."},{"i":26367,"n":"כהנא-שפירא, יהושע יוסף מקראקא","f":"אברהם אשר שמואל","bt":"תקעד - בערך","dt":"תרעד"},{"i":26368,"n":"כהנא-שפירא, יחיאל מיכל מרדומיש","f":"משה","k":"בעל דעת נבונים","bt":"תרך","dt":"תרצה","b":"תלמיד ר נפתלי צבי מטורנא. מחשובי חסידי דזיקוב. חתן ר מרדכי הורביץ ממעליץ וישב אצלו. רב ברדומישל-תרנא, עבר למעליץ. חיבר \"דעת נבונים\" ירוסלב תרסח. פרסם מאמרים ב\"אהל מועד\" - פודגורזע תרנח, \"הירדן\" - רישא תרץ."},{"i":26369,"n":"כהנא-שפירא, יעקב","f":"משה כהנא שפירא","b":"רב-שנת תר\"ל"},{"i":26370,"n":"כהנא-שפירא, יעקב","f":"שלמה זלמן סנדר ממאלץ","k":"בעל נאות יעקב","b":"מצאצאי ר חיים מוולוזין. חתן הגביר ר אברהם יגל מפיעסק. רב-שנת תרף."},{"i":26371,"n":"כהנא-שפירא, יעקב אליהו ז'ילנר","f":"אברהם אשר שמואל","b":"חסיד ר אליעזר מנחם מנדל מללוב, חתם עם רבו על שטר בירושלים-(בין תרל לתרם). חתנו ר שלום גלרנטר מו\"ל \"כור לזהב\"-תרמה."},{"i":26372,"n":"כהנא-שפירא, יעקב מאיר","f":"צבי אשר מירושלים","bt":"תרנא","bp":"ירושלים","dt":"תשלא","b":"עבר לארה\"ב-תרפד וכיהן כראש ישיבת \"משכן ישראל\" בפילדלפיה, יסד את ישיבת \"יבנה\" בניו יורק עם אחיו ר נחום יצחק. חזר לירושלים-תשיא והקים את מכון מהרש\"ל עם בנו ר מנחם נחום. חתן ר אליעזר אריה ליבוש כהנא בעל דפוס בירושלים."},{"i":26373,"n":"כהנא-שפירא, יעקב מברודי ולבוב","f":"יצחק","b":"מחכמי ברודי, לבוב. חתנו - ר מרדכי הלוי בן יצחק מחעלמא. נזכר בהקדמת \"גבורת שאול\" לבן אחותו - ר שאול בן משה מלאמז."},{"i":26374,"n":"כהנא-שפירא, יעקב מטיטשין","f":"דוד","k":"בעל אהל יעקב","b":"רב וראש ישיבה בטיטשין-תס. נכד ר יצחק הכהן אב\"ד קראקא. חיבר \"אוהל יעקב\" פפד\"א תעט - הובא לדפוס ע\"י בניו: ר משה מעשיל מגיד מהרודישטש ור יצחק מטרעפולי (ליד בריסק)."},{"i":26375,"n":"כהנא-שפירא, יעקב ממאלטש","b":"רב במאלטש-תרנ\"ח"},{"i":26376,"n":"כהנא-שפירא, ישעיה מאיר","f":"יוסף בירך","k":"בעל חקירת ראשית","bt":"תקפח או תקף","bp":"ממל","dt":"תרמז","dp":"צ'ורטקוב","b":"עבר עם הוריו לסקול. חתן הגביר ר חיים אפיסדורף מצשינוב. מקורב לר מאיר מינץ, והיה מבאי ביתו של השו\"מ. עסק במסחר ביהלומים, ופרסם בכתבי עת, מיודד עם ר בנימין זאב וילר מירוסלב שישב בצשינוב אצל חותנו. רב בצורטקוב כיהן כמשנה לרב בצ'ורטקוב, ונאלץ להתפטר בגלל פעילותו להפצת השכלה. יצג זרם מתון בתנועת ההשכלה שניסה לשמור על המסורת ולהתאים את היהדות לזמן החדש (והיה מחלוקת עם החסידים שמינו את ר ברוך מאיר פריש, ועוד מחלוקת בין חסידי ויזניץ וסטרטין) כשהגיע האדמור ר דוד משה פרידמן - פוטר מתפקידו - אך נשאר בצורטקוב ופעל כרב בשאר הקהלה. בתשובה שכתב בנושא קו התאריך פסק כפי שפסק לימים החזון איש. למד באוני' והוסמך לרבנות. פרסם מאמרים ב\"המגיד\", \"הלבנון\", \"העברי\", ועוד. תומך ב\"חיבת ציון\", חבר ב\"אליאנס\", ובחברת מפיצי השכלה\". חיבר \"חקירת ראשית\" ליק תרלב, ספר זכרון - ובו מתנגד לתיקונים בדת ומסביר שהרבנים הם ביטוי לרצון העם לשמור על נכסי הרוח שלו. בנו דוד - רופא וסופר בדוינסק ונכדתו שרה משוררת עברית שנתפרסמה בשירה \"אל טל ואל מטר\"."},{"i":26377,"n":"כהנא-שפירא, מנחם נחום","f":"יעקב מאיר","b":"מיסד מכון מהרש\"ל עם אביו. ועומד בראשו. חתן ר דודו שלמה זלמן. עורך אוצר השו\"ת א\"י."},{"i":26378,"n":"כהנא-שפירא, מרדכי צבי מקראקא*","f":"משה נתן מקשונז","bt":"תרמ","b":"רב בקשונז על מקום אביו?, ברזיסק-פלך קיעלץ-תרנו. דיין בקראקא עם ר משה שמואל בלייכר ור ניסן כץ שנידר."},{"i":26379,"n":"כהנא-שפירא, משה אבלי הכהן","f":"אברהם אשר שמואל","b":"רב ברוהטין - תשובה אליו ב\"בית יצחק\"."},{"i":26380,"n":"כהנא-שפירא, משה הכהן מנישוועז","f":"יצחק?","k":"ר מושקה ר איציקס","b":"נכד-אבי אמו ר חיים מוולוזין. רב-שנת תר. בנו - ר יעקב מוולוזין ונכדו ר זלמן סנדר ראש ישיבת \"ענף עץ חיים\" במאלטש. (באוצר ובחכמי מינסק-איזנשטט - חתן ר חיים מוולוזין בזיוו\"ש - נשא את אלמנת ר יוסף סולוביציק)."},{"i":26381,"n":"כהנא-שפירא, משה נתן מקשונז","k":"בעל שמן למאור","bt":"תריב","dt":"תרצו","b":"תלמיד ר נחום זאב בעל 'אגודת אזוב'. חתן הגביר ר יעקב הנדלסמן מראדום ועבר לשם ולמד עם גיסו ר יואב יהושע וינגרטן בעל חלקת יואב. מלמד תורה בראדום ובמייכוב, לאחר שאיבד את רכושו רב בקשונז(=קשוינז)-פלך קיעלץ-תרס ובנו ר מרדכי צבי על מקומו אחריו, נתקבל לרבנות בלודז' אך סירב. מקורב לאדמור מסוכטשוב בעל אבני נזר, ובנו בעל שם משמואל היה חתנו בזיוו\"ש, חתנו גם - ר אליעזר צבי לונטל מטאלדש. מכתביו נדפס 'שמן למאור'. רוב כתביו אבדו בשואה."},{"i":26382,"n":"כהנא-שפירא, משה שלמה","f":"פנחס","k":"ירושלים","bp":"ירושלים","dp":"תרץ - ב אדר","b":"סופר ועסקן צבור בירושלים."},{"i":26383,"n":"כהנא-שפירא, נחום יצחק מירושלים","f":"צבי אשר מירושלים","k":"בעל ילקוט סיני","bt":"תרמב","bp":"ירושלים","dt":"תשכג","b":"למד בישיבות ירושלים, חבר של רי\"מ חרל\"פ ונסעו יחד ליפו למשך 20 שנה ללמוד אצל הראי\"ה קוק. נסע לר חיים מבריסק-תרעא, נשלח ע\"י החפץ חיים לירושלים לחיזוק הישיבות. בארה\"ב-תרעו, וכיהן כרב בסטמפורד, הקים ישיבת יבנה בניו יורק עם אחיו ר יעקב מאיר. שב לירושלים-תשטו ועמד בראש כולל מהרש\"ל (ר\"ת רבלין שפירא לעווי) שהקים אחיו. חתן ר יהושע זאב זיסנויין. חיבר \"ילקוט סיני\" ירושלים תשכג."},{"i":26384,"n":"כהנא-שפירא, עזריה למל","f":"יוסף הכהן","b":"רב-שנת ת\"נ"},{"i":26385,"n":"כהנא-שפירא, פנחס","f":"אלעזר מירושלים","bt":"תרכה","dt":"תרעח","dp":"וינה","b":"מראשי כולל גליציה לצד אביו. גורש כנתין זר בתרעז לאנטוליה."},{"i":26386,"n":"כהנא-שפירא, צבי אשר מירושלים","f":"שמואל יהודה מקראקא","k":"ריצב\"א - התורה והמצו","bt":"תריח - יב","bp":"קראקא","dt":"תרצח - יז שבט","dp":"ירושלים","b":"תלמיד רח\"נ דמביצר. עלה לירושלים-תרלג, מקורב לר מאיר אוירבך מקליש בירושלים. רב בשכונת הבוכרים, ר\"מ וראש ישיבה בכמה ישיבות. חתן ר שלמה זלמן לוי ממיסדי \"מאה שערים\". בשליחות-תרנז. חיבר \"התורה והמצוה\" ירושלים תרעג. בשנת תרלד חתם בפולמוס החצר. נכדו ר מנחם נחום הוציא \"חבל הכסף\" והוא ספר היחס ותולדות זקנו הרצ\"א."},{"i":26387,"n":"כהנא-שפירא, רפאל יעקב מטורנא","f":"יוסף צבי","dt":"תרסא","b":"חתן רבז\"ו לעזער מטורנא. בגללו בוטל המנהג בטורנא להדליק בחלונות ביום אידם."},{"i":26388,"n":"כהנא-שפירא, שלמה דוד","b":"תשובה אליו ב\"משיב כהלכה\"-תרא."},{"i":26389,"n":"כהנא-שפירא, שלמה הרץ מקראקא","b":"תשובה אליו ב\"שם עולם\"-תרלו."},{"i":26390,"n":"כהנא-שפירא, שלמה זלמן מירושלים","f":"צבי אשר מירושלים","bt":"תרמז","b":"חתן ר אהרן יהושע פישל זקס. בנו - ר אברהם אלקנה ראש ישיבת מרכז הרב והרב הראשי. פרסם מאמרים ב\"ועד חכמים\" - ירושלים תרפג, \"קול ישראל\" - ירושלים תרפא - ירחון חדו\"ת מאת \"צעירי אגודת ישראל בירושלים\"."},{"i":26391,"n":"כהנא-שפירא, שלמה זלמן סנדר","f":"יעקב בן משה","k":"בעל מסגרת זהב","bt":"תריא","bp":"קוברין","dt":"תרפג - כט שבט","dp":"ירושלים","b":"נכד ר משה כהנא-שפירא(=מושקה איציקס)-נכד ר חיים מוולוזין. תלמיד ישיבת וולוזין אצל ר יוסף דב סולובציק והתחנך יחד עם ר חיים סולוביציק. מחכמי קוברין, רב במאלטש-פלך גרודנא ויסד שם את ישיבת \"ענף עץ חיים\". עבר לקריניק-תרסג עם הישיבה. עלה לירושלים-תרפג וכיהן כנשיא אגו\"י. בניו: ר יעקב בעל נאות יעקב, ר אברהם דובער - אב\"ד קובנא-חתן הגדול ממינסק, ר חיים - רב בקוזניצה, ר יהודה-חתן ר מאיר אטלס. חיבר \"מסגרת זהב\" בכתב יד. פרסם מאמרים ב\"מאסף דרושי\" - וילנא תרסט, \"תבונה\" - קובנא תרפא. היה בידידות עם הגדול ממינסק (לימים מחותנו) - כאשר בצעירותו נסע לסעלץ במיוחד כדי לפוגשו. בניו: ר יעקב, ר אברהם דובער מסמאלעויטש-חתן ה\"גדול ממינסק\", ר חיים מקיזניצא, ר יהודה. חתנו - ר יעקב בלידשטין מחארשין-בן גיסו ר ברוך יוסף מאיליא.","bk":[["חידושי הגרז\"ס",""]]},{"i":26392,"n":"כהנוב אלעזר בן אורי מאיר","bt":"1917","dt":"ה'תשסב 2002","bk":[["זכרון בצלאל",""],["פרי הארץ",""],["תורת השביעית",""]]},{"i":26393,"n":"כהנוב, אורי מאיר מארה\"ב","k":"בעל פרי הארץ-תשיט","bt":"תרמג","bp":"רוסיה","dt":"תשך - ב שבט","dp":"ניו יורק - ירושלים","b":"ברח מרוסיה בגלל הגיוס לצבא והגיע להונגריה. תלמיד ישיבת צעהלים, עלה לירושלים ולמד בישיבת \"תורת חיים\" וחזר להונגריה, התישב בכפר סיטשל-מארמרוש-תרע, שו\"ב ורב בסיטשל. עבר להרמאנשטדט וניהל בה ישיבה. היגר לארה\"ב-תרפד וכיהן כר\"מ בישיבת \"תורה ודעת\". פרסם מאמרים ב\"כרם ציון\" - ירושלים תרצה-תשיג, תשכג - קובץ \"מדרש בני ציון\".","bk":[["משמרת הכהנים",""]]},{"i":26394,"n":"כהנוב, אליהו מירושלים","f":"פיבל","bt":"תרמג","bp":"ירושלים","b":"מנהל בית הספר \"התורה והמלאכה\" בירושלים."},{"i":26395,"n":"כהנוב, דוד הכהן מארה\"ב","f":"יהושע","bp":"באקי-פלך קיוב","b":"נכד (אבי אמו) ר משה נחום ירושלימסקי מקיעלץ. תלמיד ישיבת נוברדוק, סלובודקא, סלוצק. נסמך מאת: ר איסר זלמן מלצר, ר משה מרדכי אפשטין, ר ברוך בר ליבוביץ, ר מרדכי אריה באראשענקא מזועניגראדקא, ר פישל מאומאן. חתן ר פנחס דראזנע. רב בטולנא-תרפב, גייטין-פלך פודוליה-תרפד, היגר לארה\"ב-תרפט וכיהן כרב ור\"מ בשיקגו. חבר אגודת הרבנים באמריקה ותנועת המזרחי."},{"i":26396,"n":"כהנוב, משה נחמיה מירושלים","f":"משלם פייבל","k":"בעל נתיבות שלום","r":"רב בחסלויטש ועוד ר\"י עץ חיים","bt":"תקעז","bp":"קוסטיוקוביה (רייסן)","dt":"תרמז - ב סיון","dp":"ירושלים","b":"ראב\"ד בפטרוביץ-תרסה, חסלביץ-רייסן(=רוסיה הלבנה) ור ליפא יו\"ט הלפרין בעל \"מלבושי יו\"ט\" על מקומו אחריו, עלה לירושלים-תרכג-ה והיה מראשי ישיבת \"עץ חיים\". חיבר \"נתיבות שלום\" קניגסברג תריט, \"אבל משה\" - הספד על מוטיפיורי - ירושלים תרמה, ועוד. פרסם מאמרים ב\"שמעתתי דרבנן\" - אודסה תרמז. (לא היה כהן)","bk":[["נתיבות השלום",""],["ארץ חפץ – תרו\"מ",""],["חוקות עולם – כלאים",""],["נתיבות השלום – שו\"ע",""],["שאלו שלום ירושלים",""],["שנת השבע - שמיטה",""],["שפתי ישנים - צוואה",""]]},{"i":26397,"n":"כהנוביץ, ישראל יצחק מקנדה","b":"רב בויניפג-קנדה."},{"i":26398,"n":"כהנוביץ, צבי","b":"פרסם מאמרים ב\"תל תלפיות\" - ירושלים תשא."},{"i":26399,"n":"כהנמן, יוסף שלמה מפוניבז וב\"ב","f":"יהודה ליב","r":"רב וראש ישיבת פוניבז'","bt":"תרמו","bp":"קול-ליטא","dt":"תשכט - כ אלול","b":"תלמיד ישיבות ז'ידיק, פולונגיאן, טלז, נוברדוק והיה יד ימינו של בעל \"ערוך השלחן\", וסייע בהשלמת חיבורו, ורב על מקומו אחריו - ע\"פ צוואתו של הרב. עבר לראדין והתקרב לחפץ חיים. חתן ר ליב רובין מווידז, רב בווידז על מקום חותנו והקים שם ישיבה. בזמן מלחה\"ע ה-I היה בקוטלוניאן ופעל אצל הגרמנים למען היהודים שבאזור הכיבוש, ובזכות פעילותו חודש הישוב היהודי בפונוביז. רבה האחרון של פוניבז-תרעט על מקום ר יצחק יעקב רבינוביץ והקים ישיבה ומוסדות לנוער ולבנות. נבחר כציר ב\"סיים\" הליטאי, וחבר באגודת הרבנים בליטא, פעיל באגו\"י. ביקר בארץ-תרצה, עלה לארץ-תש - רוב בני משפחתו נשארו בליטא ונספו בשואה. הקים ישיבת פונוביז בבני ברק, ועוד מוסדות ליתומים לילדים ומוסדות חשובים נוספים. חידש את כינוסי \"ירחי כלה\". בנו - ר אברהם - ר\"מ בישיבה.","bk":[["דברי הרב",""],["חי' הגאון מפוניבז' (הרב מפוניבז')",""],["חידושי הגאון מפוניבז'",""]]},{"i":26400,"n":"כהנר מיאזנא","b":"רב ביאזנה."},{"i":26401,"n":"כואיף, אפרים"},{"i":26402,"n":"כובשי, שלום מתימן","b":"רב בקוזיה אלמחאבשה-תימן - בתחילת המאה ה-20."},{"i":26403,"n":"כוגהין, יוסף מבוכרה","f":"יצחק","bt":"תרז","bp":"קוקאנד-טורקסטן","dt":"תרפד - תשרי","dp":"ירושלים","b":"עלה לירושלים פעיל צבור בעדה הבוכרית בירושלים, חזר לבוכרה והיה פעיל ציוני, חזר לארץ והתישב בחדרה."},{"i":26404,"n":"כודיידאתיף, אבא","b":"מחכמי בוכארה, דיין-תר\"ס"},{"i":26405,"n":"כוכבי דוד בן שמואל; בלוי משה יהודה","bt":"1912","dt":"ה'תשסג 2003","bk":[["ספר הבתים",""]]},{"i":26406,"n":"כוכבי, דוד","k":"בעל בית אל","b":"נזכר אצל ר מנחם די לונזנו בעל \"אור תורה\", חיבר גם \"מגדל דוד\"."},{"i":26407,"n":"כוכבי, דוד מפרובנס","k":"בעל ספר הבתים","dt":"ק","b":"מגדולי חכמי פרובינצה,דיין באביניון"},{"i":26408,"n":"כוכבי, מאיר","b":"מגדולי הפוסקים בצרפת-שנת ס'"},{"i":26409,"n":"כולי - משפחה","f":"יעקב","bt":"תקפ","bp":"טיטואן","dt":"תרמו","dp":"חיפה","b":"רב בטיטואן, עלה בשנת תרך והיה רב בטבריה, בשנת תרמא אב\"ד וראש ישיבה בחיפה."},{"i":26410,"n":"כולי, דוד מקושטא","b":"מגדולי חכמי קושטא-ש\"ז"},{"i":26411,"n":"כולי, יהודה מירושלים","f":"יעקב - מעם לועז","b":"מחכמי ירושלים-תקיח, דרשן, מלומדי ישיבת \"דמשק אליעזר\"."},{"i":26412,"n":"כולי, יעקב מירושלים וקושטא","f":"מכיר","bt":"תמה","bp":"ירושלים","dt":"תצב - יט אב","dp":"קושטא","b":"נכד (בן בתו) ר משה ן חביב. מחכמי ירושלים, עבר לקושטא ולמד אצל ר יהודה רוזנס, אחר פטירתו של רבו ערך את ספריו וסדרם ובהם \"משנה למלך\". ספרו \"מעם לועז\" קושטא תצה. קצת מדבריו בספר \"עזרת נשים\" לזקנו ר משה בן חביב, ושר יעקב הביאו לדפוס נדפס בקושטא תצא. אולי הוא שהיה מגיה בדפוס יונה בן יעקב בקושטא.","bk":[["מעם לועז – בראשית ושמות",""],["מעם לועז, תצ\"ב, קבור בטורקיה",""]]},{"i":26413,"n":"כולי, מכיר מירושלים","bt":"שצו","bp":"קנדיא (כרתים)","dt":"תפח - כט כסלו","dp":"צפת","b":"עלה מצרפת? לירושלים-תמח ונשא את בתו של ר משה בן חביב, ואחר פטירתה את בתו של ר אריה יהודה ליב כץ בעל \"שער אפרים\" בשנת תנט. בנו - ר יעקב בעל \"מעם לועז\"."},{"i":26414,"n":"כולי, שבתי","b":"מחכמי איטליה"},{"i":26415,"n":"כולי-קזאני, ישראל יעקב","f":"שבתי כולי","b":"רופא מחכמי קנדיא(=כרתים). נזכר בתקנה-שלז על איסור על נשים לצאת אחר הנפטר."},{"i":26416,"n":"כומיטיאני, מרדכי","f":"אליעזר","k":"הרמ\"ך-בעל כתר תורה","bt":"קפ","bp":"קושטא","dt":"רן","b":"תלמיד ר חנוך סאפורתא. רב באדרינופול. היה במחלוקת עם ר שבתי בן מלכיאת הכהן אודות ספרי האבן עזרא."},{"i":26417,"n":"כונסארי, אהרן","b":"מחכמי יאזד(פרס)"},{"i":26418,"n":"כורייף, אברהם יהודה מאיטליה","b":"רב באיטליה. מכתב ממנו-תקפו אל ר עזרא דילויכיו מלוגו-איטליה."},{"i":26419,"n":"כושפו, אהרן מקושטא","b":"רב בקושטא-ד'תתקלו, נזכר אצל ר בנימין מטודילא."},{"i":26420,"n":"כחלון, חואתו חיים","b":"מחכמי טריפולי בלוב"},{"i":26421,"n":"כחלון, יוסף מלוב","bt":"תרם","dt":"תשי - בערך","b":"רב בזנזור-לוב-תרף עד תשה."},{"i":26422,"n":"כחלון, יעקב מלוב","f":"סעייד","bt":"תרסז","bp":"כפר זליתן-לוב","dt":"תשנא","dp":"ישראל","b":"רב בכפר זליתן-לוב-תרפג (שם נולד) עד תש, עלה לארץ-תשי וכיהן כרב במושב עלמא."},{"i":26423,"n":"כי\"ח - כל ישראל חברים - חברה"},{"i":26424,"n":"כייאט, אברהם","dt":"תקמו","b":"דיין בתונס"},{"i":26425,"n":"כייאט, נסים מג'רבה","b":"רב בג'רבא - בשנות הת'. תקנות שלו עם חברו ר מיכאל וזאן נזכרו ב\"ישיב משה\" לר משה שתרוג. תלמידיו ר אהרן פרץ בעל \"בגדי אהרן\", ור יצחק חדאד בעל \"תולדות יצחק\" המזכירו בספרו."},{"i":26426,"n":"כלאב, י' ד' מריגא","b":"פרסם מאמרים ב\"פלפול החברים - ריגא תרפד - מאסף תלמידי ישיבת ריגא."},{"i":26427,"n":"כלאב, יעקב","dt":"תשיט - ג טבת","b":"ר\"מ בירושלים"},{"i":26428,"n":"כלאב, ישראל משה","dt":"תשג","b":"ר\"מ בריגא"},{"i":26429,"n":"כלאף, אברהם","b":"מקובל, מרבני תונס"},{"i":26430,"n":"כלב בן חצרון","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא."},{"i":26431,"n":"כלב מארטא-יוון","f":"יוחנן","b":"רב בארטא בזמן ר יהודה מינץ. דודו ורבו של ר בעל \"בנימין זאב\"."},{"i":26432,"n":"כלב מיוון","f":"שלמה","b":"פייטן מחכמי יוון-רפב."},{"i":26433,"n":"כלב מירקדו מאיר","f":"יוסף","bp":"רודוס","dt":"תרנו - ו ניסן","dp":"ירושלים","b":"מחכמי ירושלים וישיבת \"בית אל\". בנו - הראש\"ל ר יעקב מאיר."},{"i":26434,"n":"כלב ממצרים","b":"רב במצרים בזמן הרמבם, השיב על השגות ר שמשון משאנץ על הרמב\"ם."},{"i":26435,"n":"כלב מקושטא","f":"שמואל","b":"דיין בקושטא-שנות ה-ת' אצל ר יום טוב ן יקר, חתום על כתב המינוי למשלחת שמונתה לחקור אודות נתן העזתי."},{"i":26436,"n":"כלב שמואל מקושטא","b":"מחכמי קושטא. נזכר ב\"תורת אמת\" לר אהרן ששון."},{"i":26437,"n":"כלב, אברהם יעקב","b":"רב בפרייל-תר\"ס"},{"i":26438,"n":"כלב, אברהם מאנגורה","b":"מחכמי אנגורה(=אנקרה?)-ש',"},{"i":26439,"n":"כלב, יוסף מהאזינפוט","f":"משה","b":"רב בהאזינפוט(=האזנפוט)."},{"i":26440,"n":"כלב, יעקב","b":"פרסם מאמרים ב\"פרי עץ חיים\" - טלז תרצט - קובץ תלמידי ישיבת טלז."},{"i":26441,"n":"כלבו, אברהם מברזענין וזוגורבא","f":"משה יחיאל","k":"בעל המחדד","bt":"תרלו","b":"תלמיד זקנו-אב\"ד לונטשיץ. חתן ר שלמה אוירבך מקאליש בעל \"אמרי בינה\". רב בבורזענין-פלך קאליש-תרסג. נסמך מאת: ר ישראל יהושע מקוטנא. פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס, פרסם מאמרים ב\"שערי חכמה\" - אוזרוב תרפד."},{"i":26442,"n":"כלבו, דוד ממצרים","b":"רב באלכסנדריה-שנות ה-ש'."},{"i":26443,"n":"כלבו, יהושע יוסף","f":"יעקב מנחם","k":"בעל בנין אריאל","b":"חיבר ספר על ירושלים ובית המקדש בשלשה חלקים."},{"i":26444,"n":"כלבו, מאיר","k":"בעל פירוש לתורה","b":"חיבר פירוש לתורה בכת\"י (והיה בידי ר משה רפאל די אגילאר), מוזכר ב\"שפתי ישנים\"."},{"i":26445,"n":"כלבו, עמנואל משלוניקי","f":"רפאל משלוניקי","dt":"תקם-ס - ב אלול","dp":"שלוניקי","b":"למד רפואה בפדובה-תפד. רופא ותלמיד חכם. ישב בשלוניקי-תצג ונשא ונתן בהלכה עם ר משה אמריליו, הגיע עם אביו לליוורנו. חיבר פסקים קינות ושירים - ומהם ב\"קול עוגב\" לר אברהם ברוך פיפרנו. היה משורר חשוב יחד עם חברו ר אברהם יצחק קאשטילו (והיה מעין תחרות ביניהם)."},{"i":26446,"n":"כלבו, רפאל משלוניקי","b":"מחכמי שלוניקי, התישב בליוורנו ולימד תורה. מוזכר ב\"קול עוגב\""},{"i":26447,"n":"כלבזון, יהודה אידל מדובייק","b":"חזן בדובייק-ליטא."},{"i":26448,"n":"כליף, שמואל מדמשק","b":"דיין בדמשק-שנג אצל ר יעקב אבולעפיה."},{"i":26449,"n":"כליפא הכהן מג'רבה","k":"בעל מענה רך","b":"נכד הראב\"ד של ג'רבא ר רחמים הכהן. חיבר \"מענה רך\" ונדפס בסוף \"שלום דוד\" ג'רבא תרעה. ?? לא באוצר ??"},{"i":26450,"n":"כליפא הכהן מהדיג'ת-ג'רבה","k":"בעל שמחה וששון","dt":"תרצב - ה תמוז","b":"רב וראש ישיבה בהדיג'ת-ג'רבא. חיבר עוד \"מדרש שלמה\", \"שם הגדולים\". בנו ר יהודה מניני הכהן בעל \"קול יהודה\"."},{"i":26451,"n":"כליפא הכהן מתונס","k":"בעל שפתי רננות","bt":"תקפב","bp":"תונס","b":"רב בתונס."},{"i":26452,"n":"כליפא ן, דוד מאלגיר","f":"מכלוף","k":"בעל דרכי דוד","bt":"תרסו","dt":"תשנג","dp":"ירושלים","b":"תלמיד ר אליהו בן גיגי מסעידא. רב בתימושנת-אלגיר-תשח, מאסי-(ליד פאריס)-צרפת-תשכב, עלה לירושלים, חיבר גם \"מכלל יופי\" - ירושלים תשל. חיבר חיבור על תולדות רבני אלגיר - ואבד."},{"i":26453,"n":"כליפא, אברהם ממצרים","b":"מחכמי קהיר-שסו."},{"i":26454,"n":"כליפי, חיים דוד מטריפולי","k":"בעל אורח לחיים","dt":"תרמו","b":"רב בטריפולי. חיבר \"מערכת כללים\", \"סימנא דחיים\". מתורתו ב\"מעטה תהלה\" ליוורנו תריח. חתם בשם - \"חיים מדב\"ר\"."},{"i":26455,"n":"כלף, אברהם מתונס","dt":"תרכח - ט אייר","b":"רב בתונס. נספד מאת ר אליעזר אשכנזי מתונס ב\"הלבנון\"-תרכח."},{"i":26456,"n":"כלף, משה מתימן","b":"דיין בשרעב-תימן - מחצית ראשונה של המאה ה-20."},{"i":26457,"n":"כלפאני הכהן מגאבס-תונס","k":"בעל כסא רחמים","b":"רב בגאבס-תונס. מתלמידיו - ר נסים סיסי, ור פרג'י עלוש."},{"i":26458,"n":"כלפו, משה","b":"מגדולי התורה באיטליה בבארי-ד'תת\"ל"},{"i":26459,"n":"כלפון","f":"מנשה","b":"בשנת תתק (1140) היה בבית הדין בירושלים"},{"i":26460,"n":"כלפון - משפחה","b":"משפחה שמקורה בספרד."},{"i":26461,"n":"כלפון ממצרים","f":"עולא","b":"הגיע מטריפולי למצרים בזמן הרמב\"ם-ד'תתקן ונזכר בתשובותיו, דיין בדמנהור."},{"i":26462,"n":"כלפון משה הכהן מג'רבה","f":"שלום","k":"בעל שואל ונשאל","bt":"תרלד","bp":"ג'רבא","dt":"תשו - יח טבת","dp":"ג'רבא - ירושלים","b":"נכד ר שאול הכהן מג'רבא. תלמיד ר יוסף ברבי בעל \"בן פורת יוסף\", ור משה זקן מאזוז. חתן דודו - אחי אמו - ר אברהם הכהן. שו\"ב בזרזיס, רב בג'רבא על מקום ר משה זקן מאזוז. בניו ר אברהם מגוץ, ור שושן הכהן דיין בג'רבא וישראל. חיבר ספרים רבים. פרסם מאמרים ב\"אוצר התורה\" - ג'רבה תרץ, \"הירח\" - ג'רבה תשח.","bk":[["שואל ונשאל","שו\"ת - אחרונים"]]},{"i":26463,"n":"כלפון, אברהם הכהן מגרבה","f":"משה","k":"בעל ברכת אברהם","bt":"תרנח","dt":"תרצא","b":"מחשובי רבני ג'רבה, בעל \"ברכת אברהם\""},{"i":26464,"n":"כלפון, אברהם מטריפולי","f":"רפאל","k":"בעל חיי אברהם","bt":"תצה - תקא","bp":"ליוורנו או טריפולי","dt":"תקפ","dp":"צפת","b":"הגיע מליוורנו לטריפולי בילדותו עם הוריו. פרנס מחכמי טריפולי-תקלה, ונשיא הקהלה-תקלח. סיפר שמל אותו בעל \"אור החיים\" בליוורנו. חיבר פיוט \"מי כמוכה\" לשבת פורים בורגיל, וקינותיו על בנו שנשרף עק\"ה במאורעות. מחבוריו: \"חיי אברהם\" על טעמי המצוות (ליוורנו תקפו). ו\"לקט הקיצור\", אסף וחקר אודות קורות היהודים בטריפולי וחבר פיוטים שונים, כתב ידו על תקנות קדומות נעלם. ידידו של החיד\"א - והתכתב עמו, תלמידו של ר משה לחמייש. עלה לצפת אחר שנת תקסו או תקפ (ולפי \"ארזי הלבנון\" נולד בטריפולי ועלה בתקסו)."},{"i":26465,"n":"כלפון, אברהם ממרוקו","bt":"תקע - בערך","bp":"טיטואן? - מרוקו","dt":"תרן - בערך","b":"רב בתייארת-אלגיר. נזכר אצל ר אברהם אנקאווא ב\"כרם חמר\"."},{"i":26466,"n":"כלפון, אברהם מספרד","b":"פייטן ומחבר מחכמי ספרד-ד'תתק\"מ"},{"i":26467,"n":"כלפון, אברהם מתימן","k":"אברהם אל עדני","b":"משורר, מראשוני הפייטנים בתימן, מהעיר עדן"},{"i":26468,"n":"כלפון, דוד מגיברלטר","b":"מו\"צ בגיברלטר-תץ. נזכר ב\"בית יהודה\" לר יהודה עייאש."},{"i":26469,"n":"כלפון, דוד מגיברלטר","f":"אברהם","b":"חיבר פירוש לאידרות בגיבאלטאר-סיים בסיון תצ\"א"},{"i":26470,"n":"כלפון, דוד מחיפה","f":"אברהם רפאל","bt":"תריח","bp":"חיפה","dt":"תרצז - ל אדר","dp":"חיפה","b":"מורה בכי\"ח, חיבר שירים ומנגינות, ממיסדי \"בני יהודה\" - \"הדר הכרמל\" בחיפה."},{"i":26471,"n":"כלפון, יהודה מטריפולי","bt":"תם","dt":"תקי - בערך","b":"סופר קהלת טריפולי. חתם בפנקס בי\"ד טריפולי."},{"i":26472,"n":"כלפון, יוסף מטריפולי","f":"מרזוק","dt":"תקע - אחרי","dp":"מצרים","b":"רב בטריפולי-תקסב, ודיין עם ר יעקב זטלאווי, עלה לארץ - והיה גם בחיפה, עבר למצרים. נזכר אצל ר אברהם אדאדי ב\"ויקרא אברהם\". חתם בפנקס בי\"ד טריפולי."},{"i":26473,"n":"כלפון, ימין","dt":"תרפט - ח טבת","b":"מרבני חיפה"},{"i":26474,"n":"כלפון, יעקב","f":"יוסף","k":"בעל משפטים צדיקים","b":"נכד ר יעקב מטיטואן וגיברלטר."},{"i":26475,"n":"כלפון, יעקב ליאון ממרוקו","b":"רב בטיטואן-תר\"ס"},{"i":26476,"n":"כלפון, יעקב מטיטואן וגיברלטר","k":"בעל נגד מלכים","bt":"תקסח","bp":"טיטואן","dt":"תרטו - יט אב","dp":"טיטואן","b":"רב בטיטואן-שנות ה-תק', גיברלטר-תקצה, חתם על פס\"ד עם ר מנחם אבודרהם ור וידאל ביבאס. נכדו - ר כלפון בן יוסף בעל \"משפטים ישרים\"."},{"i":26477,"n":"כלפון, יעקב ממרוקו","b":"רב בפאס-תרם."},{"i":26478,"n":"כלפון, יצחק מלוב","bt":"תקס","dt":"תרל - בערך","b":"רב בבנגזי, והיה מראשוני הרבנים הידועים משם. נזכר ב\"מסעי ישראל\" ליק תריט."},{"i":26479,"n":"כלפון, יצחק ממרוקו וספרד","b":"משורר, נקרא בשם אבו אברהים בן חלפון ונזכר אצל ר\"מ ן עזרא שהגיע מאפריקה לספרד."},{"i":26480,"n":"כלפון, כליפא מטריפולי","k":"בעל מקור דמך","bt":"תרי","bp":"טריפולי","dt":"תרפ","b":"חיבר שירים וקינות \"מקור דמך\" - ליוורנו תרלה. ?? לא באוצר ??"},{"i":26481,"n":"כלפון, כליפא מטריפולי","k":"הו\"ל מקור דמעה","b":"תלמיד ר יעקב מימון. רב בטריפולי. הו\"ל \"מקור דמעה\" ליווורנו תרלה. נזכר ב\"באר לחי\" לר חי מימון - ליוורנו תרמח."},{"i":26482,"n":"כלפון, מרדכי משה ממרוקו","b":"חתם-תרח על אישור פס\"ד של ר ראובן אלמליח ור אברהם אנהורי, יתכן שהיה רב בטיטואן?"},{"i":26483,"n":"כלפון, משה מטבריה","f":"רפאל מטבריה","dt":"תרפד - טז אב","b":"רב בגיברלטר?, עלה לארץ. מחכמי טבריה, רב בחיפה. חתנו - ר משה ן נעים מגיברלטר."},{"i":26484,"n":"כלפון, נסים מטריפולי","bt":"תם","dt":"תקי - בערך","b":"רב בטריפולי. מתורתו ב\"זרע יצחק\" לר יצחק חדד - ירושלים תשסא."},{"i":26485,"n":"כלפון, ציון מטריפולי","bt":"תרי","dt":"תרף - בערך","b":"רב בטריפולי. חתם על הסכמה לשמירת זכויות הספרדים בקופת ר מאיר בעל הנס בטבריה. נזכר ב\"זכרון ירושלים\" תונס תרסד."},{"i":26486,"n":"כלפון, רחמים","f":"אברהם מטריפולי","b":"הו\"ל את ספר אביו \"חיי אברהם\"."},{"i":26487,"n":"כלפון, רפאל אברהם ממרוקו","k":"אכ\"ל","bt":"תקף","bp":"מרוקו","dt":"תרמו - ד ניסן","dp":"חיפה","b":"מחכמי טיטואן-מרוקו, עלה לטבריה-תרך וכיהן כדיין וראש ישיבה, עבר לחיפה וכיהן כאב\"ד-תרמא וראש ישיבה. חתם על כתב שליחות ר שלמה טולדנו. הסכים על \"זבחי שלמים\" לר משה קורדובירו-תרמג, \"יסוד המערבי\", \"עשיר ורש\" ועוד. בנו - ר משה - חתנו של ר רפאל משה ן נאים מגיברלטר."},{"i":26488,"n":"כלפון, שלמה מטריפולי","b":"גביר בטריפולי בשנות ה-תע', סייע לפדות את ר עמנואל ריקי שנשבה בידי שודדים בדרכו מארץ ישראל."},{"i":26489,"n":"כלפון, שמואל מפאס","b":"רב בפאס, חתם-תט על הסכמה עם ר סעדיה ן דנון."},{"i":26490,"n":"כמון ן, מרדכי מפאס","b":"מחכמי פאס, חתם-רפו בענין הנפיחה."},{"i":26491,"n":"כמון ן, שאול מפאס","b":"מחכמי פאס-רפו, וחתם אז על הסכמה בענין נפיחת הריאה."},{"i":26492,"n":"כמוס הכהן","f":"חיותו","k":"בעל כמוס עמדי","dt":"תשלז","b":"תלמיד ר דידו (דוד) הכהן מג'רבא. מחכמי ג'רבא, עלה לארץ והתישב בנתיבות."},{"i":26493,"n":"כמוס ן, אברהם הכהן","f":"יוסף","k":"בעל חיי אברהם","b":"כתב \"חיי אברהם\""},{"i":26494,"n":"כמוס שמואל הכהן מג'רבה","f":"שלום","k":"בעל דברי שמואל","b":"תלמיד ר דידו (דוד) הכהן מג'רבא."},{"i":26495,"n":"כנאפו, יוסף ממוגאדור","k":"בעל מנחת ערב","bt":"תקפג","dt":"תרסא - כה כסלו","b":"מחכמי מוגאדור-מרוקו. חיבר גם \"שומר שבת\", \"אות ברית קודש\", ועוד. בנו - ר דוד ממוגאדור. (במלכי רבנן תאריך פטירתו תקסא - כנראה טעות)"},{"i":26496,"n":"כנאפו, מסעוד ממוגדור","b":"דיין במוגאדור-תרע אצל ר יוסף כנאפו. חיבר שו\"ת בכת\"י. העתיק בכתב ידו - \"שבחי פסח\" בערבית יהודית."},{"i":26497,"n":"כנזי, שלמה הקראי מדמשק","f":"יוסף","k":"בעל ספר המישור","b":"נכד אשר יצחק בן יונה. רופא קראי מחכמי דמשק. חיבר ספר המישור - תפב - בכת\"י."},{"i":26498,"n":"כניזו, שלום ממראקש","dt":"תקסט - א חשון","dp":"מראקש","b":"רב במראקש-מרוקו."},{"i":26499,"n":"כנסת יחזקאל - ישיבה בירושלים","b":"ישיבה בירושלים, נוסדה בעזרת יחזקאל יהודה מבגדד והודו."},{"i":26500,"n":"כנסת ישראל - ישיבה בירושלים","b":"ישיבה בירושלים-תק שיסד ר חיים ן עטר בעל אור החיים. ראש הישיבה ר חיים מונדיבי, עוד מתלמידיה ר שם טוב גבאי, ר יעקב אצבאן, ר יעקב פריינטי, ר צבי הלוי, ר עזריה לאורניס, ר אליהו דודו, ר שלמה ארגואוטי, ר מרדכי מערבי, ר דוד חסאן, ר יונה נבון, ר חיים יהודה אמזלג, ר יהודה די אבילא."},{"i":26501,"n":"כנסת ישראל - ישיבת בירושלים","b":"ישיבת בירושלים מיסודו של ר חיים ן עטר בעל אור החיים."},{"i":26502,"n":"כנפו יוסף בן משה","bt":"1823","dt":"ה'תרס 1900","bk":[["אות ברית קדש",""],["טוב רואי",""],["יפה עינים",""]]},{"i":26503,"n":"כנראה שפי' זה היה לפני הרוקח ושבלי הלקט","bt":"ד'תתקכ (בערך)","bk":[["פי' קדמון להגדש\"פ",""]]},{"i":26504,"n":"כסאר, חיים","k":"בעל שם טוב","bt":"תרסב","bp":"צנעא","dt":"תשנח - כב כסלו","b":"תלמיד ר' יחיא קאפח,עלה לא\"י תש\"ט,מגדולי חכמי תימן בא\"י,סופר גיטין ורב בית כנסת בירושלים,חיבר \"שם טוב\" על משנה תורה לרמב\"ם","bk":[["שם טוב",""],["החיים והשלום",""],["קיץ המזבח",""]]},{"i":26505,"n":"כסאר, שלום מתימן","f":"יחיא","bt":"תרלו","bp":"צנעא","dt":"תשכד","dp":"ירושלים","b":"עלה בילדותו עם הוריו לירושלים-תרמב, תלמיד ר יחיא צארום. ראש ישיבת \"מקור חיים\" בירושלים. חיבר זכרונות על עליית היהודים בתרמ\"ב."},{"i":26506,"n":"כסאר, שלום מתימן","b":"חכם באשי בצנעא-תרן."},{"i":26507,"n":"כסאר, שלום מתימן וירושלים","bt":"תרלו","b":"מחכמי תימן, עלה לירושלים-תרמב, מרביץ תורה וסופר, התצטרף לעדה הספרדית ולא אל עדת התימנים."},{"i":26508,"n":"כסיסא, חיים הכהן מצפרו-מרוקו","b":"מחכמי צפרו-מרוקו-שנות ה-ת-תק'."},{"i":26509,"n":"כסכסו, שמואל מפאס","b":"מחכמי פאס-שנות ה-תק'. מכתב תמיכה אליו מר רפאל יעקב שמחון. אולי הוא ר שמואל סכסו שנזכר אצל היעב\"ץ."},{"i":26510,"n":"כספי, אבא מרי מאלגיר","f":"נחמן","k":"דון אשתרוק בונפיל","bt":"קמ","dt":"רך","b":"הגיע מספרד לאלגיר-קנא בזמן הגזירות. תלמיד הריב\"ש, והרשב\"ץ. מגדולי חכמי אלג'יר-קצ. שיר ממנו לכבוד הרשב\"ץ ב\"יבין שמועה\" להרשב\"ץ, וקינה ממנו על מצבת הריב\"ש."},{"i":26511,"n":"כספי, אבא מרי מאלגיר","f":"יוסף","bt":"רל","dt":"ש","b":"רב משורר ופיטן באלגיר."},{"i":26512,"n":"כספי, יוסף מאלגיר","f":"שלום בן אבא מרי","bt":"קע","dt":"רמ - בערך","b":"רב ומשורר ופיטן באלגיר בזמן הרשב\"ץ. קינות ממנו ב\"אורח מישור\" לר יעקב רקח, ועוד."},{"i":26513,"n":"כספי, יוסף מאלגיר - ב","f":"אבא מארי","bt":"רס","dt":"של - בערך","b":"רב משורר ופיטן באלגיר. מפיוטיו בספרי חכמי אלגיר."},{"i":26514,"n":"כספי, יוסף מצרפת וספרד - א","f":"אבא מארי","k":"בעל גביע כסף","bt":"מ'","dt":"ק'","b":"פייטן ומדקדק מחכמי צרפת, עשיר, רב במצרים, פאס, ספרד. חיבר \"קבוצת כסף\", \"מצרף לכסף\", פירוש לספר הקמה לר יונה ן גנאח, ועוד. היה מחלוקת על כתביו - ר יוסף יעבץ יצא כנגדו בספריו \"יסוד האמונה\" ו\"אור החיים\", ור קלונימוס בן קלונימוס השיג על ספרו \"טירת כסף\"-עט."},{"i":26515,"n":"כספי, מרדכי מירושלים","f":"אברהם","bt":"תרמה","bp":"ירושלים","b":"קונסול לטביה בירושלים."},{"i":26516,"n":"כספי, נתנאל מספרד","b":"מחכמי ספרד בזמן ר יצחק קנפנטון. תלמיד ר שלמה בן מנחם וחברו של ר שלמה די לוניל."},{"i":26517,"n":"כספי, רפאל משלוניקי","b":"משורר בשלוניקי-שנות ה-ש', מחברי ר גדליה ן יחיא המשורר משלוניקי."},{"i":26518,"n":"כספי, שלום מאלגיר","f":"אבא מארי","bt":"קל","dt":"ר - בערך","b":"פוסק מחכמי אלגיר בזמן הריב\"ש, והרשב\"ץ."},{"i":26519,"n":"כספי, שלמה מאלגיר","bt":"תך","dt":"תץ - בערך","b":"משורר ודיין באלגיר אצל רי\"ש צרור. חתם על החרם נגד נחמיה חיון. נזכר ב\"פרי צדיק\"."},{"i":26520,"n":"כספי, שלמה משלוניקי","dt":"שפא - יב אב","dp":"שלוניקי","b":"משורר מחכמי שלוניקי."},{"i":26521,"n":"כספי, שמואל מאלגיר","bt":"תס","dt":"תקל - בערך","b":"דיין באלג'יר-תקד אצל ר אברהם יאפיל. חתם על הסכמות ותשובות שהובאו אצל חכמי דורו, ובהם על ספרי ר יהודה עייאש."},{"i":26522,"n":"כעאבלו, יהודה מאספי-מרוקו","f":"מסעוד","b":"מחכמי אספי-מרוקו-תכט."},{"i":26523,"n":"כעבאלו, יהודה מאספי","b":"מחכמי אספי-תכט, נזכר באגרת ר מסעוד אתאזי."},{"i":26524,"n":"כעבאלו, מסעוד מאספי-מרוקו","b":"רב באספי-מרוקו - בשנות ה-ת."},{"i":26525,"n":"כעבון, ישראל מאלגיר","bt":"רץ - בערך","dt":"שע - בערך","b":"רב באלגיר, תלמסאן. נזכר ב\"עומר השכחה\" ואצל החיד\"א."},{"i":26526,"n":"כעבון, מכלוף מאלגיר","bt":"שך","dt":"שץ - בערך","b":"רב במילייאנא-אלגיר. שאלה ממנו לרשב\"ץ האחרון."},{"i":26527,"n":"כפוסי, חיים ממצרים - בעל הנס","f":"יצחק","k":"בעל באור החיים","bt":"ש - בערך","dt":"שצא - יב שבט","b":"רב באלגיר, הגיע עם אביו למצרים, מגדולי רבני מצרים, למד תורה אצל מהר\"י בירב, וקבלה מהאר\"י, דיין באלכסנדריה בזמן הרדב\"ז, דמיאט. התעור וכאשר רננו אחריו שכהו עיניו כי נטל שוחד ובנס שבו עיניו לראות לעין כל, ומאז חתם \"ד' ניסי חיים כפוסי\". חיבר \"באור החיים\" על התורה. מתורתו בספרי חכמי מצרים, התכתב עם הרשב\"ץ ונזכר ב\"חוט המשולש\". חשב לעלות לארץ אך נפטר במצרים."},{"i":26528,"n":"כץ אריה ליב בן משה","dt":"ה'תקפ 1820","bk":[["פני אריה",""],["קונטרס מילי דאבות",""]]},{"i":26529,"n":"כץ ברטדם, שלמה","dt":"תריח - יא אד\"א","b":"רב בשטעקטשין,פינטשוב,ראב\"ד בקרקא"},{"i":26530,"n":"כץ גרוס, משה פערי","bp":"טיסא-פערע","b":"תלמיד החת\"ס, ור יצחק פרנקל מקראלי. חתן הגביר ר דוד קליין. גר בפעטשי-ניידורף וניהל אחוזה בפריטש ובעל מפעל למים מינרלים \"סאלוואדור\". כשירד מנכסיו נתמנה שם לרב-תרכה."},{"i":26531,"n":"כץ דב בן יעקב","bt":"1903","dt":"ה'תשלט 1979","bk":[["פולמוס המוסר",""]]},{"i":26532,"n":"כץ יהודה בן יעקב מאיר","bt":"1840","dt":"ה'תרסח 1908","bk":[["קול יהודא",""]]},{"i":26533,"n":"כץ מאיר יוסף","bt":"1900","dt":"ה'תשמח 1988","bk":[["שאר יוסף",""]]},{"i":26534,"n":"כץ מחוקק, בנימין","dt":"תסה","b":"רב בוירמיזא"},{"i":26535,"n":"כץ קודש, י' אר' ליבוש","dt":"תרכח - יד אלול","b":"מו\"צ בוורשה-תקצ\"ה"},{"i":26536,"n":"כץ קערעפש, יום טוב ליפמן מאירש","f":"אהרן","bp":"אטש","b":"תלמיד החת\"ס. חתן ר דוד קערעפש מאירשא ועבר לשם והיה מחכמי אירשא. נזכר ב\"חתם סופר\"."},{"i":26537,"n":"כץ ראובן בן השקי","bt":"1605","dt":"ה'תלג 1673","bk":[["דבר שבקדושה",""],["ילקוט ראובני",""],["עונג שבת",""]]},{"i":26538,"n":"כץ ראובן בן שמעון","bt":"1880","dt":"ה'תשכג 1963","bk":[["דגל ראובן",""],["דודאי ראובן",""],["שער ראובן",""]]},{"i":26539,"n":"כץ רפא, יקותיאל","b":"גביר,רב בפורטו-רכ\"ז"},{"i":26540,"n":"כץ רפאל בן יקותיאל זיסקינד","bt":"1722","dt":"ה'תקסג 1803","bk":[["דעת קדושים",""],["זכר צדיק",""],["מרפא לשון",""],["שאלת הכהנים תורה",""],["תורת יקותיאל",""]]},{"i":26541,"n":"כץ, אביגדור מזבורוב","b":"רב בזבורוב. זקנו של ר יצחק הורודנר מוינה."},{"i":26542,"n":"כץ, אביגדור מרדכי מאוסטרין","f":"אברהם עזרא מאמדור","k":"בעל פרי הדר","b":"רב באוסטרין(=אסטרין)-[תרכ..], גראיעווע. חיבר גם \"קרבן תודה\", ענבי גפן\", \"תורת אביגדור\", ועוד. גיסו - ר בן ציון איזנשטט בעל \"אמרי ברוך\"."},{"i":26543,"n":"כץ, אברהם אהרן מנייטרא","f":"משה פרוסטיץ מנייטרא","bt":"תרכט או תרלד","dt":"תרץ - יז אייר","dp":"נייטרא","b":"תלמיד השב\"ס, ור משה צבי הרש פוקס מגרוסורדין. מו\"ץ בנייטרא-תרס ורב-תרפז על מקום אביו. נסמך מאת: השב\"ס, דודו ר דוד פרידמן מצעהלים. בנו ר אליהו כץ רב בבאר שבע."},{"i":26544,"n":"כץ, אברהם אליהו משה מפעצעל","dt":"תרלג - יד תשרי","b":"רב בפעצעל"},{"i":26545,"n":"כץ, אברהם אריה ליב מברוד","f":"כהנא, אברהם אריה ליב","b":"רב בברוד תק\"כ"},{"i":26546,"n":"כץ, אברהם דב ברטשי מלמברג","f":"חיים","bt":"תרלט","bp":"בוברקא","dt":"תשב","b":"חתן ר ישראל גרינולד ממוסט. רב בלמברג-תרסב. נספה בשואה."},{"i":26547,"n":"כץ, אברהם חיים ממוהילוב","k":"בעל פת לחם","b":"מג\"מ במאהליב-תק\"נ"},{"i":26548,"n":"כץ, אברהם מויזון","b":"רב בויזון על מקום ר אהרן שמידט ור זלמן מלצר הי\"ד על מקומו אחריו."},{"i":26549,"n":"כץ, אברהם מירושלים","b":"תלמיד ישיבת \"שפת אמת\" בירושלים. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרצה - בהוצאת ישיבת \"שפת אמת\"."},{"i":26550,"n":"כץ, אברהם מלמברג","b":"דיין בלבוב, חתם-תפד עם ר נתן נטע בן זלמן ור אהרן זליג בן שמואל למשפחת צבי, ועוד."},{"i":26551,"n":"כץ, אברהם מפעטרא","dt":"תרך - אחרי","dp":"פעטרא (ליד מרגרעטין)","b":"תלמיד החת\"ס. בנו - ר יצחק יוסף כץ קאהן מסמאש-אויוואר, חתנו - ר אליהו וייס משימלויא. תשובה אליו ב\"חתם סופר\"."},{"i":26552,"n":"כץ, אברהם עזרא מאמדור","f":"שמואל מאמדור","dt":"תרמב","b":"רב באמדור-במאה ה-19, לאחר פסק דין מוטעה פרש מן הרבנות ויצא להשתלם בתורה ובפוסקים, קהילת אמדור המתינה לו עד שחזר. בנו ר אביגדור מרדכי מאוסטרין בעל \"פרי הדר\"."},{"i":26553,"n":"כץ, אברהם צבי מדאוג","b":"רבה של דאוג-ליטא כ-40 שנה, ור אפרים ניסן מה-יפית על מקומו אחריו."},{"i":26554,"n":"כץ, אברהם שלמה מריסקובה ונ\"י","f":"אליהו מראסלביץ","k":"בעל אורחות המשפטים","bt":"תרמד","dt":"תשלה - יד ניסן","b":"חסיד סיגט-סטמר. תלמיד בעל \"ערוגת הבשם\" בחוסט, וה\"קדושת יו\"ט\" בסיגט. חתן ר צבי ברגפלד מנימוזה, רב בנימוזה-תרעה על מקום חותנו, רב בריסקווה-(=פוליען-ריסקובה)-מרמארוש והקים ישיבת \"תורת אש\" (ר\"ת שמו). נחשב למומחה בדיני ממונות ונבחר כבורר ואב\"ד בדיני תורה מסובכים. ניצל מהשואה, ואחריה רב בקלויזנבורג, וכיהן כנשיא הועד הפועל של לשכת הרבנים-תשה. היגר לארה\"ב-תשי, עלה לארץ-תשכה וכיהן כרב \"קרית יואל\" בבני ברק. חיבר גם \"דברי אש\". פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":26555,"n":"כץ, אהרן גד מנימוז'ה","f":"אליהו מראסלוביץ","k":"בעל קרן אורה - בכת\"י","r":"אב\"ד ראסאלויץ","bt":"תרמז","dt":"תשא - ח תמוז","b":"תלמיד בעל \"ערוגת הבשם\" בחוסט, וה\"קדושת יו\"ט\" בסיגט. חתן הגביר ר אלתר לאנדוי מבאטארטש-ליד האלמין, ועבר לשם. רב בנימוזה-תרפו על מקום אחיו ר אברהם שלמה שעבר לריסקווה. רוב כתביו אבדו בשואה.","bk":[["פרח מטה אהרן – שו\"ת",""]]},{"i":26556,"n":"כץ, אהרן יצחק הלוי מפולנגן","f":"שמואל מנחם מפולנגן","bt":"תרסח","dt":"תשא","dp":"פולנגן-ליטא","b":"תלמיד זקנו ר חיים הלוי מפומפיאן, וישיבות טלז, פוניבז. רב באוטיאן, פולנגן על מקום אביו. נספה בשואה."},{"i":26557,"n":"כץ, אהרן מברלין","f":"איזיק","b":"מראשי הקהילה בברלין-תע, והיה מתומכי ר מרדכי ראנבאך בזמן המחלוקת אודות ביהכ\"נ בברלין."},{"i":26558,"n":"כץ, אהרן מורנדורף","b":"רב בוארנדורף(=ורנדורף)-תקכא, ומדינת פדרבורן ווסטפליה."},{"i":26559,"n":"כץ, אהרן מזילוזיץ","k":"בעל לקוטי שושנים","b":"רב בזילוזיץ-תרסו. חיבר \"לקוטי שושנים\" מונקטש תרעד, ועוד."},{"i":26560,"n":"כץ, אהרן מנחם (משה) מקראקא","f":"יוסף - שארית יוסף","k":"ר מנדל ר זלמן חזנש","dt":"שעו - ט אדר","dp":"קראקא","b":"(לפי גדולי אוסטרהא היה נכדו של ר יוסף בעל שארית יוסף). חתן ה\"פני יהושע\"?. ש\"ץ בקראקא. בנו: ר שלום שכנא כהנא מקראקא. אחיו: ר תנחום מקראקא, ר משה מקראקא."},{"i":26561,"n":"כץ, אהרן שלמה מאלמאשד","b":"רב באלמאשד-ת\"ר"},{"i":26562,"n":"כץ, אהרן שמואל מיאנישוק וראסיי","f":"חיים שמעון הכהן","k":"בעל גחלי אש","bt":"תרל","dt":"תשג","b":"תלמיד ישיבת וולוזין. חתן ר בן ציון גינצבורג-מו\"ל ביאור הגר\"א. רב ביאנישוק-פלך קובנא-תרנז, מו\"צ בראסיין-תרסא על מקום ר אברהם יצחק רבינוביץ, ולימים-תרעא אב\"ד ורבה האחרון של ראסיין. חיבר גם \"אמרי אש\". נספה בשואה."},{"i":26563,"n":"כץ, אלברט מברלין","k":"בעל היהודי וארץ אבות","bt":"תריט","bp":"לודז","b":"תלמיד ישיבת לובלין, וילנא, בעל תואר ד\"ר. רב בביהכ\"נ \"אהל יצחק\" בברלין-תרמד. חיבר גם \"נשמת העם היהודי\", \"שקר הדם\", \"היהודים בקוקז\", \"היהודים בסין\", ועוד. מראשי חברת \"לקורות היהודים וספרותם\"."},{"i":26564,"n":"כץ, אליהו מבאר שבע","f":"אברהם אהרן","k":"בעל באר אליהו","bt":"תרעו","bp":"נייטרא","dt":"תשסה - ח כסלו","b":"תלמיד הדעת סופר, וגיסו ר שלמה וייס מסעמניץ ור שמואל דוד הלוי אונגר ועוד. חתן ר משה ליבוביץ. ניצל מהשואה ואחריה רב בנייטרא, פרשבורג, רב ראשי בסלובקיה. עלה לארץ וכיהן כרב בבאר שבע-תשלא."},{"i":26565,"n":"כץ, אליהו מרסלביץ","b":"רב בראסלאביץ-תרע\"ד"},{"i":26566,"n":"כץ, אליעזר מזלוטשוב","f":"משה אשכנזי הכהן","b":"רב בזלוטשוב(=זלאטשוב)-ת\"ו"},{"i":26567,"n":"כץ, אליעזר מנ\"י","b":"תלמיד ישיבת \"רבי יצחק אלחנן\". פרסם מאמרים ב\"הדנו\" - נ\"י תרפה."},{"i":26568,"n":"כץ, אליעזר מפרשבורג","f":"שמעון צבי הרש","dt":"תרפט - יב שבט","dp":"פרשבורג","b":"תלמיד הכת\"ס, ור משה שיק מחוסט. רב בפרשבורג, מלמד ב\"יסודי התורה\" בפרשבורג-תרמה, ראש חברת ש\"ס בפרשבורג."},{"i":26569,"n":"כץ, אלכסנדר מזברז","b":"רב בזברז."},{"i":26570,"n":"כץ, אלכסנדר סנדר מוארשא","f":"אריה ליב מפלוצק","b":"נכד ר שמואל לסקר. חתן ר משה מאניס מקמפנא. נזכר בספר קרובו \"שמן רוקח\", וב\"צלעות הבית\" לר מאיר פוזנר. גיסו(-בעל אחותו) - ר מאיר צילך מלוסק."},{"i":26571,"n":"כץ, אלעזר מקמינקא","f":"יהושע מליזנסק","dt":"תקמד - יג תמוז","b":"רב בקמינקא."},{"i":26572,"n":"כץ, אנשיל","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":26573,"n":"כץ, אפרים יחיאל ממודנא","f":"דוד","dt":"תקסט","b":"רב במודנא. נכד מוהררי\"ך בעל \"זרע אמת\" ממודנא."},{"i":26574,"n":"כץ, אריה ליב מפרידאן","f":"משה מטיקטין ומאקובה","k":"בעל פני אריה","dt":"תקפא","b":"חתן ר אשר קמץ. רב בפרידאן-פלך פוזנא. נשא ונתן עם חכמי דורו ובהם ר עקיבא איגר. נספד ב\"דרשות גבר\"י\" פפדא תקפו. עליו בהקדמת רצ\"י מיכלזון ל\"דברי גדולים\", ו\"בית אהרן וישראל\" קובץ 30 תשנו."},{"i":26575,"n":"כץ, אשר אנשיל ממטרסדורף","b":"דומ\"צ במטסדורף-תר\"י"},{"i":26576,"n":"כץ, אשר אנשיל מנירמעדיעץ","f":"יונתן בנימין מטשנגר","k":"בעל ולאשר אמר-תשמא","bt":"תרמא","bp":"צ'נגר","dt":"תשד - כז סיון","b":"תלמיד בעל \"ערוגת הבשם\" בחוסט. נסמך מאת: בעל \"הכנה דרבה\". חתן ר שלמה זלמן ארנרייך משאמלוי, דיין בשאמלוי ור\"מ בישיבת חותנו שם. רב בניר-מעדיאש-תרסט, רב בדונא-סערדאהעי(=סערדאוהל) ועמד בראש הישיבה. נספה בשואה. בנו ר יהושע הו\"ל כמה מספריו."},{"i":26577,"n":"כץ, אשר שמואל מקנדה","f":"פנחס יהודה מקרולה","dt":"תשם -","b":"חתן דודו ר אברהם שלמה כץ מריסקווה. רב בזשיבוי. ניצל מהשואה, ואחריה עבר לקנדה וכיהן שם כרב. הו\"ל \"ים הרחב\" לר חיים בצלאל פאנט."},{"i":26578,"n":"כץ, בן ציון","f":"אברהם צבי","k":"בעל מזקנים אתבונן","bt":"1875","bp":"דאוג-ליטא","dt":"1958","dp":"תל אביב","b":"בנו של רבה של דאוג-ליטא. נכד ר שמואל איסר שהיה ר\"מ בישיבת מייליס בוילנא. התפרסם כ\"עילוי מדאוג\". פרסם מאמרים נגד החומרות היתרות ועורר מחלוקת. חיבר גם \"לתולדות ההלכה\". הוזמן לפטרבורג ע\"י הברון גינצבורג להוציא את כת\"י הירושלמי שהיה ברשות הברון עם פירוש מרדכי לכבוד הפרופ' חוולסון - אך לא הסתייע. חיבר גם \"לקורות היהודים ברוסיה\" - ברלין תרנט, ועוד. עלה לארץ-1931 וחיבר \"האמת קודמת לשלום\" לטובת סטבסקי שנאשם ברצח ארלוזרוב."},{"i":26579,"n":"כץ, בן ציון מבורשטשוב","f":"יעקב קופל","k":"בעל ירושלים דדהבא","bt":"תרמז","bp":"סערט","dt":"תרצה","b":"חתן ר אברהמצי יוסף בקנרוט מסכודניצה. רב בבורשטשוב-תרעא, וינה, טשרנוביץ-תרפג. נפטר ללא ילדים. חיבר \"ירושלים דדהבא\" דרוהוביטש תרע. פרסם מאמרים ב\"רבותינו שבגולה\" - פרשבורג תרעה."},{"i":26580,"n":"כץ, בנימין בישקא מאורלי","b":"בניו: ר נחמן מאורלי, ור שבתי משנאדאווה ואורלי בעל \"שבת אחים\"."},{"i":26581,"n":"כץ, בנציון מטעטש","b":"חתן ר יהודה יואל דייטש מגאניטש. חתנו - ר מאיר דייטש מגאניטש - נתניה."},{"i":26582,"n":"כץ, בצלאל מאוסטרהא","f":"נפתלי - סמיכת חכמים","dt":"תעז - כא סיון","dp":"אוסטרהא","b":"חתן ר יואל הלפרין מאוסטרהא. אב\"ד ור\"מ באוסטרהא על מקום חותנו ואביו. הסכים על \"פני משה\" לקרובו ר משה בן ישעיה כץ מפרמישלא, \"על \"של\"ה\" פפד\"א-תעז. נפטר צעיר בחיי אביו. רבנים: ר יצחק איזיק הכהן ר\"מ בקלויז הגדולה באוסטרהא, ר נחמן הכהן, ר יוסף-חתנו של ר יהודה מייזלש ממיר. חתניו: ר דב בר בן ר שמואל ר יעקליש מאוסטרהא, ר משה רוקח מזלטשוב, ר יוסף לנדא מקלימנטוב-אחי של בעל \"נודע מיהודה\"."},{"i":26583,"n":"כץ, בצלאל מיאס","f":"ישעיה כץ","b":"רב ביאס והמדינה-תק\"י"},{"i":26584,"n":"כץ, בצלאל מראקישוק","f":"יוסף מראקישוק","bt":"תרד","dt":"תש","b":"רב בראקישאק(=ראקישוק) בקהלה החסידית על מקום אביו - במשך עשרות שנים. חסיד ליובאביץ. חתנו ר אברהם מאירוביץ על מקומו אחריו."},{"i":26585,"n":"כץ, ברוך מברוד","dt":"תקכ","b":"דרשן,מגיד בברוד"},{"i":26586,"n":"כץ, גבריאל מזאמטר","f":"יעקב","k":"בעל דרשות גברא","bt":"תקמד","bp":"וערשנה","dt":"תרכד - יד אייר","dp":"זאמטער","b":"רב בגנעזען, טירטשיגל, זאמטר-תקצג ועמד בראש ישיבה."},{"i":26587,"n":"כץ, דב","b":"פרסם מאמרים ב\"תבונה\" - קובנא תרפא."},{"i":26588,"n":"כץ, דב בריש הכהן מאפטא","f":"יצחק - גבורת אנשים","k":"בעריש שפתי כהנ'ס","b":"מצאצאי בעל הש\"ך. חתן הגביר ר אברהם אבלי-נכד ר יחזקאל הלוי מקרוטשין. מגדולי חריפי דורו, רב בפינטשוב-תקל, סטבניץ, אפטא. בניו - ר יצחק, ר יצחק אברהם (נקרא יצחק ע\"ש אחיו שנפטר) בעל \"כתר כהונה\"על מקומו אחריו. מצאצאיו החלו לכנות עצמם - רפפורט."},{"i":26589,"n":"כץ, דב בריש מראקוב ופינטשוב","f":"אברהם יצחק כץ","dt":"תקעה - ב אד\"ב","b":"רב בראקוב,פינטשוב"},{"i":26590,"n":"כץ, דב מדוברומיל","f":"ראובן","b":"רב בדוברומיל."},{"i":26591,"n":"כץ, דוד מגיד מקולבסוב","f":"מאיר [או ברוך]","dt":"תקפז","b":"רב בקולבסוב-תקסג, רדומישל-תקסה, נכדו ר פנחס בן מאיר על מקומו אחריו."},{"i":26592,"n":"כץ, דוד מדולינא","f":"מנחם מנדל","b":"רב בדולינא-תקפא."},{"i":26593,"n":"כץ, דוד מחנטשין","f":"דוב בעריש כץ","b":"רב בחנטשין-תק\"צ"},{"i":26594,"n":"כץ, דוד ממטרסדורף","f":"צבי הירש","k":"בעל מנחת כהן","b":"רב במטרסדורף-תר\"כ"},{"i":26595,"n":"כץ, דוד צבי מרדומישל","f":"פנחס","b":"רב ברדומישל על מקום אביו, בנו ר משה על מקומו אחריו."},{"i":26596,"n":"כץ, הלל מלבוב","f":"יצחק","dt":"תב - יג ניסן","dp":"לבוב","b":"ר\"מ ודיין בלבוב. חתם-שצט עם ר שמואל זאנויל אוירבך, ור יעקב קצנלנבוגן."},{"i":26597,"n":"כץ, הלל מצפת","f":"שמואל","b":"נמנה בין העולים לצפת עם ר מנחם מנדל משקלוב, וחתם-תקעג בענין ר יוסף יעקבקא פרנקל מברסלוי."},{"i":26598,"n":"כץ, זאב וולף","dt":"תקיב - ה טבת","b":"ראב\"ד בקרקא"},{"i":26599,"n":"כץ, זאב מטרנופול","b":"פרסם מאמרים ב\"עטרת תפארת\" - פודוולוטשיסק-בילגוריי תרצא."},{"i":26600,"n":"כץ, זושא זיסקינד","f":"דוב בערים כץ","b":"רב-שנת תק\"פ"},{"i":26601,"n":"כץ, חיים","f":"שמואל","b":"מצאצאי ר גומפריך. תלמיד ר שמעון וינר, נסמך-תריב מאת ר יעקב הרצוג מאבניא."},{"i":26602,"n":"כץ, חיים דוד זאב","dt":"תש","b":"רב בדובראווא"},{"i":26603,"n":"כץ, חיים הלוי מפומפיאן","f":"יהודה ליב נח מזאסלי","k":"בעל עונג חיים","bt":"תריד","bp":"ז'וסלי-ליטא","dt":"תרצב - ב אד\"ב","b":"חתן הגביר ר יוקיל סגלובסקי מקובנא. נסמך מאת: ר יצחק אלחנן מקובנא ועסק אצלו בהוראה. רב בגודלבה(=געויא)-פלך סובאלק-תרמא, איווייה(=וועויא)-פלך וילנא, פומפיאן-פלך קובנא-תרמט. דרשן, מראשוני הרבנים הציונים בליטא ודרש למען הציונות. חיבר גם \"מסלות חיים\", \"ישועת חיים\", ועוד. בניו: ר יוסף הלוי מגלובוק, ר שמריהו מויזון, ר משה יונה מסרדניק, ור שמואל מנחם מוילון ופולנגן. נכדו ותלמידו ר אהרן יצחק כץ הלוי רב בפולנגן."},{"i":26604,"n":"כץ, חיים מאוסטרהא","f":"נפתלי - סמיכת חכמים","b":"יש אומרים שלא היה בן כזה."},{"i":26605,"n":"כץ, חיים מוילנא וירושלים","f":"טוביה","k":"חיים פאקראוער","dt":"תקעג - כח תמוז","dp":"צפת או ירושלים","b":"חתן ר אברהם בן משה ציפקעס (אצל ריבלין - חתן שפרינצא בת ר שמחה כץ רפפורט). מתלמידי הגר\"א, רב בפוקרוי, דיין בוילנא, התכתב עם ר אברהם דנציג המזכירו בספרו \"נשמת אדם\", בספר \"עליות אליהו\" מסופר שר חיים היה הולך מדי יום לשמוע את שיעורי הגר\"א במכילתא. הסכים על ספר \"תולדות אדם\" לר יחזקאל המגיד מוילנא. בשנת תקע עלה לירושלים בשיירת ר ישראל משקלוב. (בספר \"עיר וילנא\" מסופר שנפטר בירושלים תקעג). חתם ראשון על הכרוז ליהודי רוסיה וליטא לתמוך בישוב בצפת, ובביהמ\"ד ע\"ש הגר\"א בצפת. הניח פירוש לתלמוד ועל השו\"ע - בכת\"י בידי נכדו ר לוי חיים רוקח דיין בוילנא. ישב בדין-תקנה במחלוקת בין החסידים והמתנגדים בוילנא יחד עם חברו ר יהודה ליב בן יצחק כץ (=ליבלי רומשיסקער) - כאשר מצד החסידים היה ר מאיר רפאל'ס ומצד המתנגדים ר ליבלי ר בער'ש."},{"i":26606,"n":"כץ, חיים מיברוב ולבוב","f":"יקותיאל זיסקינד","b":"חתן ר חיים הלוי מיברוב. רב ביאבורוב(=יברוב), נמרוב(=נעמרוב), ראב\"ד בלבוב, ראש מדינה דגליל לבוב, וראש דד\"א-תפו. לפי ר יוסף לוינשטין - אולי אחיו ר רפאל הכהן בעל \"ושב הכהן\"."},{"i":26607,"n":"כץ, חיים ממגרוב","bt":"תרמח","bp":"מגרוב","dt":"תשה","b":"חתן ר ישראל חיים רוזנפלד מפאקש-תרע. מחכמי אונגוואר סוחר מצליח ואיש חסד. נספה בשואה."},{"i":26608,"n":"כץ, חיים מפרג","f":"יצחק כץ","dt":"רע - כח תשרי","dp":"פרג","b":"ממגורשי קושטא? מרביץ תורה בפרג. נהרג עק\"ה סמוך לעיר צחיטא(=צוויטאוי). בנו - ר מרדכי גרשון מוינה. אחיו - ר עקיבא מאויבן."},{"i":26609,"n":"כץ, חיים שמואל מארה\"ב","b":"פרסם מאמרים ב\"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה."},{"i":26610,"n":"כץ, יהודה","f":"נפתלי מפרג ולובלין","b":"אחיהם של ר פנחס מפולדא, ר יצחק מסטפין, ר חיים מפוזנא, ר מרדכי מברודא."},{"i":26611,"n":"כץ, יהודה ליב מפלאצק","f":"יצחק כץ מלובלין","b":"רב בפלאצק"},{"i":26612,"n":"כץ, יהודה ליב משברשין","b":"רב בשברשין-תס\"א"},{"i":26613,"n":"כץ, יהודה מאוסטרהא","f":"שלמה זלמן","k":"ר יהודה ר יוקבת","dt":"תעט - ח תשרי","dp":"אוסטרהא","b":"חתן ר יעקב-יוקבת חסיד מאוסטרהא. מחכמי ונכבדי קראקא. בנו של ר שלמה זלמן כץ שהיה אבי משפחת זוסמן, ובנו ר שלמה זלמן שהיה ר\"מ באוסטרהא."},{"i":26614,"n":"כץ, יהודה מלמברג","dt":"שעה - כו ניסן","b":"רב בלבוב"},{"i":26615,"n":"כץ, יהודה מסנוק","f":"יעקב מאיר","k":"בעל קול יהודה","bt":"תר","dt":"תרסט","b":"מחסידי ר חיים מצאנז, סירב להצעת רבו לרבנות דוקלא (ותולה בסירוב את השריפה שכלתה את רכושו), רב בסנוק. חיבר \"קול יהודה\" מונקטש תרסז. מתורתו ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז."},{"i":26616,"n":"כץ, יהודה פסח מלענשנע","k":"בעל קרבן פסח","b":"רב בלענטשנע"},{"i":26617,"n":"כץ, יהושע השל ריינס מהורדנא","f":"אריה ליב","k":"בעל ישועות יהושע","bp":"גרודנא","dt":"תקעג - ז ניסן","dp":"הורדנא","b":"רב בהורדנא. תלמיד ר אלכסנדר זיסקינד בעל \"יסוד ושורש העבודה\". הגיה את באור הגר\"א לנביאים, ולמשניות. חיבר \"ישועות יהושע או מעיני יהושע\" על \"שנות אליהו להגר\"א."},{"i":26618,"n":"כץ, יהושע זאב הכהן מוארשא","f":"יהודה ליב","k":"בעל דברי רבית","b":"מחכמי וארשא, חיבר גם \"מורה קריאת התורה\"."},{"i":26619,"n":"כץ, יהושע ממאקווא","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":26620,"n":"כץ, יהושע מסמבאטהעלי","k":"בעל ויאמר יהושע","b":"רב בסמבאטהעלי, ניו יורק, ובנו ר אשר אנשיל בעל \"שמן ראש\" על מקומו אחריו."},{"i":26621,"n":"כץ, יהושע מקראקא","f":"שלום שכנא הכהן -רש\"ך","bt":"תי","dt":"תצה - יא כסלו","dp":"קראקא","b":"ראב\"ד בקראקא."},{"i":26622,"n":"כץ, יואל מאוסטרהא","f":"נחמן מאוסטרהא","dt":"תקסא - ג אלול","dp":"אוסטרהא","b":"נכד ר בצלאל כץ מאוסטרהא ונינו של ה\"סמיכת חכמים\". רב בביחוב, דיין באוסטרהא מאנשי קלויז הגדולה. הסכים על \"משנת חכמים\", ועוד. חתם הרבה בפנסקי הח\"ק. (ב\"דעת קדושים\" נכתב עליו כנראה בטעות כי היה ממשפחת רפפורט ובנו של ר נחמן מויסוקי)."},{"i":26623,"n":"כץ, יואל מסטניסלב ואנטניא","f":"יצחק אייזיק מאוסטרהא","dt":"תקל - יז כסלו","b":"מצאצאי מהר\"ל מפרג. חתן ר דב בר מצורטקוב-(בן ר אברהם סגל מהארחוב ולבוב). רב באנטניא, התקבל לסטאניסלב וטבע בדרך בנהר. בניו: ר יצחק איזיק הכהן מקוריץ בעל \"ברית כהונת עולם\", ר משולם הכהן מזורוונע קוריץ, ולבוב בעל \"פתחי נדה\", ר יהודה ליב הכהן מבולחוב,וסטרי."},{"i":26624,"n":"כץ, יואל מערדעד","f":"מאיר הכהן מנווטלנפלו","k":"בעל טירת כסף","bt":"תרנב","bp":"תרנב","dt":"תשד - ט סיון","b":"תלמיד השב\"ס, ור שלמה זלמן עהרנריך משימלויא, ר יהודה גרינוולד בסטמר, ר שמעון גרינפלד בסמיהאי, ועוד. חתן ר יהודה ליב וינברגר מניגערשט. דיין בניגרעשט ליד חותנו ורב בטשערטעז הסמוכה-השייכת לגליל חותנו והתגורר בניגרשט, רב בערדעד(=ארדד=ארדוד)-ליד סטמר. נחשב למומחה בעניני גיטין ועגונות, והיה מסדר הגיטין של העיר סטמר (משום שבעיר סטמר לא נערכו גיטין בגלל בעיה עם שם העיר המדוייק - סאטו מארה). מקורב לציונות. נספה בשואה. חיבר \"טירת כסף\", \"פרדס רמונים\", ועוד. בנו ר פנחס חיים כץ רב בערדעד לצדו. וחתנו ר שמואל טיטלבוים אב\"ד ניגרעשט. פרסם מאמרים ב\"לקט ששנ\"ה\" - סטמר תרצד."},{"i":26625,"n":"כץ, יוזאפ מהנובר","b":"רב בהנובר,אלטונא-תק\"כ"},{"i":26626,"n":"כץ, יוזמן מניישטט","b":"מגדולי חכמי אשכנז,מרביץ תורה בנוישטט-ר\"כ"},{"i":26627,"n":"כץ, יום טוב","k":"הו\"ל עולת שבת","b":"הוציא לאור \"עולת שבת\" לר יואל ן שועיב. ?? לא באוצר ??"},{"i":26628,"n":"כץ, יונתן מסעליש","b":"פרסם מאמרים ב\"המגיד\" - סטמר תרפח-תרצט."},{"i":26629,"n":"כץ, יוסף (ראה גם ויס, יוסף)","b":"סופר סת\"ם ברדיחוב-תרלד."},{"i":26630,"n":"כץ, יוסף יוזפא מוינה","f":"יהושע פאלק- הסמ\"ע","k":"בעל כתנת פסים","dt":"שצט - יח אדר","b":"מחכמי וינה. הו\"ל ספרי אביו \"דרישה ופרישה\" עם הערות ממנו בשם \"כתנת פסים\" לובלין שצה. בנו - ר שלמה בעל תפארת הקדש."},{"i":26631,"n":"כץ, יוסף יצחק מדומברובה","f":"אברהם אבלי-זכרון אבר","bt":"תקצז","b":"נתייתם בילדותו וגדל אצל ר ליבוש מטומשוב. נסמך מאת: ר יצחק שמלקיש מלמברג. חתן ר נחום צבי-חתנו של ר חיים דוד קלוגר מגריידינג. רב בדומברובה?(=דאבראטוואר-ליד קאמניקא)-תרך, יאנוב-תרלו."},{"i":26632,"n":"כץ, יוסף מאמשטרדם","b":"דיין באמסטרדם-תס\"ט"},{"i":26633,"n":"כץ, יוסף מהנובר","b":"חתן ר אליהו פאלק מהמבורג. רב בהנובר והמדינה-תנט."},{"i":26634,"n":"כץ, יוסף מירושלים","b":"מגדולי ירושלים-תק\"כ"},{"i":26635,"n":"כץ, יוסף מפוליען-ריסקובה","b":"רב בפוליען-ריסקובה-תרלה."},{"i":26636,"n":"כץ, יוסף מקולומיי","b":"רב בקולומיי-ש\"צ"},{"i":26637,"n":"כץ, יוסף מקראקא","f":"מרדכי גרשון מוינה","k":"בעל שארית יוסף","bt":"רעא","dt":"שנא - ג שבט","dp":"קראקא","b":"לאחר פטירת אביו גדל אצל ר יואל שנשא את אמו. חתן ר משה עברליש, גיסו של הרמ\"א. מגדולי דורו, אב\"ד וראש ישיבה בקראקא כ-50 שנה. בניו: ר אהרן מנחם מקראקא, ר תנחום מקראקא, ר אהרן משה מקראקא, חתניו - ר שלמה חריף מלבוב, . מחותנו - ר דוד זלצבורג. דודו(=בעל אחות אמו) - ר משה יפה מקראקא (זקנו של הב\"ח)."},{"i":26638,"n":"כץ, יוסף מראקישוק","f":"מאיר","b":"רב הקהילה החסידית בראקישוק, ובנו ר בצלאל על מקומו אחריו."},{"i":26639,"n":"כץ, יוסף פנחס ממאדין","b":"שו\"ב במאדין-תרנט, קנטשוגה-תרסג."},{"i":26640,"n":"כץ, יוסף ראובן הלוי מגלובוק","f":"חיים מפומפיאן-עונג ח","bt":"תרלז","bp":"גודלווה(=גודלאווה)","dt":"תשא","b":"חתן ר מיכל יפה מנישינטא-פלך קובנא. רב בוישינטה(=נישינטא)-תרסג, אב\"ד גלובוק. חבר \"המזרחי\" בוילנא. נספה בשואה."},{"i":26641,"n":"כץ, יוסף שמואל מניקלשבורג","bt":"תקך - בערך","b":"תלמיד בעל מחצית השקל, ר מרדכי בנט - והדפיס את תשובותיו. דיין בניקלשבורג מעל 40 שנה. בנו - ר משה ליב מניקלשבורג."},{"i":26642,"n":"כץ, יחזקאל מזולקוא","f":"ר\"מ","b":"מחכמי זולקוא, נזכר-תנא בין חמשה שומרי התקנות ונקרא האלוף הראש."},{"i":26643,"n":"כץ, יחזקיה הכהן מוורבוי ובעלעד","k":"בעל מגדנות חזקיהו","b":"מקובל, מו\"צ בוורבוי, יעמרינג?, רב בבעלעד-תקץ ומחוז רעבוי. התכתב עם החת\"ס. חתנו - ר זליג ליב פנחס יהודה פייפר."},{"i":26644,"n":"כץ, יחיאל חיים מקרליפקה","b":"רב בקרליפקה."},{"i":26645,"n":"כץ, יחיאל מזלין","b":"רב בזלין-תרלד."},{"i":26646,"n":"כץ, יחיאל מיכל","b":"פרסם מאמרים ב\"זהב הארץ\" - ירושלים תרסט."},{"i":26647,"n":"כץ, יחיאל מיכל מוילנא","f":"שמעון","bt":"תרנז","bp":"אולשאן","dt":"תשב","dp":"פונארי","b":"תלמיד ישיבות שטוצין, גרודנא, סלובודקה, וחברון. חתן ר שלמה הכהן מוילנא. רב בוילנא. נספה בשואה. מתורתו בספר אחיו ר ראובן כץ - \"דגל ראובן\"."},{"i":26648,"n":"כץ, יעקב"},{"i":26649,"n":"כץ, יעקב בעל התוספות","k":"ר' יעקב כץ הזקן","dt":"קט","b":"עק\"ה,מגדולי התורה באשכנז בגורטנהויזן"},{"i":26650,"n":"כץ, יעקב יהודה מרימנוב","f":"זאב וולף","dp":"קליינוארדין","b":"רב ברימנוב."},{"i":26651,"n":"כץ, יעקב יוסף מאנאד","f":"יהודה אריה ליב","bt":"תקץ","bp":"טיבאלד דאראץ","dt":"תרן - כג אדר","dp":"אנאד","b":"תלמיד הכת\"ס, ור שמואל שלזינגר קיצע משאהל, ור יהושע מורפעלעט. חתן ר מאיר כהן. רב באברהאם. רב בשאהל על מקום רבו (שנאלץ להיכנס לעסקי חותנו). רב בנעמעשביק(=נאמאשי), רבה הראשון של אנאד-תרך, חתנו ר חיים מאיר שיק על מקומו אחריו. בנו - ר אליהו קאהן מואראש-נאמעני."},{"i":26652,"n":"כץ, יעקב מאוסטיטשקי","b":"רב באוסטיטשקי. חתן המגיד הקדוש ר בנימין ב\"ר אבא הכהן ממנוסטרישץ."},{"i":26653,"n":"כץ, יעקב מאלטונא","f":"משה","bt":"תקסח","bp":"אלטונא","dt":"תרסו - יא תשרי","dp":"אלטונא","b":"ממשפחת ר שמואל עלקאן בעל \"מקום שמואל\", ומצאצאי ר ברוך כהנא. תלמיד החת\"ס. רב באלטונא-תרז וראב\"ד (באופן זמני) שם-תרלג על מקום ר יעקב עטלינגר - בעל \"ערוך לנר\". מתורתו במשניות אלטונא תרה, בשו\"ת החת\"ס, ב\"שומר ציון\". בנו - ר אהרן כץ - רב באיכנהויזן (ביירען). גיסו - ר ישעיה הולנדר."},{"i":26654,"n":"כץ, יעקב מזולקוא (פלק)","f":"שמואל אלכסנדר מלבוב","b":"נכד הסמ\"ע. מחכמי זולקוא, חתם-תם על תקנה בענין הכנסות השמשים בקהלה."},{"i":26655,"n":"כץ, יעקב מפלאצק","f":"יהודה ליב כץ","b":"רב בפלאצק-תץ על מקום אביו."},{"i":26656,"n":"כץ, יעקב מצעהלים ופרשבורג","b":"מחכמי פרשבורג, חתם-תקסז על כתב מנוי רבנות לחת\"ס."},{"i":26657,"n":"כץ, יעקב מקליקול","f":"ישראל","bt":"תרכג","bp":"רומשישוק-ליטא","dt":"תרפג - י תשרי","dp":"וילדינגן-גרמניה","b":"מגדולי המוסר בליטא. תלמיד ישיבות קובנא, וולוזין, קלם. תלמיד ר יצחק בלזר. ר\"מ בישיבת ר הירשל בסלובודקה, משפיע רוחני בישיבת טלז-תרס, רב בקליקול-תרסו, נדד עם ישיבה מריגא להומל וכיהן בה כר\"מ. רב בקליקול-תרף, זאגר חדש על מקום ר בן ציון פלדמן. מבניו: ר שלמה כצ'ס מפתח תקוה, ר דב כץ בעל \"תנועת המוסר\"."},{"i":26658,"n":"כץ, יעקב משה מקרוסנו","b":"רב בקרוסנו-תרכו."},{"i":26659,"n":"כץ, יעקב צבי מסובוסלו ואמשטרדם","f":"שלמה מסובוסלוי","k":"בעל לקט הקמח החדש","dt":"תשכד - ו כסלו","b":"נכד ר יעקב צבי מסאביסלוי. רב בסובאסלו(=סאביסלוי)-תרף על מקום אביו, סאראסלויא, ניצל מהשואה ואחריה רב הקהלה החרדית באמשטרדם. פרסם מאמרים ב\"המעין\" - בודפשט תשז (לאחר השואה!).","bk":[["לקט הקמח החדש [על שו\"ע או\"ח]",""]]},{"i":26660,"n":"כץ, יעקב קופל מסטאנוב","b":"רב בסטאנוב-תקט\"ז"},{"i":26661,"n":"כץ, יצחק איזיק מאוסטרהא","f":"בצלאל אב\"ד אוסטרהא","dt":"תצה - ו כסלו","dp":"אוסטרהא","b":"נכד ר נפתלי כץ מאוסטרהא. חתן ר יהודה ליב איטינגא מלבוב, ובזיוו\"ש חתן קרובו ר יהודה ליב בן ר אשר ענזיל מאוסטרהא. תלמיד ר יעקב עמדין (היעב\"ץ) בלבוב. רב באוסטרהא על מקום חותנו שעבר לסלוצק-תפב בערך. הסכים על \"עולת אהרן\"-תצא. בנו ר יואל כץ מאנטאני וסטניסלב. חתנו - ר נחום מצויזמיר."},{"i":26662,"n":"כץ, יצחק איזיק מפרוסטיץ","f":"נפתלי - סמיכת חכמים","b":"יש אומרים שלא היה בן כזה."},{"i":26663,"n":"כץ, יצחק איזיק מקראקא","dt":"תקעב - י כסלו","b":"הדיין הגדול בקרקא"},{"i":26664,"n":"כץ, יצחק איזיק משערשוב","f":"יעקב כהן גדול מואלפא","k":"בעל שערי יצחק","dt":"תריח - י אדר","b":"שם משפחתו גם אלכסנדרובסקי (ע\"ש שושלת הכהונה של משפחתו עד אלכסנדר הכהן מזמן שמעון הצדיק). תלמיד ר משה משרשקוב(=שארשוב), ור נח מלכוביץ. רב בשארשוב. בניו - ר ישראל שלמה זלמן אלכסנדרובסקי משארשוב, ר צבי אריה."},{"i":26665,"n":"כץ, יצחק הכהן מקושטא או שלוניק","f":"עקיבא מספרד","b":"רב במגרש גלאטי ופערא בקושטא-רכ? בנו - ר עקיבא כץ מאויבן ופרג."},{"i":26666,"n":"כץ, יצחק הכהן מריפין","b":"פרסם מאמרים ב\"דגל הרבנים\" - וארשא תרפו."},{"i":26667,"n":"כץ, יצחק הקטן מלובלין","b":"עק\"ה,רב בלובלין-שמ\"ז"},{"i":26668,"n":"כץ, יצחק מארץ ישראל","b":"פרסם מאמרים ב\"תורת ארץ ישראל\" - ירושלים תרץ."},{"i":26669,"n":"כץ, יצחק מבומסלא","f":"בנימין כץ מחוקק","dt":"שצד - ז שבט","b":"רב בבומסלא"},{"i":26670,"n":"כץ, יצחק מזולקוא","f":"שלמה","b":"מחכמי זולקוא, חתם-תפב עם ראשי הקהלה, ובשנת תקג על בחירת ראשי העדה."},{"i":26671,"n":"כץ, יצחק מטוטשין","f":"אברהם דב בערשי למברג","b":"חתן הרב גולובה מטוטשין. רב בטוטשין על מקום חותנו. נספה בשואה. פרסם ב\"טאגבללאט\" ו\"איד\"."},{"i":26672,"n":"כץ, יצחק מלבוב","b":"רב בלבוב-ש\"מ"},{"i":26673,"n":"כץ, יצחק מסטנוביץ ופינטשוב","f":"דב בריש מפינטשוב","bt":"תקג","dt":"תקלד - כה שבט","b":"מצאצאי בעל הש\"ך. רב בסטאבניץ,פינטשוב. בנו ר דוד זאב רפפורט. (באהלי שם - הוא אחיו של ר אברהם אבלי בעל \"כתר כהונה\" - והוא שהיה רב בסטנביץ ופינטשוב)"},{"i":26674,"n":"כץ, יצחק מפודהייץ","f":"משה - נקודות הכסף","k":"הו\"ל גבורות אנשים","b":"נכד בעל הש\"ך, ונכד ר מאיר בן שאול וייל - אב\"ד בריסק. חתן ר משה סגל מזאבריז-בנו של ר למל מוילנא. רב בפודהייץ, (סטאבניץ, אפטא-תנז?). לפי מרקוביץ - חתן ר משה בן מרדכי ז\"ק מונגרוב ומינסק."},{"i":26675,"n":"כץ, יצחק מפינטשוב","dt":"תטו","b":"רב בפינטשוב. נרשם בין מצבות קראקא אבל לא נפטר שם."},{"i":26676,"n":"כץ, יצחק מפרג - הזקן","f":"שמשון","k":"בעל פירוש למדרש","bp":"פרג","dt":"שפד - יב-ד סיון","dp":"פרג","b":"מצאצאי ר עקיבא מאובן. חתן מהר\"ל מפרג. רב בניקלשבורג ומדינת מורביה, וינה, ראב\"ד בפרג. בתו - חוה - מלומדת כאחד הגאונים המפורסמים - אשת ר שמשון בכרך. בניו: ר חיים הכהן מפוזנא, ר נפתלי כץ מפינסק ולובלין. מנכדיו - ר יאיר בעל חות יאיר."},{"i":26677,"n":"כץ, יצחק מפרג - הנכד","f":"נפתלי מפרג ולובלין","dp":"לובלין","b":"דרשן בפרג, רב בסטעפין ובנו ר נפתלי על מקומו אחריו, דרשן ור\"מ בלובלין-תמ."},{"i":26678,"n":"כץ, יצחק מקראקא","f":"שלום","dt":"שסא - כד טבת","dp":"קראקא","b":"מחכמי קראקא."},{"i":26679,"n":"כץ, יקותיאל זלמן מקלצק","b":"מגדולי חכמי קלצק-תק\"פ"},{"i":26680,"n":"כץ, ירחמיאל הכהן מאוסטרהא","f":"שלמה זלמן","dt":"תצו - ב חשון","dp":"אוסטרהא","b":"מחכמי אוסטרהא. אחיו של ר יהודה ר יוקבת כץ. נפטר צעיר."},{"i":26681,"n":"כץ, ישכר בער משברשין וחברון","f":"נפתלי","k":"בעל מתנות כהונה","bp":"שברשין (פולין)","dp":"חברון","b":"מחכמי פולין, למד בבית מדרש הרמ\"א. רב בשעברשין-שנז, עלה לארץ-שם בערך, היה מתלמידי ר משה קורדובירו, רב בחברון. חיבר \"מתנות כהונה\" קראקא שמו, ועוד. (לדעת לונץ - לא הגיע לארץ). נכדו - ר אברהם בן אליעזר בעל \"אורי וישעי\" הו\"ל את ספרו \"מראה כהן\"."},{"i":26682,"n":"כץ, ישעיה מדוקלא","b":"רב בדוקלא-תרנו."},{"i":26683,"n":"כץ, ישעיה מוורצקי","b":"דומ\"צ בוורצקי-תר\"י"},{"i":26684,"n":"כץ, ישעיה מיאקא","b":"רב ביאקא-תקפב, נזכר אצל החת\"ס שהשיב לו ולחבריו ר משה אריה ליב מגלנטא(=גלאנדע), ור יוסף מסערער."},{"i":26685,"n":"כץ, ישעיה מלובלין","f":"יצחק כץ","b":"מחכמי לובלין-ת\"פ"},{"i":26686,"n":"כץ, ישראל מואדיסלב","b":"רב בוואדסלב-תקס\"ז"},{"i":26687,"n":"כץ, ישראל מלמברג","f":"אברהם דב בערשי למברג","k":"יה\"ן","b":"מעסקני המזרחי בלמברג. השתתף ב\"בית יעקב\"-לודז - בשמו הספרותי יה\"ן. ניצל מהשואה ועבר לניו יורק. עלה לירושלים."},{"i":26688,"n":"כץ, ישראל מסערדאוהל","dt":"תרז - בערך","b":"תלמיד החת\"ס. מחכמי סערדאוהל. והאב\"ד ר יהודה אסאד מכנהו בשם \"קדוש ישראל\". חתנו - ר מנחם דונט מנייטרא."},{"i":26689,"n":"כץ, ישראל מפומפיאן","f":"יהודה","b":"רב בפומפיאן-ליטא."},{"i":26690,"n":"כץ, ליפמן מסאבודקה","b":"רב בסאבאדקה-תקע\"ב"},{"i":26691,"n":"כץ, מאיר הכהן ממוהילוב ודובנא","f":"משה אשכנזי מדאנהויזן","k":"בעל גבורת אנשים","r":"אב\"ד אמסטוב","dt":"תג - ג כסלו","dp":"דובנא","b":"רב באמסטיבאווי(=אמסטובאווי), מאהילוב(=מוהילוב), דובנא-תב על מקום ר צבי הירש בן עוזר, ור יהודה החסיד (שנהרג בגזרות תח) על מקומו אחריו. בניו - ר שבתי בעל הש\"ך, ר יונה נחום מסוכטשוב, חתנו - ר יצחק א\"ש ונכדו ר מאיר בעל \"פנים מאירות\".","bk":[["שאלות ותשובות - נדפסו בתוך ספר גבורת אנשים",""]]},{"i":26692,"n":"כץ, מאיר מחעלמא ובלז","f":"משה ירמיה מנראל","b":"אחיו של ר טוביה בעל \"מעשה טוביה\". רב בחעלמא, בעלזא-תס?. בנו - ר אברהם רפפורט. (בלבול עם ר מאיר בן משה ירמיה רפפורט - ראה בערכו)."},{"i":26693,"n":"כץ, מיכל מוילנא","dt":"תשג","b":"רב בוילנא."},{"i":26694,"n":"כץ, מנחם","b":"רב דמדינת רוסיה-תקע\"א"},{"i":26695,"n":"כץ, מנחם מבריסק","f":"בנימין","b":"אב\"ד בריסק-תנה. הסכים על \"נפתלי שבע רצון\". אחיינו - ר אליהו בעל יד אליהו (שנפטר בחברון) המזכירו בספרו."},{"i":26696,"n":"כץ, מנחם מואנילוב","b":"דיין בואנילוב, חתם-תלג עם ר אהרן בן צבי הירש סגל, ר שניאור פיבש בן דוד הקדוש."},{"i":26697,"n":"כץ, מנחם מנדל מאונסדורף","b":"ראב\"ד באונסדורף-תר\"כ"},{"i":26698,"n":"כץ, מנחם מנדל מזולקוא","f":"יהודה ליב","b":"מחכמי זולקוא, חתם-תסד בפנקס הקהלה."},{"i":26699,"n":"כץ, מנחם מנדל מפרשבורג","f":"אברהם מפרשבורג","dt":"תרכז - יב אייר","dp":"פרשבורג","b":"תלמיד החת\"ס. סופר הבי\"ד ונאמן הקהלה בפרשבורג במשך מז שנה, בנו ר פנחס על מקומו אחריו. בנו ר יהודה ליב בעל \"יושר דברי אמת\"."},{"i":26700,"n":"כץ, מרדכי","b":"רב-שנת ש\"ס"},{"i":26701,"n":"כץ, מרדכי","bt":"1885","bp":"שקומיאן-ליטא","dt":"1954","b":"תלמיד ישיבות וילקומיר, וילנא. פעיל בתנועת ס.ס. בוילקוביסק. פרסם ב\"הצפירה\", \"הזמן\", ועוד. היגר לארה\"ב דרך יפן, פרסם מאמרים בעתוני התקופה."},{"i":26702,"n":"כץ, מרדכי ברוך","f":"אברהם דב בערשי למברג"},{"i":26703,"n":"כץ, מרדכי גרשון מוינה","f":"חיים מקושטא","b":"ממגורשי וינה. דיין בקראקא-שנת ש'. בנו - ר יוסף מקראקא בעל \"שארית יוסף\"."},{"i":26704,"n":"כץ, מרדכי הכהן מברודא ופוזנן","f":"נפתלי - סמיכת חכמים","k":"יעקב מרדכי (באוצר)","b":"רב בברוד-מהרן, פוזנא. חתן ר משולם-חתנו של הרבי ר השל. חתנו היה ר יעקב עמדין-היעב\"ץ. הסכים על \"אבן השהם\". (ראה גם: יעקב מרדכי מפוזנא)."},{"i":26705,"n":"כץ, מרדכי מאפטא","f":"נתן נטע כץ","b":"רב באמסטיבווא,אפטא-ת\"נ"},{"i":26706,"n":"כץ, מרדכי מבירטש","b":"רב בבירטש-תרלז."},{"i":26707,"n":"כץ, מרדכי מוונגרוב","f":"מהר\"מ","b":"מחכמי וונגרוב."},{"i":26708,"n":"כץ, מרדכי מלבוב","f":"דוד","dt":"שצא - א ניסן","dp":"לבוב","b":"ר\"מ בלבוב. היה בין המשיבים בענין אילנות בבית העלמין יחד גדולי דורו ובהם בעל תוי\"ט. נזכר ב\"איתן האזרחי\", וב\"משאת בנימין\"."},{"i":26709,"n":"כץ, מרדכי מלבוב","f":"שמרל מלבוב","dt":"תסג - ד כסלו","dp":"לבוב","b":"מחכמי לבוב. גיסו של ר יעקב יהושע פאלק בעל פני יהושע (?)."},{"i":26710,"n":"כץ, מרדכי מפרוינקירכן","dt":"תקלא - יז אייר","b":"רב בפרוינקירכן"},{"i":26711,"n":"כץ, מרדכי מפרוסטיץ וזולקוא","f":"משה","k":"בעל דרך ים התלמוד","b":"הו\"ל חידושי מהרש\"א עם תוספות ממנו בשם \"דרך ים התלמוד\" זולקוא תנב."},{"i":26712,"n":"כץ, משה","f":"יהושע פאלק- הסמ\"ע","b":"חתן ר דוד בן מרדכי. רב-שנת שצה."},{"i":26713,"n":"כץ, משה הכהן מבריסק ולויצק","f":"מרדכי גרשון או פסח","b":"רב בקלויז השר שאול וייל בבריסק, אב\"ד סלוצק, לוצק-תכד. הסכים על \"עמודיה שבעה\" דירנפורט תנג. בניו - ר יוסף, ר יהודה ליב, חתנו - ר אברהם מלונטשיץ."},{"i":26714,"n":"כץ, משה יהודה מסערדהאלי","f":"אשר אנשל כץ","k":"בעל ויגד משה","bt":"תרסז","dt":"תשד - כז סיון","b":"מרביץ תורה בסרדאהעלי. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":26715,"n":"כץ, משה יונה הלוי מסרדניק","f":"חיים מפומפיאן-עונג ח","dt":"תרצו - חשון","b":"חתן הגביר ר נתן ליב שלאווא. רב בסרדניק. פרסם מאמרים ב\"חכמי ליטא\" - קאלואריא תרמה."},{"i":26716,"n":"כץ, משה ליב הכהן מניקלשבורג","f":"יוסף שמואל מניקלשבור","dt":"תרנ","b":"תלמיד אביו-שהיה דיין בניקלשבורג, ר יהודה אסאד, ר נחום טריבטש מניקלשבורג. מגיד, ראב\"ד בניקלשבורג. חיבר שו\"ת בכת\"י. פרסם מאמרים ב\"אוצר חכמה\" - לבוב תרך. נספד מאת ר חזקיה פיבל פלויט."},{"i":26717,"n":"כץ, משה מביאליסטוק וירושלים","f":"אברהם יהושע","k":"בעל אשי משה","b":"מחכי ביאליסטוק, עלה לירושלים."},{"i":26718,"n":"כץ, משה מדובנא","f":"יוסף","dt":"תמד - ט סיון","dp":"לבוב","b":"מרביץ תורה, רב בדובנא על מקום ר נחמן רפפורט, ור ישראל בן מרדכי יאליס על מקומו אחריו."},{"i":26719,"n":"כץ, משה מזולקוא","f":"יצחק","b":"מחכמי זולקוא, חתם-תסד על תקנת הקהלה."},{"i":26720,"n":"כץ, משה מטור-טארבש","f":"אהרן שלמה מאלמאשד","k":"בעל דברי משה","dt":"תרנה - ד אדר","b":"גיסו של ר שמלקא קליין מסעליש. חתן ר אהרן פריד מקאסני, רבה הראשון של טור-טרבש-ליד האלמין-תרל שהיה בגליל סעליש אצל גיסו. רבות מתשובותיו ב\"אהל אברהם\" למחותנו - ר אברהם קרפלס - מונקטש תרנט. מתורתו ב\"מגד ירחים\" - סיגט תרנח."},{"i":26721,"n":"כץ, משה מטיקטין ומאקובה","b":"רב בטיקטין, מאקובה. מחותן עם ר אשר קמץ - (בנו - ר משה מפארידן בעל \"פני אריה\" היה חתנו של ר אשר קמץ). ונקראו הוא ומחותנו \"הגאונים מטיקטין\"."},{"i":26722,"n":"כץ, משה מיאנוב","f":"ליב","b":"רב ביאנוב-תקפג."},{"i":26723,"n":"כץ, משה מלבוב","f":"דוד צבי","dt":"תעט - יט חשון","dp":"לבוב","b":"ר\"מ בלבוב"},{"i":26724,"n":"כץ, משה מפודהייץ","f":"שבתי - בעל הש\"ך","k":"בעל נקודות הכסף","dt":"תמו - יא חשון","b":"חתן ר מנחם מנדל מרגליות. מגדולי דורו, רב בפודהייץ, במלחמת התורכים נשרפה הקהילה ונשבתה, נסע לפפד\"א. יש אומרים שלאחר פטירתו נישאה אלמנתו לר משה זאב ממינסק."},{"i":26725,"n":"כץ, משה מפרמישלא ומזיבוז","f":"ישעיה","k":"בעל פני משה","b":"אב\"ד במזיבוז, ר\"מ בפרמישלא. דודו - ר נפתלי בעל סמיכת חכמים."},{"i":26726,"n":"כץ, משה מרדומישל","f":"דוד צבי","b":"רב ברדומישל על מקום אביו, קלן-תרצז, שוב ברדומישל-תרצח. נספה בשואה."},{"i":26727,"n":"כץ, משה מרדומישלא","b":"מתלמידי החוזה מלובלין והנועם אלימלך."},{"i":26728,"n":"כץ, משה פנחס מקינצק","b":"פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":26729,"n":"כץ, משה קאפיל מרומנאווקע","b":"פרסם מאמרים ב\"דגל התורה\" - אויבר-וישווה תרפח."},{"i":26730,"n":"כץ, משלם פיבל מגריידינג","b":"אב\"ד גריידינג-תרכה."},{"i":26731,"n":"כץ, נחמיה מארה\"ב","f":"יעקב משה קסטנביץ","bt":"תרסה","bp":"ליובאן-פלך מינסק","b":"תלמיד ישיבת סלוצק, נסמך מאת: ר אליעזר זילבר מסינסינטי, ר שמעון זיויץ, ר חיים הירש רובינשטין, ר שמעון יצחק פינקלשטין. חתן ר יצחק משה סילברמן מטולדו-ארה\"ב. היגר לארה\"ב וכיהן כרב בטולדו, ועוד. חבר אגודת הרבנים באמריקה, תנועת המזרחי, פעיל צבור."},{"i":26732,"n":"כץ, נחמן מאוסטרהא","f":"בצלאל אב\"ד אוסטרהא","dt":"תקלד - ד אדר","dp":"אוסטרהא","b":"מצאצאי ר נתן שפירא בעל מגלה עמוקות, נכד-מצד אמו ר יואל הלפרין. חתן ר חיים רפפורט מלבוב. רב בערזדוב, פרנס מחכמי אוסטרהא ואלוף הגבאים על מקום דודו ר מרדכי הלפרין בהגאון מפינסק. מבניו: ר יואל מביחוב ואוסטרהא. חתניו: ר אריה יהודה ליב בן פנחס בן ר שאול מלודמיר. נכדו - ר חיים נחמן פרנס מוילנא. הניח ספר בכת\"י שהגיע ללבוב - ולא נדפס."},{"i":26733,"n":"כץ, נחמן מאורלי","f":"בנימין בישקא מאורלי","dt":"תקעה","b":"רב באורלי(=אורלע). נכדו הו\"ל מתורתו ומתורת אחיו - ר שבתי משנאדאווה ואורלי בשם \"שבת אחים\". נספד ע\"י ר משה זאב מביאליסטוק בספרו \"אגודת אזוב\"."},{"i":26734,"n":"כץ, נחמן מבריסק","f":"שלמה","b":"מחכמי בריסק, חתם-שצט על תקנות."},{"i":26735,"n":"כץ, נפתלי הרץ","b":"תשובה אליו ממהר\"ם פדובה - שכינהו \"אהובי עמיתי ...\""},{"i":26736,"n":"כץ, נפתלי הרץ מזאמושט","k":"בעל נפתלי אילה שלוחה","b":"רב בזאמוטשט-ת\"מ"},{"i":26737,"n":"כץ, נפתלי מאוסטרהא - הזקן","b":"חתן ר יהונתן מפינסק. ר\"מ בגלוגא, אוסטרהא-תקיד. תלמידו - ר אליעזר הלוי הביא מחדושיו בספרו \"עדות ביהוסף\"."},{"i":26738,"n":"כץ, נפתלי מאוסטרהא ופוזנא הנכד","f":"יצחק מפרג ולובלין","k":"בעל סמיכת חכמים","dt":"תעט - כד שבט","dp":"קושטא","b":"נכד ר נפתלי כץ מלובלין, נינו של המהר\"ל. חתן ר שמואל שמלקא בן מאיר ז\"ק מאוסטרהא. היה שבוי בידי הטטרים ונפדה. רב בסטעפן על מקום אביו. ר\"מ באוסטרהא ובנו ר בצלאל על מקומו אחריו, רב בפוזנא-תנא, פפד\"מ-תסד, אוסטרהא-תעד - ישב אצל בנו ר בצלאל. נתקבל ראב\"ד צפת, עלה לארץ-תעח דרך קושטא ונפטר שם טרם הגיעו לארץ. הסכים על ספרים רבים. עוד מבניו: ר פנחס יצחק מפולדא, מרדכי מברודי ופוזנן, ר שמואל שמלקא מברסלא, ר שאלתיאל. חתניו: ר יעקב בן אליהו מפוזנא וטיקטין, ר סעדיה ישעיה קצנלנבוגן ממזריטש, ר זאב וולף מירלש בן משולם מירלש - אב\"ד המבורג, ר יהודה ליב אשקלס בן גבריאל מניקלשבורג שנפטר צעיר הוא ואשתו - והניחו בן ר חיים ור נפתלי אמצו לבן. חיבר גם \"ים כנרת\", \"בית רחל\", \"צוואת רבי נפתלי\", ועוד. ר נפתלי נאסר בפפד\"מ-תעא בגלל שריפה שהחלה בביתו והתפשטה בכל רחוב היהודים - ושוחרר - היו שריננו על הרב בענין זה. היה מהלוחמים בשבתאות ושותף לחרם על נחמיה חיון. ר מאיר אליעזר רפפורט-הורטשטין - שהיה מצאצאיו חיבר \"שלשלת הזהב\" לתולדותיו. (לפי רוזניס נפטר ב-כד אלול)"},{"i":26739,"n":"כץ, נפתלי מיאס","dt":"תקסט - טו אדר","b":"רב ביאס"},{"i":26740,"n":"כץ, נפתלי מפרג ולובלין - הזקן","f":"יצחק בן שמשון מפרג","k":"בעל פירות גינוסר","dt":"תי - ה תשרי","dp":"לובלין","b":"נכד המהר\"ל מפרג. דרשן בפרג, רב בפרוסטיץ(=פרוסניץ), ניקלשבורג, פינסק, לובלין - בזמן ר השל-שכיהן כראש ישיבה. היה בקשר עם בעל הט\"ז שהביא ממנו בספרו, תשובות ממנו ב\"חוט השני\". בניו - ר יצחק מפרג וסטפין, ר יהודה, ר פנחס מפולדא, ר מרדכי מברודא, ונכדו - ר נפתלי בעל סמיכת חכמים. חתנו - ר שמואל זנויל מזולקוא, אחיו - ר חיים הכהן מפרג ופפד\"מ."},{"i":26741,"n":"כץ, נתן נטע ליב מפוניבז","b":"שמש ב\"קלויז גליקל\" בפוניבז. היה תלמיד חכם שסיים 200 פעם את הש\"ס. עלה לתל אביב."},{"i":26742,"n":"כץ, נתן נטע מבריסק","f":"ישעיה כץ","b":"רב בבריסק דליטא-ת\"צ"},{"i":26743,"n":"כץ, נתן נטע מבריסק","f":"דוד","dp":"בריסק","b":"דיין בבריסק-שנות ה-תק-תר."},{"i":26744,"n":"כץ, עמרם מלעווא","f":"אברהם אליהו משה כץ","b":"רב בלעווא-תר\"נ"},{"i":26745,"n":"כץ, עקיבא הכהן מאויבן","f":"יצחק(10722)","dt":"רנו?","b":"חתן ר אברהם קצנלנבוגן מאויבן. חותנו של ר שבתי שפטל הורביץ. היה שולחני המלך מטיאש באויבן ונקרא נשיא היהודים. נאלץ לעבור מהונגריה לבוהמיה והתישב בפרג. יסד ישיבה גדולה ולימד בה - בימי ר יעקב פולק. ניצל מעלילה גם בפרג. עלה לדוכן עם 12 בניו וחתניו הכהנים. מבניו: ר גרשון אבי משפחת הגרשוני, גרשם אבי משפחת גרשם - יסד דפוס בפרג, ועוד. (לדעת ר יוסף סמבורי -ר יצחק אביו - ממגורשי גאלאטה שבקושטא, בנו של ר עקיבא כץ משלוניקי - ממגורשי ספרד, לדעת ר\"מ וייץ - כל זה אינו נכון). (בעיר וילנא מביא שהיו לו 12 בנים ו-13 חתנים והיה עולה לדוכן ואומר כ\"ה תברכו - ולעומת זאת מביא שאותו הסיפור מסופר על ר אליעזר בן שמחה הכהן - המליץ א-12.) אחיו - ר חיים מפרג."},{"i":26746,"n":"כץ, פאלק מגלאטו בהמן","b":"רב בגלאטו-בהמן-תק\"ס"},{"i":26747,"n":"כץ, פנחס הכהן מפולדא - א","f":"נפתלי מפרג ולובלין","b":"רב בפולדא. אחיהם של ר יהודה, ר יצחק מסטפין, ר חיים מפוזנא, ר מרדכי מברודא. (אולי הוא בלבול עם ר פנחס שהיה בנו של ר נפתלי בעל סמיכת חכמים)"},{"i":26748,"n":"כץ, פנחס חיים מארדד(=ערדעד)","f":"יואל מארדד","bt":"תרעו","dt":"תש..","b":"חתן ר יצחק צבי ליבוביץ מצ'אפ. רב בארדד אצל אביו. נספה בשואה."},{"i":26749,"n":"כץ, פנחס יהודה מקיראי דרוץ","f":"אליהו מראסלוביץ","bt":"תרמט","dt":"תרפג - י אייר","b":"תלמיד בעל \"ערוגת הבשם\" בחוסט, ר שמואל רוזנברג באונסדורף, ור יהודה גרינוולד בסטמר. חתן ר ישכר דב פרידמן מקיראי-דארוץ. דיין בכפר אלשו-סופור ליד טשאנד. רב בקיראי-דארוץ-תרפב על מקום חותנו שעבר לקרולה. נפטר צעיר."},{"i":26750,"n":"כץ, פנחס יצחק הכהן מפולדא","f":"נפתלי - סמיכת חכמים","b":"רב בפולדא, קרזמיר-תצ. הסכים על \"דמשק אליעזר\". בנו ר שמשון הכהן."},{"i":26751,"n":"כץ, פנחס מסטניסלב","b":"דיין בסטניסלב לפני השואה."},{"i":26752,"n":"כץ, פנחס מרדומישל","f":"מאיר","b":"רב ברדומישל על מקום זקנו - ר דוד מגיד, בנו ר דוד צבי על מקומו אחריו."},{"i":26753,"n":"כץ, פסח יהודה מסעקעלהיד","f":"שבתי","bt":"תקצא","dt":"תרנה - ח אדר","b":"תלמיד הכת\"ס, רב באלמאשד, סעקעלהיד והגליל-תרכח."},{"i":26754,"n":"כץ, פסח מלויצק","f":"תנחום כץ","b":"רב בלאצק(=לוצק)-שנת ת'. בנו - ר משה מסלוצק ולוצק."},{"i":26755,"n":"כץ, צבי הירש","f":"יוסף","k":"בעל עטרת צבי","b":"רב - שנות ה-ש'-ת'. חיבר גם \"נחלת צבי\" על השו\"ע - קראקא תו."},{"i":26756,"n":"כץ, צבי הירש מזולקוא","f":"יעקב יחיאל","b":"מחכמי זולקוא, חתם-שפו על תקנת הקהלה."},{"i":26757,"n":"כץ, צבי הירש מלבוב","f":"אברהם","b":"ספרא ודיינא בלבוב בזמן ר חיים רפפורט. חתם-תקד בפנקס הקהלה, חתם-תקיא עם ר אריה ליב רפפורט, ר יוסף בן מנחם מאניש סגל מלבוב, ועוד."},{"i":26758,"n":"כץ, צבי הירש מצפת","b":"גבאי בקהלת הפרושים בצפת-תקעה יחד עם ר ישראל משקלוב."},{"i":26759,"n":"כץ, קויפמן מזולצבך","b":"רב בזולצבך-תק\"מ"},{"i":26760,"n":"כץ, ראובן מליטא ופתח תקוה","f":"שמעון הכהן מאלשאן","k":"בעל דגל ראובן","bt":"תרם","bp":"אולשאן-פלך וילנא","dt":"תשכד - יז חשון","dp":"פתח תקוה","b":"תלמיד ישיבות איווייה, מיר, ראדין, סלובודקה, וסלוצק (מ-14 הבחורים שעברו לשם עם ר איסר זלמן מלצר), ולמד בקיבוץ ר חיים עוזר גודזנסקי בוילנא. חתן ר אברהם יצחק משכיל לאיתן מחסלביץ. רב בסליב(=סעליב)-פלך מינסק-תרסה, אמדור-תרסט, ראש ועד העזרה במחוז גרודנא-לאחר מלחה\"ע ה-I, רב בסטאויסק-תרפג, לבקשת החפץ חיים יצא בראש משלחת רבנים בארה\"ב-תרפט ונשאר שם לכהן כרב ביון-ניו ג'רסי, וסגן נשיא אגודת הרבנים בארה\"ב. רב ראשי בפתח תקוה-תרצב, ומנהל ישיבת לומז'ה שם. ממייסדי \"ועד הישיבות\" בא\"י. פרסם מאמרים ב\"בית מדרש\" - תל אביב תשא, \"יגדיל תורה\" - סלוצק-בוברויסק תרסט, \"כרם ציון\" - ירושלים תרצה-תשיג, תשכג - קובץ \"מדרש בני ציון\", \"המאור\" - תל אביב תרצה, פרסם מאמרים ב\"קול תורה\" - ירושלים תרץ, \"השער\" - בני ברק תשח, \"תורת ארץ ישראל\" - ירושלים תרץ.","bk":[["דגל ראובן - שו\"ת",""],["דודאי ראובן - על התורה",""],["שער ראובן - מאמרים",""],["דגל ראובן",""]]},{"i":26761,"n":"כץ, ראובן מסטאויסק וארה\"ב","b":"רב בסטאויסק, עבר לארה\"ב וכיהן כרב בביאן-נידזאדזשע-תרפד."},{"i":26762,"n":"כץ, ראובן מפרג","k":"בעל ילקוט ראובני","r":"אדמו\"ר הראשון מסקוירא","dt":"תלג - יז ניסן","b":"מקובל,דרשן,סופר,מגדולי חכמי פרג","bk":[["ילקוט הראובני",""]]},{"i":26763,"n":"כץ, שאול מזידיטשוב","b":"רב בזידיטשוב-תרם."},{"i":26764,"n":"כץ, שאלתיאל","f":"נפתלי - סמיכת חכמים"},{"i":26765,"n":"כץ, שבתי מאורלא ושנאדאווה","f":"בנימין בישקא מאורלי","k":"בעל שבת אחים","dt":"תקפ - ו אלול","b":"רב בשנאדאווה, אורלע(=אורלי). נכד אחיו הו\"ל מתורתו ומתורת אחיו - ר נחמן מאורלי(=אורלא) בשם \"שבת אחים\" וילנא תקצג. בנו - ר ישראל."},{"i":26766,"n":"כץ, שבתי מלעוורדן","dt":"תקס","b":"רב בלעווערדען"},{"i":26767,"n":"כץ, שלום שכנא מקראקא","f":"אברהם חיים","k":"בעל משפט שלום","dt":"תקצט - ב סיון","b":"דיין בקראקא. חיבר \"שלמי נזיר\" קראקא תקפא."},{"i":26768,"n":"כץ, שלמה (שמואל) מסובאסלו","f":"משה - דברי משה","bt":"תריח","dt":"תרף - בערך","b":"תלמיד ר יואל אונגואר מפאקש בעל \"תשובת ריב\"א\". חתן ר אברהם אייבניץ קרפלס מגירבא בעל \"אהל אברהם\", ובזיוו\"ש חתן ר יעקב צבי ויסמן מסובאסלו. רב בגורבע-תרמא, סובאסלוי(=סאביסלוי)-תרנא על מקום חותנו. נסמך מאת: ר אהרן פריער בעל שו\"ת מהרא\"ף, ר פנחס קליין מסולעש. בנו - ר יעקב צבי בעל \"לקט הקמח החדש\" על מקומו אחריו-תרף."},{"i":26769,"n":"כץ, שלמה דב מנימוז'ה","f":"אהרן גד מנימוז'ה","dt":"תש..","b":"רב בנימוז'ה על מקום אביו-תשא. נספה בשואה."},{"i":26770,"n":"כץ, שלמה זלמן מגרוסורדין ונ\"י","f":"יונתן בנימין","k":"בעל שב גיטין","bt":"תרנב","bp":"צ'נגר","b":"אחיו של ר אשר אנשיל מסערדאהלי. תלמיד \"ערוגת הבשם\" בחוסט, ור שמואל רוזנברג באונסדורף. חתן ר פנחס צימטבוים מגרוסורדין, וכיהן כר\"מ בישיבת \"בית שלמה\" בגרוסורדין. היגר לארה\"ב-תרצח וכיהן כרב בניו יורק-תרצה."},{"i":26771,"n":"כץ, שלמה זלמן מלבוב","f":"שמואל","dt":"תיג - ב חשון","b":"רב בלבוב. (יש שרשמו שהיה חתן מהר\"ל מקראקא - ולדעת בובר בטעות). בנו - ר נתן הכהן ונכדו ר שלמה זלמן שחתם בפינטשוב."},{"i":26772,"n":"כץ, שלמה מבריסק","f":"נתן","b":"מחכמי בריסק-שפו."},{"i":26773,"n":"כץ, שלמה מזולקוא","f":"יוסף יוזפא בן הסמ\"ע","k":"בעל תפארת הקדש?","b":"נכד הסמ\"ע. מחכמי זולקוא, חתם-תמ על תקנת הקהל."},{"i":26774,"n":"כץ, שלמה מפרוזנא","f":"ישראל","b":"אב\"ד בפרוזנא. הסכים-תקצב על \"אבות דרבי נתן\" לר אליהו בן אברהם מדליטיץ."},{"i":26775,"n":"כץ, שלמה מקראקא ושטקטשין","f":"זאב דוב כץ","dt":"תריח - יא אדר","b":"חריף,מרביץ תורה,רב בשטעקטשין,ראב\"ד בקרקא"},{"i":26776,"n":"כץ, שלמה משארוואר","dt":"תקמו - טו אב","b":"רב בשארוואר"},{"i":26777,"n":"כץ, שמואל הכהן מהעדיעס","f":"מנחם מהעדיעס","b":"תלמיד הכת\"ס, ור ישראל דוד יפה מרגליות מפעזינג."},{"i":26778,"n":"כץ, שמואל מאיר מצעהלים פרוסטיץ","f":"מנחם פרוסטיץ כץ מצעל","k":"בעל שם משמואל","bt":"תקץ","bp":"פרשבורג","dt":"תרלה - כט אב","dp":"צעהלים","b":"תלמיד הכת\"ס. מחכמי צעהלים. נפטר בצעירותו."},{"i":26779,"n":"כץ, שמואל מוינה ונציה ירושלים","f":"יוזפה כץ","k":"בעל לקט שמואל","b":"מקובל,סופר העיר בווינה,עבר לויניציאה בגירוש-ת\"ל,עלה לירושלים"},{"i":26780,"n":"כץ, שמואל מזשיבא","b":"חתן ר משה פרנקל מזשיבא. רב בזשיבא. מונטריאול."},{"i":26781,"n":"כץ, שמואל מנחם הלוי מפלנגאן","f":"חיים מפומפיאן-עונג ח","k":"המגיד מקורלנד","bt":"תרמח","bp":"ז'וסלי","dt":"תשיד - יב תמוז","dp":"תל אביב","b":"חתן הגביר ר פנחס מראזאליא. תלמיד ישיבית סלובודקה. רב בוילון, רוגאצ'וב, פלנגאן(=פולאנגן) (לא פלונגיאן) ובנו ר אהרן יצחק כץ על מקומו אחריו, אחרי השריפה הגדולה-תרצח דאג לשיקום העיר, עלה לארץ-תש, וכיהן כרב ודיין בתל אביב. חבוריו בהלכה נשרפו-תרצח. בנו אברהם איסר - נרצח ע\"י הערבים בחניתה במאורעות תרצו - וע\"ש נקרא ישוב בארץ."},{"i":26782,"n":"כץ, שמואל מרדכי מבוריסלב","b":"נכד מהרם מלובלין. פוליען-ריסוקבה. חתן ר יחיאל מיכל היבנר מניזנוב-תרכט."},{"i":26783,"n":"כץ, שמואל שמלקא מברסלא","f":"נפתלי - סמיכת חכמים","b":"רב בברסלוי-תפד. הסכים על \"יפה מראה\". בנו ר חיים מגלוגא."},{"i":26784,"n":"כץ, שמואל שרגא מאושפיצין","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":26785,"n":"כץ, שמעון מקובין","dt":"תרט - כ תמוז","b":"רב בקובין"},{"i":26786,"n":"כץ, שמעיה מסעמיהאל","b":"רב בסעמיהאל-תרכ\"ו"},{"i":26787,"n":"כץ, שמריה (שמרל) הכהן מלבוב","dt":"תסג - ד כסלו","dp":"לבוב","b":"מגיד בלבוב. נינתו - אשת בעל פני יהושע. נהרג במפולת בלבוב עם 36 נפשות מישראל."},{"i":26788,"n":"כץ, שמריהו הלוי מויז'ון","f":"חיים מפומפיאן-עונג ח","bt":"תרלח","dt":"תרעט - אלול","b":"חתן ר אלעזר דון יחיא מלוצין בעל \"אבן שתיה\". אב\"ד ויז'ון-תרסג, ווישניוואלאצק-תרעו."},{"i":26789,"n":"כץ, שמשון","f":"פנחס יצחק","b":"נכד ר נפתלי בעל \"סמיכת חכמים\". הניח חבור בכת\"י בשם \"מסכת שמשון\" ובו גם ליקוטים מאביו וזקנו."},{"i":26790,"n":"כץ, תנחום מקראקא","f":"יוסף - שארית יוסף","dt":"שעה - כז טבת","dp":"קראקא","b":"דיין בקראקא. אחיו - ר אהרן משה."},{"i":26791,"n":"כץ-גולדמן, יוסף אלימלך מבסרמין","b":"דומ\"צ בבסרמין-תר\"מ"},{"i":26792,"n":"כץ-הלפרן, ישעיה משברשין","f":"אליעזר ליפמן הלפרן","b":"רב בשברשין-ת\"ק"},{"i":26793,"n":"כצמן, אשר","b":"תלמיד ר דוד הכהן רפפורט בעל 'מקדש דוד'. ר\"מ בישיבת 'תורה ודעת', חיבר מאמר לזכר רבו בקובץ 'אלה אזכרה'."},{"i":26794,"n":"כצמן, גרשון הכהן מפוחאביץ","k":"בעל הגיונות הגרשוני","b":"רב בפוחאוויץ, סן פרנציסקו."},{"i":26795,"n":"כצקלס, הלנה","k":"בעל די נאטור ארום או","bt":"1882","bp":"קובנא","b":"פעילה בבונד, מחנכת ועורכת תכנית להוראת מדעי הטבע. מורה בסמינר למורים של שמואל לוין בקובנא. ביקרה בארצות רבות ובהם בא\"י ותיארה את רשמיה במאמרים וחוברות. בזמן השואה היתה בסטלינגרד, ב-1944 חזרה לקובנא והתמסרה לחינוך יתומי שואה. חיברה גם \"פינלנד\", ועוד. תרגמה ספרי ילדים."},{"i":26796,"n":"כרבשא, יוסף מפאס","b":"מחכמי פאס-שנות ה-ר', נזכר ב\"חוט המשולש\" לר\"ש צרור."},{"i":26797,"n":"כרוב, חיים מלארסו","b":"גביר בלארסו, מכתב ממנו-תעא לר שלמה אברבנל-חתנו של ר יעקב די בוטון. משפחת כרוב נזכרת בספר בניהו על יחסי יהודי יון ויהודי איטליה."},{"i":26798,"n":"כרוב, יוסף מאיטליה","f":"אברהם","b":"רב באיטליה-של בזמן ר יחיאל טרבוט."},{"i":26799,"n":"כרוב, שלמה מאגאדיר-מרוקו","b":"מחכמי אגדיר(=אגאדיר)-מרוקו, חתם-תצה על פס\"ד עם ר דוד בן אשר ן צור."},{"i":26800,"n":"כרופ, שלמה מיעזרנה","k":"אדמור מיעז'רנה","b":"בן למשפחה פשוטה, ולפתע נתפרסם והמונים נהרו אליו."},{"i":26801,"n":"כרייף, אברהם ממכנאס","dt":"תקסה - טז אב","b":"מחכמי מכנאס. קינה לזכרו ב\"קול יעקב\"."},{"i":26802,"n":"כרייף, בנימין ממכנאס","f":"יחיא","k":"בעל גבול בנימין","b":"נכד-בן בתו ר משה בירדוגו-המשבי\"ר, חתן ר דוד ן חסין בעל \"תהלה לדוד\". מו\"ץ במכנאס-תקנח. תלמיד ר' רפאל בירדוגו, חתן המשורר, ר' דוד בן חסין, חיבר שו\"ת \"גבול בנימין\""},{"i":26803,"n":"כרייף, יחיא ממכנאס","f":"יחיא","b":"נקרא על שם אביו. מחכמי מכנאס, חתם בהקדמת \"ראש משביר\"-תר."},{"i":26804,"n":"כרייף, יחיא ממכנאס - הזקן","b":"מחכמי מכנאס. בנו - ר בנימין בעל \"גבול בנימין\"."},{"i":26805,"n":"כרייף, יחיא ממכנאס-הנכד","f":"בנימין","b":"מחכמי מכנאס-תקצט."},{"i":26806,"n":"כרייף, משה מתונס","k":"בעל שיטות על הש\"ס","b":"תלמיד ר צמח צרפתי, ור יצחק למברוזו. למד ביחד עם ר דוד בונאן אב\"ד פורטוגזים בתונס. חיבר שיטה שהדפיסה חברו רד\"ב בעזרת הקאייד נסים שמאמא. מנכדיו - ר אברהם כהן יצחקי בעל \"משמרות כהונה\", ר משה שאלתיאל שסייעו בהדפסת ספרו."},{"i":26807,"n":"כרייף, שלם ממרוקו","f":"יהודה","b":"מחכמי מרוקו, חתם-תעז על פס\"ד עם ר יהודה הלוי."},{"i":26808,"n":"כריסדה, עמרם מלוב","bt":"תק","dt":"תקע - בערך","b":"רב בלוב. הניח חדושים בכת\"י, והיו בידי ההיסטוריון - ישראל בלוב, ונזכר אצל ר גבריאל רוקח."},{"i":26809,"n":"כריסטינפולר מאיר","bt":"1740","dt":"ה'תקסה 1805","bk":[["יד המאיר",""]]},{"i":26810,"n":"כרמולי אליקים","bt":"1802","dt":"ה'תרלה 1875","bk":[["אגודת אגדות",""],["דברי הימים לבני יחייא",""],["העורבים ובני יונה",""],["חקקי אבן",""],["מבשרת ציון",""],["תולדות גדולי ישראל",""]]},{"i":26811,"n":"כרמי, אברהם","b":"רב ודיין-ת\"ק"},{"i":26812,"n":"כרמי, יהודה דוד מקרפנטרץ","b":"רב בקארפינטרץ"},{"i":26813,"n":"כרמי, יוסף","b":"מגדולי רבני איטליה-תקל\"ה"},{"i":26814,"n":"כרמי, יוסף ידידיה מאיטליה","k":"בעל כנף רננים","b":"מגדולי חכמי איטליה-ש\"ס"},{"i":26815,"n":"כרמי, מרדכי מקרפנטרץ","f":"אברהם","k":"בעל מאמר מרדכי","b":"רב בקרפנטרץ-תקלז, וחיבר \"מאמר מרדכי\" ובו השיג הרבה על החיד\"א, (שפגשו גם בקרפנטרץ וגם בליוורנו), ושהסכים על ספרו, למרות שלא עבר עליו. החיד\"א השיב לו בספרו \"מחזיק ברכה\", ר מרדכי חיבר \"דברי מרדכי\" כנגד \"מחזיק ברכה\". ר אברהם בלעיש מתונס שכיהן כרב בניצה-צרפת, השיב לר מרדכי ב\"יד אבישלום\"."},{"i":26816,"n":"כרמי, שלמה חיים מליוורנו","f":"אברהם כרמי","k":"בעל חשק שלמה","b":"מחכמי ליוורנו-תק, אחיו של ר מרדכי כרמי בעל \"מאמר מרדכי\" וכתב הקדמה לספר אחיו."},{"i":26817,"n":"כרמייה, יצחק אהרן אדולף מצרפת","f":"משה","bt":"תקנו","bp":"ניס-צרפת","dt":"תרם - כט שבט","dp":"פריס","b":"ראש תנועת \"אליאנס\" בצרפת - שפעלה למען השכלה בקהלות המזרח, וחברת כי\"ח. פרסם מאמרים ב\"כבוד הלבנון\" - ירושלים-פאריס תרכג-תרמב."},{"i":26818,"n":"כרמל, מנשה מקראקא","bt":"תקעב","dt":"תרמה","b":"רב בקראקא."},{"i":26819,"n":"כרמלי, ברוך מעזה","b":"רב בעזה-תך אצל ר יעקב נג'ארה."},{"i":26820,"n":"כרסנתי, בוי יזו","b":"מחכמי מרוקו, מקובל"},{"i":26821,"n":"כרסנתי, שלמה דון מליסבון","b":"רופא בליסבון, אחר הגירוש הגיע לתורכיה. ניסה לפשר במחלוקת באבילונה-אלבניה בין קהלת קשטיליה לקהלת פורטוגל."},{"i":26822,"n":"כרפס, יעקב משה","b":"גביר בקובנא, ועוסק בחסד והכנסת אורחים. ידידו של ר ישראל סלנט שהיה מתארח אצלו, וכן סייע לגדול ממינסק שהתגורר אצלו בהיותו בקובנא."},{"i":26823,"n":"כשדאי, צבי","k":"בעל קטעי זכרונות","bt":"1865","bp":"דובובה-פלך קיוב","dt":"1937","b":"סופר."},{"i":26824,"n":"כשר, מנחם מנדל מוארשא","k":"בעל תורה שלמה","b":"רב בוארשא. מראשי ישיבת מנישביץ בירושלים (ישיבה שהוחזקה בידי משפחת מנישביץ מארה\"ב). עורך \"דגל התורה\" וארשא תרפא. פרסם מאמרים ב\"בית תלמוד\" - ירושלים תרצב, \"כרם ציון\" - ירושלים תשכג - קובץ \"מדרש בני ציון\", \"המאור\" - תל אביב תרצה, \"סיני\" - ירושלים תרצז, \"תלפיות\" - נ\"י תשד."},{"i":26825,"n":"כשר, שמעון","f":"מנחם מנדל מוארשא","k":"בעל סולמות לרום","bt":"תרעד","dt":"תשכח - ו תמוז","b":"משורר, עלה לארץ-תרפה."},{"i":26826,"n":"כתב יד פארמה די רוססי","bk":[["מחזור ספרדי לר\"\"ה ויום כפור משנת 1320",""]]},{"i":26827,"n":"כתבן, אבנר מסניאטין","k":"בעל אבל משה","bt":"תקצא","bp":"סניאטין","dt":"תרנח","b":"רב בסאניווץ, מיהאלן, פנטשיא, בראילה-תרכז, קריובה-ואלאכיה, רימניק-סרעט. חיבר \"אבל משה\" ראדוויץ תרמה."},{"i":26828,"n":"כתריאל יצחק","f":"ראובן אמסציסלאווער","dt":"תרמג - כד אדר"},{"i":26829,"n":"כתריאל מקושטא","f":"יקותיאל","k":"שלמה משאמאוו","b":"מדפיס אצל אברהם פרנקו תח."},{"i":26830,"n":"כתריאל מקלוש","f":"יעקב","b":"רב בקלוש, סקאלא."},{"i":26831,"n":"כתריאל מקראקא","b":"רב בקראקא-שנז, נזכר בסדר הדורות."}];
